function settingsSectionLabel(section = settingsSection) {
    return settingsLeafTab(section)?.label
        || settingsCategoryTab(section)?.label
        || settingsLeafTab(settingsCategoryChildren(settingsActiveCategory(section))[0]?.id)?.label
        || 'Workspace Settings';
}

function settingsCategoryCounts(leafCounts = {}) {
    return SETTINGS_CATEGORY_TABS.reduce((counts, category) => {
        const children = SETTINGS_CATEGORY_CHILDREN[category.id] || [];
        counts[category.id] = children.reduce((sum, childId) => sum + Number(leafCounts[childId] || 0), 0);
        return counts;
    }, {});
}

