function setAutomationFilter(kind, value) {
    automationFilters[kind] = value || 'all';
    render();
}

function setAutomationSearch(value) {
    automationFilters.q = value || '';
}

function applyAutomationFilters() {
    render();
}

function clearAutomationFilters() {
    automationFilters = { package: 'all', service: 'all', project: 'all', owner: 'all', status: 'all', channel: 'all', type: 'all', q: '' };
    render();
}

async function refreshAutomations() {
    automationNotice = '';
    await loadData({ background: true });
}

async function toggleAutomationDetail(event, id) {
    if (event) event.stopPropagation();
    const key = String(id);
    if (String(expandedAutomationId) === key) {
        expandedAutomationId = null;
        render();
        return;
    }
    expandedAutomationId = key;
    if (!automationDetailCache[id]) {
        automationDetailLoading[id] = true;
        render();
        try {
            automationDetailCache[id] = await api.getAutomation(id);
        } catch (error) {
            automationNotice = error.message || 'Unable to load automation detail.';
        } finally {
            automationDetailLoading[id] = false;
        }
    }
    render();
}

async function saveAutomationMetadata(event, id) {
    event.preventDefault();
    const form = event.currentTarget;
    const data = new FormData(form);
    let permissions = {};
    try {
        const rawPermissions = String(data.get('permissions') || '').trim();
        permissions = parseAutomationPermissionsInput(rawPermissions);
    } catch (error) {
        automationNotice = 'Permission rules must use key: value lines or valid JSON before saving.';
        render();
        return;
    }
    const setupBlockers = String(data.get('setup_blockers') || '')
        .split(/\r?\n/)
        .map(item => item.trim())
        .filter(Boolean);
    const relatedTaskIds = String(data.get('related_task_ids') || '')
        .split(/[,\s]+/)
        .map(value => Number(value))
        .filter(Number.isFinite);
    const payload = {
        owner: data.get('owner') || '',
        responsible_person: data.get('responsible_person') || '',
        status: data.get('status') || 'draft',
        automation_type: data.get('automation_type') || 'workflow',
        channel: data.get('channel') || '',
        next_run_at: data.get('next_run_at') || null,
        summary: data.get('summary') || '',
        description: data.get('description') || '',
        trigger_label: data.get('trigger_label') || '',
        audience: data.get('audience') || '',
        setup_blockers: setupBlockers,
        related_task_ids: relatedTaskIds,
        permissions,
    };
    try {
        const result = await api.updateAutomation(id, payload);
        if (result?.automation) {
            automations = automations.map(row => Number(row.id) === Number(id) ? result.automation : row);
            automationDetailCache[id] = { ...(automationDetailCache[id] || {}), automation: result.automation };
        }
        automationNotice = 'Automation metadata saved.';
        await loadData({ background: true });
    } catch (error) {
        automationNotice = error.message || 'Unable to save automation metadata.';
        render();
    }
}

function taskAgentControlEnabled() {
    return opsMe?.scope?.type === 'all' && allowedViews().has('agents');
}

function communicationAgentsViewActive(workspaceKey = currentWorkspaceKey()) {
    return currentView === 'agents' && currentWorkspaceIsOneTime(workspaceKey);
}

function communicationAgentTabIsValid(tabId) {
    return COMMUNICATION_AGENT_TABS.some(tab => tab.id === tabId);
}

function agentRunStatusLabel(status) {
    return ({
        draft: 'Draft',
        ready: 'Ready',
        claimed: 'Claimed',
        running: 'Running',
        waiting_operator: 'Needs Operator',
        submitted: 'Submitted',
        sealed_pass: 'Sealed Pass',
        sealed_fail: 'Sealed Fail',
        blocked: 'Blocked',
        expired: 'Expired',
        cancelled: 'Cancelled'
    })[String(status || '').toLowerCase()] || String(status || 'Unknown').replace(/_/g, ' ');
}

function agentRunIsTerminal(run = {}) {
    return ['sealed_pass', 'sealed_fail', 'blocked', 'expired', 'cancelled'].includes(String(run.status || '').toLowerCase());
}

function agentRunTabId(run = {}) {
    const status = String(run.status || '').toLowerCase();
    if (['draft', 'ready'].includes(status)) return 'ready';
    if (['claimed', 'running'].includes(status)) return 'running';
    if (['waiting_operator', 'blocked'].includes(status)) return 'needs_operator';
    if (status === 'submitted') return 'needs_verification';
    if (status === 'sealed_fail') return 'failed';
    if (['sealed_pass', 'expired', 'cancelled'].includes(status)) return 'completed';
    return 'ready';
}

function agentRunSubnavCounts() {
    const counts = { ready: 0, running: 0, needs_operator: 0, needs_verification: 0, failed: 0, completed: 0, all: agentRuns.length };
    agentRuns.forEach(run => {
const tab = agentRunTabId(run);
counts[tab] = Number(counts[tab] || 0) + 1;
    });
    return counts;
}

function communicationAgentSubnavCounts() {
    const payload = communicationAgentsPayload || {};
    const agents = Array.isArray(payload.agents) ? payload.agents : [];
    const channelCount = agents.reduce((count, agent) => count + (Array.isArray(agent.channels) ? agent.channels.length : 0), 0);
    return {
knowledge: Array.isArray(payload.knowledge_sources) ? payload.knowledge_sources.length : 0,
channels: channelCount,
test: payload.test_panel ? 1 : 0,
activity: Array.isArray(payload.activity) ? payload.activity.length : 0
    };
}

function filteredAgentRuns() {
    const tab = AGENT_RUN_TABS.some(item => item.id === agentRunsTab) ? agentRunsTab : 'ready';
    if (tab === 'all') return agentRuns;
    return agentRuns.filter(run => agentRunTabId(run) === tab);
}

function agentRunByKey(runKey) {
    const key = String(runKey || '');
    return agentRuns.find(run => String(run.run_key || '') === key) || (String(agentRunDetail?.run_key || '') === key ? agentRunDetail : null);
}

function agentRunForTask(task = {}) {
    const taskId = Number(task.id || 0);
    if (!taskId) return null;
    const activeId = Number(task.active_agent_run_id || 0);
    return agentRuns.find(run => Number(run.task_id || 0) === taskId && activeId && Number(run.id || run.run_id || 0) === activeId)
        || agentRuns.find(run => Number(run.task_id || 0) === taskId && !agentRunIsTerminal(run))
        || agentRuns.find(run => Number(run.task_id || 0) === taskId)
        || null;
}

function agentRunCriteria(run = {}) {
    const criteria = Array.isArray(run.acceptance_criteria) ? run.acceptance_criteria : parseJsonField(run.acceptance_criteria) || [];
    return criteria.length ? criteria : [{ id: 'AC-1', label: 'Verify the requested work against the task notes and visible result.', required: true }];
}

function agentRunPromptText(run = {}) {
    return String(run.prompt_text || run.prompt || '').trim();
}

function agentRunSummaryRows(run = {}) {
    return [
        ['Status', agentRunStatusLabel(run.status)],
        ['Task', run.task_id ? `#${run.task_id} ${run.task_display_title || run.task_title || ''}` : 'No linked task'],
        ['Workspace', run.project_short_name || run.project_name || run.project_key || 'BNA'],
        ['Agent', run.agent_display_name || run.agent_key || 'Agent'],
        ['Mode', String(run.verification_mode || '').replace(/_/g, ' ') || 'mixed'],
        ['Evidence', `${Number(run.artifact_count || 0)} artifact${Number(run.artifact_count || 0) === 1 ? '' : 's'}`],
        ['Events', `${Number(run.event_count || 0)} event${Number(run.event_count || 0) === 1 ? '' : 's'}`],
        ['Updated', formatDateTime(run.updated_at) || 'Not recorded'],
    ];
}

function scopedAgentWorkTasks() {
    return tasks
        .filter(task => {
            const agentStatus = String(task.agent_status || '').toLowerCase();
            return taskIsMachine(task)
                || ['queued', 'running', 'completed', 'failed', 'blocked_needs_human_decision', 'needs_verification'].includes(agentStatus)
                || Number(task.active_agent_run_id || 0) > 0;
        })
        .slice()
        .sort(sortTasks);
}

function scopedAgentStatusCounts(items = scopedAgentWorkTasks()) {
    return items.reduce((counts, task) => {
        const status = String(task.agent_status || '').toLowerCase();
        if (status === 'queued') counts.queued += 1;
        else if (status === 'running') counts.running += 1;
        else if (status === 'failed') counts.failed += 1;
        else if (status === 'blocked_needs_human_decision') counts.blocked += 1;
        else if (status === 'completed') counts.completed += 1;
        else if (status === 'needs_verification') counts.needsVerification += 1;
        else counts.tracked += 1;
        return counts;
    }, { queued: 0, running: 0, blocked: 0, failed: 0, completed: 0, needsVerification: 0, tracked: 0 });
}

function renderScopedAgentStatus() {
    const workItems = scopedAgentWorkTasks();
    const counts = scopedAgentStatusCounts(workItems);
    const queue = agentFleetStatus?.queue || {};
    const fleet = agentFleetStatus?.fleet || {};
    const visibleItems = workItems.slice(0, 12);
    return `
        <div class="container agent-control-center" data-scoped-agent-status>
            <div class="page-heading task-heading">
                <div>
                    <div class="page-kicker">One Time Agent Status</div>
                    <h2>Agent Work</h2>
                    <p>Scoped machine work, queue heartbeat, verification handoffs, and blockers for the One Time workspace.</p>
                </div>
                <div class="task-actions">
                    <button class="task-action primary" type="button" onclick="loadData({ background: true })">Refresh</button>
                    <button class="task-action" type="button" onclick="openCommandTarget('tasks', 'codex_queue')">Codex Queue</button>
                    <button class="task-action" type="button" onclick="openCommandTarget('tasks', 'tasks')">Open Tasks</button>
                </div>
            </div>
            <section class="focus-panel compact-panel">
                <div class="task-section-header">
                    <div>
                        <h3>Queue Heartbeat</h3>
                        <span>${escapeHtml(fleet.last_seen_at ? `Last seen ${formatDateTime(fleet.last_seen_at)}` : Number(queue.pending ?? counts.queued) > 0 ? 'Stored; worker offline' : 'No worker heartbeat loaded')}</span>
                    </div>
                    <span class="page-status-pill">${escapeHtml(String(fleet.status || 'unknown').replace(/_/g, ' '))}</span>
                </div>
                <div class="metric-grid">
                    ${renderMetricButton('Queued', Number(queue.pending ?? counts.queued), 'One Time machine work waiting.', "openCommandTarget('tasks', 'codex_queue')")}
                    ${renderMetricButton('Running', Number(queue.in_progress ?? counts.running), 'One Time machine work in progress.', "openCommandTarget('tasks', 'codex_queue')")}
                    ${renderMetricButton('Needs Review', counts.needsVerification, 'Submitted work awaiting verification.', "openCommandTarget('tasks', 'codex_queue')")}
                    ${renderMetricButton('Blocked', counts.blocked, 'Machine work waiting on a human or external dependency.', "openCommandTarget('tasks', 'pending')")}
                </div>
            </section>
            <section class="task-board agent-run-board" aria-label="Scoped agent work">
                ${visibleItems.length ? visibleItems.map(task => `
                    <article class="task-card agent-run-card">
                        <div class="task-card-main">
                            <div class="task-row-meta">
                                <span class="task-type-badge">${escapeHtml(String(task.agent_status || 'tracked').replace(/_/g, ' '))}</span>
                                <span class="badge">${escapeHtml(taskProjectLabel(task))}</span>
                                <span class="badge">${escapeHtml(taskStageLabel(task))}</span>
                            </div>
                            <h3>#${Number(task.id || 0)} ${escapeHtml(taskDisplayTitle(task))}</h3>
                            <p>${escapeHtml(limitTextClient(task.notes || task.description || 'One Time agent-status task.', 220))}</p>
                        </div>
                        <div class="task-row-actions">
                            <button class="task-action primary" type="button" onclick="openTaskDetail(event, ${Number(task.id || 0)})">Open Task</button>
                        </div>
                    </article>
                `).join('') : '<div class="task-empty">No One Time agent work is queued or running right now.</div>'}
            </section>
        </div>
    `;
}

function communicationAgentChannels(payload = communicationAgentsPayload || {}) {
    const agents = Array.isArray(payload.agents) ? payload.agents : [];
    return agents.flatMap(agent => (Array.isArray(agent.channels) ? agent.channels : []).map(channel => ({
...channel,
agent_display_name: agent.display_name || agent.agent_key || 'Communication agent'
    })));
}

function communicationAgentPublicFactsRows(source = {}) {
    const facts = source.approved_public_facts || {};
    return Object.entries(facts).slice(0, 6).map(([key, value]) => {
const rendered = Array.isArray(value)
    ? value.join(', ')
    : value && typeof value === 'object'
        ? JSON.stringify(value)
        : String(value || '');
return [key.replace(/_/g, ' '), limitTextClient(rendered, 180)];
    });
}

