async function loadFirstPartyCrmContacts(event, options = {}) {
    if (event) event.preventDefault();
    const filters = firstPartyCrmQueryFilters();
    const queryKey = firstPartyCrmQueryKey(filters);
    if (!options.force && firstPartyCrmContactsCache.has(queryKey)) {
        firstPartyCrmContactsPayload = firstPartyCrmContactsCache.get(queryKey);
        firstPartyCrmError = '';
        firstPartyCrmLoading = false;
        updateFirstPartyCrmPanel();
        return;
    }
    if (firstPartyCrmContactsAbortController) firstPartyCrmContactsAbortController.abort();
    const requestSeq = firstPartyCrmContactsRequestSeq + 1;
    firstPartyCrmContactsRequestSeq = requestSeq;
    const controller = new AbortController();
    firstPartyCrmContactsAbortController = controller;
    firstPartyCrmLoading = true;
    firstPartyCrmError = '';
    updateFirstPartyCrmPanel();
    try {
        const payload = normalizeFirstPartyCrmPayload(await api.getCrmContacts(filters, { signal: controller.signal }));
        if (controller.signal.aborted || requestSeq !== firstPartyCrmContactsRequestSeq) return;
        firstPartyCrmContactsPayload = payload;
        firstPartyCrmContactsCache.set(queryKey, payload);
        const cards = Array.isArray(payload.cards) ? payload.cards : [];
        if (selectedFirstPartyCrmContactId && !cards.some(card => String(card.id) === String(selectedFirstPartyCrmContactId))) {
            selectedFirstPartyCrmContactId = null;
            firstPartyCrmTimelinePayload = null;
            firstPartyCrmConversationsPayload = null;
            firstPartyCrmTasksPayload = null;
            syncOperationsUrl();
        } else if (selectedFirstPartyCrmContactId && !firstPartyCrmDetailPayloadLoaded(firstPartyCrmActiveTab) && !firstPartyCrmTimelineAbortController) {
            await openFirstPartyCrmContact(selectedFirstPartyCrmContactId, { captureScroll: false, syncUrl: false });
        }
    } catch (error) {
        if (isAbortError(error)) return;
        firstPartyCrmError = error.message || 'Could not load CRM contacts.';
        firstPartyCrmContactsPayload = null;
    } finally {
        if (requestSeq === firstPartyCrmContactsRequestSeq) {
            firstPartyCrmLoading = false;
            firstPartyCrmContactsAbortController = null;
            updateFirstPartyCrmPanel();
        }
    }
}

async function openFirstPartyCrmContact(contactId, options = {}) {
    if (options.captureScroll !== false) captureFirstPartyCrmListScroll();
    selectedFirstPartyCrmContactId = contactId;
    firstPartyCrmTimelinePayload = null;
    firstPartyCrmConversationsPayload = null;
    firstPartyCrmTasksPayload = null;
    if (firstPartyCrmTimelineAbortController) firstPartyCrmTimelineAbortController.abort();
    const requestSeq = firstPartyCrmTimelineRequestSeq + 1;
    firstPartyCrmTimelineRequestSeq = requestSeq;
    const controller = new AbortController();
    firstPartyCrmTimelineAbortController = controller;
    if (options.syncUrl !== false) syncOperationsUrl();
    updateFirstPartyCrmPanel();

    if (requestSeq === firstPartyCrmTimelineRequestSeq) {
        firstPartyCrmTimelineAbortController = null;
    }
    await loadFirstPartyCrmSubviewData(contactId, firstPartyCrmActiveTab, { renderLoading: false });
}

function clearFirstPartyCrmSelection(event) {
    event?.preventDefault?.();
    selectedFirstPartyCrmContactId = null;
    firstPartyCrmTimelinePayload = null;
    firstPartyCrmConversationsPayload = null;
    firstPartyCrmTasksPayload = null;
    firstPartyCrmActiveTab = 'activity';
    if (firstPartyCrmTimelineAbortController) {
        firstPartyCrmTimelineAbortController.abort();
        firstPartyCrmTimelineAbortController = null;
    }
    syncOperationsUrl();
    updateFirstPartyCrmPanel();
}

async function openFirstPartyCrmInboxContext(contactId = '') {
    if (contactId) selectedFirstPartyCrmContactId = contactId;
    emailInboxScope = window.BnaCrmInbox?.scopeForWorkspace?.('rabbi_sheller_provider') || 'rabbi';
    currentWorkspaceId = 'rabbi_sheller_provider';
    taskProjectFilter = 'one_time_mishnah_class';
    currentView = 'communications';
    communicationsSection = 'email';
    syncOperationsUrl();
    rerenderOperationsApp();
    await loadData({ background: true });
}

function firstPartyCrmWapiPhonebookKey(card = {}, item = {}) {
    const candidates = [
        item.thread_key,
        item.from_address,
        item.to_address,
        card.phone,
        card.whatsapp,
    ];
    for (const value of candidates) {
        const raw = String(value || '').trim();
        if (!raw) continue;
        if (/^phone:\d+$/i.test(raw)) return raw.toLowerCase();
        if (/^chat:[^\s]+$/i.test(raw)) return raw.toLowerCase();
        const tokens = phoneTokenVariantsClient(raw);
        if (tokens.length) return `phone:${tokens[0]}`;
    }
    return '';
}

async function openFirstPartyCrmConversationThread(event, contactId = '', conversationId = '', preferredChannel = '') {
    event?.preventDefault?.();
    const card = selectedFirstPartyCrmCard() || {};
    const item = (firstPartyCrmConversationsPayload?.conversations || [])
        .find(entry => String(entry.id || '') === String(conversationId || '')) || {};
    const actionChannel = firstPartyCrmConversationActionChannel(item) || String(preferredChannel || '').toLowerCase();
    if (!actionChannel) return;
    const workspaceKey = card.workspace_key || currentWorkspaceKey() || 'rabbi_sheller_provider';
    const projectKey = card.project_key || projectKeyForWorkspaceKey(workspaceKey) || taskProjectFilter || 'one_time_mishnah_class';
    if (contactId) {
        selectedFirstPartyCrmContactId = contactId;
        window.sessionStorage?.setItem?.('oneTimeSelectedCrmContactId', String(contactId || ''));
    }
    if (card.email) window.sessionStorage?.setItem?.('oneTimeSelectedCrmContactEmail', String(card.email || ''));
    currentWorkspaceId = workspaceKey;
    taskProjectFilter = projectKey;
    currentView = 'communications';
    if (actionChannel === 'email') {
        communicationsSection = 'email';
        emailInboxScope = window.BnaCrmInbox?.scopeForWorkspace?.(workspaceKey) || emailInboxScopeRecord().id;
        firstPartyCrmNotice = 'Email thread opened in the scoped Inbox.';
    } else {
        communicationsSection = 'whatsapp';
        selectedWapiPhonebookKey = firstPartyCrmWapiPhonebookKey(card, item) || selectedWapiPhonebookKey;
        wapiMobilePane = 'conversation';
        firstPartyCrmNotice = 'WhatsApp thread opened in the scoped Inbox.';
    }
    syncOperationsUrl();
    rerenderOperationsApp();
    await loadData({ background: true });
}

async function saveFirstPartyCrmAction(event, contactId) {
    event.preventDefault();
    const form = event.currentTarget;
    const data = new FormData(form);
    const submitterActionId = event.submitter?.dataset?.actionId || 'ACTION-CRM-CONTACT-SAFE-UPDATE';
    const noteBody = String(data.get('note_body') || '').trim();
    const ownerValue = String(data.get('assigned_owner') || '').trim();
    const tagToAdd = String(data.get('tag_to_add') || '').trim();
    const tagToRemove = String(data.get('tag_to_remove') || '').trim();
    const followUpDate = submitterActionId === 'ACTION-CRM-CLEAR-FOLLOW-UP'
        ? ''
        : String(data.get('next_follow_up_at') || '').trim();
    let tags = String(data.get('tags') || '')
        .split(',')
        .map(tag => tag.trim())
        .filter(Boolean);
    if (submitterActionId === 'ACTION-CRM-ADD-TAG') {
        if (!tagToAdd) {
            firstPartyCrmError = 'Enter a tag before saving.';
            firstPartyCrmNotice = '';
            render();
            return;
        }
        const lowerTags = new Set(tags.map(tag => tag.toLowerCase()));
        if (!lowerTags.has(tagToAdd.toLowerCase())) tags = [...tags, tagToAdd];
    }
    if (submitterActionId === 'ACTION-CRM-REMOVE-TAG') {
        if (!tagToRemove) {
            firstPartyCrmError = 'Choose a tag to remove.';
            firstPartyCrmNotice = '';
            render();
            return;
        }
        tags = tags.filter(tag => tag.toLowerCase() !== tagToRemove.toLowerCase());
    }
    if (submitterActionId === 'ACTION-CRM-ADD-NOTE' && !noteBody) {
        firstPartyCrmError = 'Enter a note before saving.';
        firstPartyCrmNotice = '';
        render();
        return;
    }
    if (submitterActionId === 'ACTION-CRM-ASSIGN-OWNER' && !ownerValue) {
        firstPartyCrmError = 'Enter an owner before saving.';
        firstPartyCrmNotice = '';
        render();
        return;
    }
    if (['ACTION-CRM-SET-FOLLOW-UP', 'ACTION-CRM-CHANGE-FOLLOW-UP'].includes(submitterActionId) && !followUpDate) {
        firstPartyCrmError = 'Choose a follow-up date before saving.';
        firstPartyCrmNotice = '';
        render();
        return;
    }
    firstPartyCrmSaving = true;
    firstPartyCrmError = '';
    firstPartyCrmNotice = '';
    render();
    try {
        const result = await api.updateCrmContact(contactId, {
            ...firstPartyCrmQueryFilters(),
            display_name: data.get('display_name') || '',
            email: data.get('email') || '',
            phone: data.get('phone') || '',
            status: data.get('status') || '',
            lifecycle_stage: data.get('status') || '',
            next_follow_up_at: followUpDate,
            assigned_owner: ownerValue,
            tags,
            create_follow_up_task: false,
            crm_action_id: submitterActionId,
            note_summary: submitterActionId === 'ACTION-CRM-CLEAR-FOLLOW-UP'
                ? 'CRM follow-up cleared'
                : (submitterActionId === 'ACTION-CRM-ADD-TAG'
                    ? `CRM tag added: ${tagToAdd}`
                    : (submitterActionId === 'ACTION-CRM-REMOVE-TAG'
                        ? `CRM tag removed: ${tagToRemove}`
                        : (submitterActionId === 'ACTION-CRM-ASSIGN-OWNER'
                            ? 'CRM owner assigned'
                            : (submitterActionId === 'ACTION-CRM-CHANGE-LIFECYCLE'
                                ? 'CRM lifecycle changed'
                                : (noteBody ? `CRM note for selected contact` : 'CRM contact updated'))))),
            note_body: noteBody,
            no_send: true,
            external_write_performed: false
        });
        firstPartyCrmNotice = 'CRM update saved.';
        await loadFirstPartyCrmContacts();
        selectedFirstPartyCrmContactId = contactId;
        firstPartyCrmTimelinePayload = null;
        firstPartyCrmConversationsPayload = null;
        firstPartyCrmTasksPayload = null;
        await openFirstPartyCrmContact(contactId, { captureScroll: false, syncUrl: false });
    } catch (error) {
        firstPartyCrmError = error.message || 'Could not save CRM update.';
    } finally {
        firstPartyCrmSaving = false;
        render();
    }
}

async function saveFirstPartyCrmNewContact(event) {
    event.preventDefault();
    if (oneTimeViewAsRabbiActive()) return;
    const form = event.currentTarget;
    const data = new FormData(form);
    const noteBody = String(data.get('note_body') || '').trim();
    const tags = String(data.get('tags') || '')
        .split(',')
        .map(tag => tag.trim())
        .filter(Boolean);
    firstPartyCrmSaving = true;
    firstPartyCrmError = '';
    firstPartyCrmNotice = '';
    render();
    try {
        const result = await api.createCrmContact({
            ...firstPartyCrmQueryFilters(),
            display_name: data.get('display_name') || '',
            email: data.get('email') || '',
            phone: data.get('phone') || '',
            contact_type: data.get('contact_type') || 'general_contact',
            family_school_classification: data.get('contact_type') || 'general_contact',
            status: data.get('status') || 'new',
            lifecycle_stage: data.get('status') || 'new',
            next_follow_up_at: data.get('next_follow_up_at') || '',
            assigned_owner: data.get('assigned_owner') || '',
            source: 'manual_crm',
            tags,
            create_follow_up_task: false,
            note_summary: noteBody ? 'Manual CRM contact note' : 'Manual CRM contact created',
            note_body: noteBody,
            no_send: true,
            external_write_performed: false
        });
        const contactId = result?.contact?.id || result?.contact_id || '';
        firstPartyCrmNotice = result?.created === false
            ? 'Existing workspace contact updated.'
            : 'Contact created.';
        firstPartyCrmAddContactOpen = false;
        firstPartyCrmActiveTab = 'overview';
        firstPartyCrmFilters = {
            contact_type: 'all',
            status: 'all',
            source: 'all',
            tag: 'all',
            sort_key: 'last_contact_desc',
            search: ''
        };
        firstPartyCrmContactsCache.clear();
        selectedFirstPartyCrmContactId = contactId || null;
        syncOperationsUrl();
        await loadFirstPartyCrmContacts(null, { force: true });
        if (contactId) {
            selectedFirstPartyCrmContactId = contactId;
            await openFirstPartyCrmContact(contactId, { captureScroll: false });
        }
    } catch (error) {
        firstPartyCrmError = error.message || 'Could not save CRM contact.';
    } finally {
        firstPartyCrmSaving = false;
        render();
    }
}

