function leadPipelineStatuses(visibleLeads) {
    const statusOrder = ['new', 'lead_candidate', 'interested', 'follow_up', 'visit_scheduled', 'application_sent', 'accepted_not_paid', 'not_now', 'not_fit'];
    const present = new Set(visibleLeads.map(leadStatusKey));
    return statusOrder
        .filter(status => present.has(status) || contactLeadStatusFilter === status)
        .concat([...present].filter(status => !statusOrder.includes(status)).sort());
}

function renderLeadPipeline(visibleLeads) {
    const statuses = leadPipelineStatuses(visibleLeads);
    return `
        <div class="lead-pipeline-board" aria-label="Interested parent pipeline">
            ${statuses.map(status => {
                const leads = visibleLeads.filter(lead => leadStatusKey(lead) === status);
                return `
                    <section class="lead-pipeline-column">
                        <div class="lead-pipeline-header">
                            <div class="lead-pipeline-title">${escapeHtml(leadStatusLabel(status))}</div>
                            <span class="lead-pipeline-count">${leads.length}</span>
                        </div>
                        <div class="lead-pipeline-list">
                            ${leads.length ? leads.map(renderLeadCard).join('') : '<div class="contact-detail-note">No leads in this stage.</div>'}
                        </div>
                    </section>
                `;
            }).join('')}
        </div>
    `;
}

function renderLeadFilterPanel(sectionLeads, visibleLeads) {
    const statusCounts = countByValue(sectionLeads, leadStatusKey);
    const interestCounts = countByValue(sectionLeads, leadInterestKey);
    const typeCounts = countByValue(sectionLeads, leadTypeKey);
    const tagCounts = {};
    sectionLeads.forEach(lead => {
        leadTags(lead).forEach(tag => {
            tagCounts[tag] = (tagCounts[tag] || 0) + 1;
        });
    });
    const statusOrder = ['new', 'lead_candidate', 'interested', 'follow_up', 'visit_scheduled', 'application_sent', 'accepted_not_paid', 'not_now', 'not_fit'];
    const statusOptions = Object.keys(statusCounts).sort((a, b) => {
        const aRank = statusOrder.includes(a) ? statusOrder.indexOf(a) : 99;
        const bRank = statusOrder.includes(b) ? statusOrder.indexOf(b) : 99;
        return aRank - bRank || a.localeCompare(b);
    });
    const interestOptions = ['hot', 'warm', 'cool', 'unknown'].filter(key => interestCounts[key] || contactInterestFilter === key);
    const typeOptions = [
        { value: 'all', label: `All lead types (${sectionLeads.length})` },
        { value: 'school_interest', label: `School interest (${typeCounts.school_interest || 0})` },
        { value: 'content_interest', label: `Content interest (${typeCounts.content_interest || 0})` },
        { value: 'group_member', label: `Group member (${typeCounts.group_member || 0})` },
        { value: 'accountability_interest', label: `Accountability app (${typeCounts.accountability_interest || 0})` },
    ];
    const statusSelectOptions = [
        { value: 'all', label: `All (${sectionLeads.length})` },
        ...statusOptions.map(status => ({ value: status, label: `${leadStatusLabel(status)} (${statusCounts[status]})` }))
    ];
    const interestSelectOptions = [
        { value: 'all', label: `All (${sectionLeads.length})` },
        ...interestOptions.map(level => ({ value: level, label: `${leadInterestLabel(level)} (${interestCounts[level] || 0})` }))
    ];
    const tagOptions = uniqueSortedTags([...allContactTags(), ...Object.keys(tagCounts)]);
    const tagSelectOptions = [
        { value: 'all', label: `All tags (${sectionLeads.length})` },
        ...tagOptions.map(tag => ({ value: tag, label: `${tag} (${tagCounts[tag] || 0})` }))
    ];

    return `
        <details class="filter-details collapsible-details" open>
            <summary>Filters</summary>
            <div class="filter-details-body">
                <div class="filter-row">
                    <span class="filter-label">Category</span>
                    ${renderFilterSelect('setContactFilter', 'lead_type', contactLeadTypeFilter, typeOptions, 'Lead category filter')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Date</span>
                    ${COMMON_DATE_FILTERS.map(filter => renderFilterChip('setContactFilter', 'date', filter.id, filter.label, contactDateFilter)).join('')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Status</span>
                    ${renderFilterSelect('setContactFilter', 'lead_status', contactLeadStatusFilter, statusSelectOptions, 'Lead status filter')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Interest</span>
                    ${renderFilterSelect('setContactFilter', 'interest', contactInterestFilter, interestSelectOptions, 'Lead interest filter')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Tags</span>
                    ${renderFilterSelect('setContactFilter', 'tag', contactTagFilter, tagSelectOptions, 'Lead tag filter')}
                </div>
                ${renderFilterCountNote(visibleLeads.length, sectionLeads.length, 'lead')}
            </div>
        </details>
    `;
}

function renderLeadCard(lead) {
    const leadId = Number(lead.id);
    const isActive = Number(selectedLeadId) === leadId;
    const studentMeta = [lead.student_name || '', lead.student_age ? `Age ${lead.student_age}` : '', lead.student_grade ? `Grade ${lead.student_grade}` : '']
        .filter(Boolean)
        .join(' - ');
    const sourceLine = [leadSourceLabel(lead.source), lead.source_detail || ''].filter(Boolean).join(' - ');
    const communications = leadCommunications(lead);
    const nextFollowUp = lead.next_follow_up_date ? `Next follow-up ${formatDate(lead.next_follow_up_date)}` : 'No follow-up date';
    const otherPhones = leadOtherPhones(lead);
    const latestWhatsapp = latestWhatsappCommunication(communications);

    return `
        <article class="contact-card ${isActive ? 'active' : ''}">
            <button class="contact-card-summary" type="button" onclick="selectLead(${leadId})" aria-expanded="${isActive ? 'true' : 'false'}" data-action-id="ACTION-CRM-CONTACT-CARD-EXPAND">
                <div class="contact-card-top">
                    <div class="contact-card-copy">
                        <div class="contact-card-title">${escapeHtml(lead.parent_name || 'Unknown parent')}</div>
                        <div class="contact-card-subtitle">${escapeHtml(studentMeta || leadTypeLabel(lead.lead_type))}</div>
                    </div>
                    <span class="page-status-pill">${escapeHtml(leadInterestLabel(lead.interest_level))}</span>
                </div>
                <div class="contact-card-contact">
                    ${lead.parent_phone ? escapeHtml(lead.parent_phone) : 'No phone yet'}
                    ${lead.parent_email ? ` - ${escapeHtml(lead.parent_email)}` : ' - No email yet'}
                </div>
                ${otherPhones.length ? `<div class="contact-card-contact">Other phone: ${escapeHtml(otherPhones.join(', '))}</div>` : ''}
                <div class="contact-card-meta">
                    <div class="tag-list">
                        ${leadTags(lead).slice(0, 4).map(tag => `<span class="tag ${escapeHtml(cssToken(tag))}">${escapeHtml(tag)}</span>`).join('') || '<span class="tag">No tags</span>'}
                    </div>
                    <span class="contact-detail-note">${escapeHtml(nextFollowUp)} - ${communications.length} note${communications.length === 1 ? '' : 's'}</span>
                    ${latestWhatsapp ? renderCommunicationDeliveryPill(latestWhatsapp) : ''}
                </div>
                <div class="contact-card-contact">${escapeHtml(sourceLine || 'Manual lead')}</div>
            </button>
            ${isActive ? renderLeadDetailPanel(lead) : ''}
        </article>
    `;
}

function renderLeadDetailPanel(lead) {
    if (!lead) {
        return `<div class="contact-detail-panel"><div class="contact-detail-note">Select a lead to see details.</div></div>`;
    }
    const leadId = Number(lead.id);
    const phoneDigits = String(lead.parent_phone || '').replace(/[^0-9]/g, '');
    const nextFollowUp = lead.next_follow_up_date ? formatDate(lead.next_follow_up_date) : 'Not scheduled';
    const lastTouch = leadDateValue(lead) ? formatDateTime(leadDateValue(lead)) : 'Unknown';
    const otherPhones = leadOtherPhones(lead);
    const communications = leadCommunications(lead);
    const latestWhatsapp = latestWhatsappCommunication(communications);
    const activeSection = LEAD_DETAIL_SECTIONS.some(section => section.id === leadDetailSection) ? leadDetailSection : 'overview';
    const detailSections = LEAD_DETAIL_SECTIONS.map(section => {
        const count = ({
            tags: leadTags(lead).length,
            communication: communications.length,
            notes: lead.notes ? 1 : 0
        })[section.id];
        return count === undefined ? section : { ...section, count };
    });

    return `
        <div class="contact-detail-panel">
            <div class="contact-detail-header">
                <div>
                    <div class="contact-detail-title">${escapeHtml(lead.parent_name || 'Unknown parent')}</div>
                    <div class="contact-detail-note">${escapeHtml(leadTypeLabel(lead.lead_type))} - ${escapeHtml(leadStatusLabel(lead.status))} - ${escapeHtml(leadInterestLabel(lead.interest_level))}</div>
                </div>
                <span class="page-status-pill">${escapeHtml(nextFollowUp)}</span>
            </div>
            <div class="person-detail-shell">
                <aside class="student-picker person-detail-sidebar">
                    <div class="event-type">Selected Lead</div>
                    <div class="event-title">${escapeHtml(lead.parent_name || 'Unknown parent')}</div>
                    <div class="event-meta">${escapeHtml(leadTypeLabel(lead.lead_type))} - ${escapeHtml(leadInterestLabel(lead.interest_level))}</div>
                    ${renderPersonSectionMenu({
                        id: `lead-${leadId}`,
                        label: 'Lead Sections',
                        sections: detailSections,
                        activeId: activeSection,
                        handlerName: 'setContactDetailSection',
                        handlerArgs: ['lead']
                    })}
                </aside>
                <div class="person-detail-main">
                    ${activeSection === 'overview' ? `
                        <div class="contact-detail-grid">
                            ${renderContactDetailItem('Category', leadTypeLabel(lead.lead_type))}
                            ${renderContactDetailItem('Status', leadStatusLabel(lead.status))}
                            ${renderContactDetailItem('Interest', leadInterestLabel(lead.interest_level))}
                            ${renderContactDetailItem('Source', leadSourceLabel(lead.source))}
                            ${renderContactDetailItem('Source Detail', lead.source_detail || 'Not set')}
                            ${renderContactDetailItem('Student', lead.student_name || 'Not entered')}
                            ${renderContactDetailItem('Next Follow-up', nextFollowUp)}
                            ${renderContactDetailItem('Last Touch', lastTouch)}
                        </div>
                    ` : ''}
                    ${activeSection === 'contact' ? `
                        <div class="contact-detail-grid">
                            ${renderContactDetailItem('Phone', lead.parent_phone || 'Not entered')}
                            ${renderContactDetailItem('Other Phones', otherPhones.length ? otherPhones.join(', ') : 'None')}
                            ${renderContactDetailItem('Email', lead.parent_email || 'Not entered')}
                            ${renderContactDetailItem('Latest WhatsApp', latestWhatsapp ? communicationDeliveryText(latestWhatsapp) : 'No WhatsApp log yet')}
                            ${renderContactDetailItem('Legacy CRM Contact', lead.legacy_crm_contact_id || 'Not linked')}
                            ${renderContactDetailItem('Legacy CRM Conversation', lead.legacy_crm_conversation_id || 'Not linked')}
                        </div>
                        <div class="task-actions">
                            ${phoneDigits ? `<a class="task-action primary" href="https://wa.me/${escapeHtml(phoneDigits)}" target="_blank" rel="noopener">WhatsApp</a>` : '<button class="task-action" disabled>No phone</button>'}
                            ${lead.parent_email ? `<a class="task-action" href="mailto:${escapeHtml(lead.parent_email)}">Email</a>` : '<button class="task-action" disabled>No email</button>'}
                            ${renderParentPortalActionButtons('lead', leadId, { email: lead.parent_email, phone: lead.parent_phone })}
                        </div>
                    ` : ''}
                    ${activeSection === 'tags' ? `
                        <div class="contact-detail-section" style="margin-top:0;">
                            <h3>Tags</h3>
                            <div class="tag-list">
                                ${leadTags(lead).map(tag => `<span class="tag ${escapeHtml(cssToken(tag))}">${escapeHtml(tag)}</span>`).join('') || '<span class="tag">No tags yet</span>'}
                            </div>
                        </div>
                    ` : ''}
                    ${activeSection === 'notes' ? `
                        <div class="contact-detail-section" style="margin-top:0;">
                            <h3>Notes</h3>
                            <div class="contact-detail-note">${escapeHtml(lead.notes || 'No lead notes yet.')}</div>
                        </div>
                    ` : ''}
                    ${activeSection === 'communication' ? `
                        <div class="contact-detail-section" style="margin-top:0;">
                            <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">
                                <h3>Communication</h3>
                                <button class="task-action primary" onclick="addLeadCommunication(${leadId})">Add note</button>
                            </div>
                            ${renderLeadCommunicationList(lead)}
                        </div>
                    ` : ''}
                    ${activeSection === 'actions' ? `
                        <div class="person-action-panel">
                            <div class="task-actions">
                                <button class="task-action primary" onclick="addLeadCommunication(${leadId})">Add note</button>
                                <button class="task-action" onclick="setLeadNextFollowUp(${leadId})">Follow-up</button>
                                <button class="task-action" onclick="updateLeadQuick(${leadId}, { interest_level: 'hot', status: 'interested' })">Mark hot</button>
                                <button class="task-action" onclick="updateLeadQuick(${leadId}, { interest_level: 'warm', status: 'follow_up' })">Mark warm</button>
                                <button class="task-action" onclick="updateLeadQuick(${leadId}, { status: 'not_now', interest_level: 'cool' })">Not now</button>
                                <button class="task-action" onclick="updateLeadQuick(${leadId}, { status: 'archived' })">Archive</button>
                            </div>
                        </div>
                    ` : ''}
                </div>
            </div>
        </div>
    `;
}

function communicationSortDescending(items = []) {
    return [...items].sort((a, b) => Date.parse(b.occurred_at || b.created_at || 0) - Date.parse(a.occurred_at || a.created_at || 0));
}

function uniqueCommunicationsById(items = []) {
    const seen = new Set();
    return (items || []).filter(item => {
        const key = String(item?.id || `${item?.source || 'communication'}:${item?.occurred_at || item?.created_at || ''}:${item?.summary || ''}`);
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

function normalizeUnifiedCommunicationRecord(row = {}) {
    const metadata = parseObjectMaybe(row.metadata);
    const sourceContext = parseObjectMaybe(row.source_context);
    const communicationType = row.communication_type || metadata.communication_type || '';
    const subject = row.subject || metadata.subject || row.summary || 'Email communication';
    const body = row.body_text || row.body || row.body_preview || row.summary || '';
    const fromAddress = row.from_address || metadata.from_address || '';
    const toAddress = row.to_address || metadata.to_address || '';
    const fromName = row.from_name || metadata.from_name || row.contact_name || '';
    const metadataTags = [
        ...(Array.isArray(metadata.communication_tags) ? metadata.communication_tags : []),
        ...(Array.isArray(row.tags) ? row.tags : []),
    ];
    return {
        id: row.id ? `bna_communications:${row.id}` : `bna_communications:${row.external_message_id || row.thread_key || row.created_at || subject}`,
        source_table: 'bna_communications',
        source_record_type: 'bna_communications',
        channel: row.channel || metadata.channel || (/email|resend/i.test(communicationType) ? 'email' : 'message'),
        direction: row.direction || metadata.direction || 'inbound',
        source: row.provider || metadata.source || 'bna_communications',
        provider: row.provider || metadata.provider || 'bna_communications',
        subject,
        summary: subject,
        body,
        contact_id: row.contact_id || metadata.contact_id || null,
        contact_name: fromName || metadata.contact_name || 'General contact',
        contact_email: fromAddress || metadata.contact_email || '',
        email: fromAddress || metadata.email || '',
        project_id: row.project_id || metadata.project_id || null,
        project_key: row.project_key || metadata.project_key || '',
        project_name: row.project_name || metadata.project_name || '',
        workspace_key: row.workspace_key || metadata.workspace_key || '',
        occurred_at: row.occurred_at || row.created_at || metadata.occurred_at || '',
        created_at: row.created_at || row.occurred_at || metadata.created_at || '',
        external_message_id: row.external_message_id || metadata.email_message_id || '',
        thread_key: row.thread_key || metadata.thread_key || '',
        follow_up_required: Boolean(row.follow_up_required || metadata.follow_up_required),
        metadata: {
            ...metadata,
            source_table: 'bna_communications',
            source_record_type: 'bna_communications',
            communication_type: communicationType,
            from_address: fromAddress,
            to_address: toAddress,
            communication_tags: [...new Set(['bna communications', row.provider || '', communicationType, ...metadataTags].filter(Boolean))],
        },
        source_context: {
            ...sourceContext,
            source: 'bna_communications',
            unified_communication_id: row.id || '',
            contact_id: row.contact_id || '',
            from_address: fromAddress,
            to_address: toAddress,
            message_id: row.external_message_id || metadata.email_message_id || '',
            status: row.status || metadata.status || '',
        },
    };
}

function mergeContactAndUnifiedCommunications(contactRows = [], unifiedRows = []) {
    const normalizedUnifiedRows = (unifiedRows || []).map(normalizeUnifiedCommunicationRecord).filter(Boolean);
    return communicationSortDescending(uniqueCommunicationsById([...(contactRows || []), ...normalizedUnifiedRows]));
}

function phoneTokenVariantsClient(value = '') {
    const digits = normalizePhoneDigitsClient(value);
    if (!digits || digits.length < 7) return [];
    const variants = new Set([digits]);
    if (digits.startsWith('00') && digits.length > 9) variants.add(digits.slice(2));
    if (digits.startsWith('972') && digits.length >= 11) variants.add(`0${digits.slice(3)}`);
    if (digits.startsWith('0') && digits.length >= 9) variants.add(`972${digits.slice(1)}`);
    return [...variants].filter(token => token.length >= 7);
}

function phoneTokensFromValues(values = []) {
    return [...new Set((values || []).flatMap(value => phoneTokenVariantsClient(value)))];
}

function emailTokensFromValues(values = []) {
    const emailPattern = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
    const tokens = [];
    (values || []).forEach(value => {
        const matches = String(value || '').match(emailPattern) || [];
        matches.forEach(match => tokens.push(match.trim().toLowerCase()));
    });
    return [...new Set(tokens)];
}

function communicationEmailTokens(item = {}) {
    const sourceContext = parseObjectMaybe(item.source_context);
    const metadata = parseObjectMaybe(item.metadata);
    return emailTokensFromValues([
        sourceContext.from_address,
        sourceContext.to_address,
        sourceContext.email,
        sourceContext.parent_email,
        sourceContext.matched_email,
        metadata.from_address,
        metadata.to_address,
        metadata.email,
        metadata.parent_email,
        item.contact_email,
        item.email,
    ]);
}

function communicationIntersectsTokens(left = [], right = []) {
    if (!left.length || !right.length) return false;
    const rightSet = new Set(right);
    return left.some(token => rightSet.has(token));
}

function signupCommunicationMatchTokens(signupOrId) {
    const signup = typeof signupOrId === 'object'
        ? signupOrId
        : signups.find(item => Number(item.id) === Number(signupOrId));
    const linkedStudent = signup ? linkedStudentForSignup(signup) : null;
    return {
        signup,
        signupId: Number(signup?.id || signupOrId || 0),
        studentId: Number(linkedStudent?.id || signup?.student_id || 0),
        phoneTokens: phoneTokensFromValues([
            signup?.parent_phone,
            signup?.phone,
            signup?.whatsapp_phone,
            linkedStudent?.parent_phone,
            linkedStudent?.phone,
        ]),
        emailTokens: emailTokensFromValues([
            signup?.parent_email,
            signup?.email,
            linkedStudent?.parent_email,
            linkedStudent?.email,
        ]),
    };
}

function communicationMatchesSignup(item = {}, signupOrId) {
    if (!communicationAllowedForCurrentWorkspace(item)) return false;
    const tokens = signupCommunicationMatchTokens(signupOrId);
    if (tokens.signupId && Number(item.signup_id) === tokens.signupId) return true;
    if (tokens.studentId && Number(item.student_id) === tokens.studentId) return true;
    if (communicationIntersectsTokens(tokens.phoneTokens, communicationPhoneTokens(item))) return true;
    if (communicationIntersectsTokens(tokens.emailTokens, communicationEmailTokens(item))) return true;
    return false;
}

function leadCommunicationMatchTokens(leadOrId) {
    const lead = typeof leadOrId === 'object'
        ? leadOrId
        : parentLeads.find(item => Number(item.id) === Number(leadOrId));
    return {
        lead,
        leadId: Number(lead?.id || leadOrId || 0),
        phoneTokens: phoneTokensFromValues([
            lead?.parent_phone,
            lead?.phone,
            lead?.whatsapp_phone,
            ...leadOtherPhones(lead),
        ]),
        emailTokens: emailTokensFromValues([
            lead?.parent_email,
            lead?.email,
        ]),
    };
}

function communicationMatchesLead(item = {}, leadOrId) {
    if (!communicationAllowedForCurrentWorkspace(item)) return false;
    const tokens = leadCommunicationMatchTokens(leadOrId);
    if (tokens.leadId && Number(item.lead_id) === tokens.leadId) return true;
    if (communicationIntersectsTokens(tokens.phoneTokens, communicationPhoneTokens(item))) return true;
    if (communicationIntersectsTokens(tokens.emailTokens, communicationEmailTokens(item))) return true;
    return false;
}

function signupCommunications(signupOrId) {
    return communicationSortDescending(uniqueCommunicationsById(contactCommunications
        .filter(item => communicationMatchesSignup(item, signupOrId))));
}

function renderCommunicationHistoryGuardrail() {
    return `
        <div class="contact-detail-note" data-contact-communication-history-readonly>
            Read-only workspace-scoped local history matched by record ID, normalized phone, email, or WAPI source context. No Whapi sync, WhatsApp send, broadcast, CRM tag update, or external CRM write runs from this card.
        </div>
    `;
}

function selectedTaskCalendarLabel(key) {
    const date = dateFromKey(key);
    if (!date) return formatDate(key) || 'Selected day';
    return date.toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'long',
        day: 'numeric',
        year: 'numeric',
    });
}

function renderSignupCommunicationList(signupOrId) {
    const items = signupCommunications(signupOrId);
    if (!items.length) return `
        ${renderCommunicationHistoryGuardrail()}
        <div class="contact-detail-note" data-contact-communication-history="signup-empty">No communication notes yet. Incoming WAPI/WhatsApp messages will appear here when the phone number or email matches this parent.</div>
    `;
    return `
        ${renderCommunicationHistoryGuardrail()}
        <div class="mini-list" data-contact-communication-history="signup">
            ${items.map(renderCommunicationEntry).join('')}
        </div>
    `;
}

function leadCommunications(leadOrId) {
    return communicationSortDescending(uniqueCommunicationsById(contactCommunications
        .filter(item => communicationMatchesLead(item, leadOrId))));
}

function renderLeadCommunicationList(leadOrId) {
    const items = leadCommunications(leadOrId);
    if (!items.length) return `
        ${renderCommunicationHistoryGuardrail()}
        <div class="contact-detail-note" data-contact-communication-history="lead-empty">No communication notes yet. Incoming WAPI/WhatsApp messages will appear here when the phone number or email matches this lead.</div>
    `;
    return `
        ${renderCommunicationHistoryGuardrail()}
        <div class="mini-list" data-contact-communication-history="lead">
            ${items.map(renderCommunicationEntry).join('')}
        </div>
    `;
}

function communicationContactName(item) {
    return item.lead_parent_name || item.signup_parent_name || item.signup_student_name || item.student_name || 'General contact';
}

function communicationChannelLabel(channel) {
    return contactStatusLabel(channel || 'internal_note');
}

function communicationDirectionLabel(direction) {
    return contactStatusLabel(direction || 'internal_note');
}

function communicationMetaLine(item) {
    const parts = [
        item.occurred_at || item.created_at ? formatDateTime(item.occurred_at || item.created_at) : '',
        communicationChannelLabel(item.channel),
        communicationDirectionLabel(item.direction),
    ].filter(Boolean);
    return parts.join(' - ');
}

function latestWhatsappCommunication(items = []) {
    return (items || []).find(item => String(item.channel || '').toLowerCase() === 'whatsapp') || null;
}

function communicationDeliveryStatus(item = {}) {
    if (String(item.channel || '').toLowerCase() !== 'whatsapp') return '';
    const metadata = item.metadata && typeof item.metadata === 'object' ? item.metadata : {};
    const sourceContext = item.source_context && typeof item.source_context === 'object' ? item.source_context : {};
    const status = metadata.delivery_status || sourceContext.delivery_status || '';
    if (status) return String(status).toLowerCase();
    if (metadata.sent === true || sourceContext.wapi_status) return 'sent';
    if (item.follow_up_required && String(item.source || '') === 'wapi') return 'unknown';
    return '';
}

function communicationDeliveryText(item = {}) {
    const status = communicationDeliveryStatus(item);
    const metadata = item.metadata && typeof item.metadata === 'object' ? item.metadata : {};
    const sourceContext = item.source_context && typeof item.source_context === 'object' ? item.source_context : {};
    const error = metadata.error || sourceContext.error || '';
    const label = ({
        sent: 'WhatsApp sent',
        delivered: 'WhatsApp delivered',
        read: 'WhatsApp read',
        played: 'WhatsApp played',
        pending: 'WhatsApp pending',
        attempted: 'WhatsApp attempted',
        unknown: 'WhatsApp delivery unknown',
        failed: 'WhatsApp failed',
        not_configured: 'WhatsApp not configured'
    })[status] || (String(item.channel || '').toLowerCase() === 'whatsapp' ? 'WhatsApp logged' : '');
    return [label, error && status !== 'sent' ? limitTextClient(error, 90) : ''].filter(Boolean).join(' - ');
}

function renderCommunicationDeliveryPill(item = {}) {
    const text = communicationDeliveryText(item);
    if (!text) return '';
    const status = communicationDeliveryStatus(item) || 'logged';
    return `<span class="page-status-pill whatsapp-${escapeHtml(cssToken(status))}">${escapeHtml(text)}</span>`;
}

function renderCommunicationEntry(item) {
    const tags = communicationTags(item).slice(0, 5);
    const attachmentSummary = communicationAttachmentSummary(item);
    return `
        <div class="contact-detail-item wapi-timeline-item">
            <span class="contact-detail-label">${escapeHtml(communicationMetaLine(item))}</span>
            <div class="contact-detail-value">${escapeHtml(communicationSubject(item) || 'Contact note')}</div>
            ${renderCommunicationDeliveryPill(item)}
            ${item.body ? `<div class="contact-communication-body">${escapeHtml(item.body)}</div>` : ''}
            ${attachmentSummary ? `<div class="contact-detail-note">Attachments: ${escapeHtml(attachmentSummary)}</div>` : ''}
            <div class="contact-card-meta">
                ${item.follow_up_required ? '<span class="page-status-pill">Follow-up</span>' : ''}
                ${tags.map(tag => `<span class="status-chip">${escapeHtml(tag)}</span>`).join('')}
            </div>
        </div>
    `;
}

function renderCommunicationsSection() {
    const sectionCommunications = [...contactCommunications].sort((a, b) => {
        return Date.parse(b.occurred_at || b.created_at || 0) - Date.parse(a.occurred_at || a.created_at || 0);
    });
    const visibleCommunications = sectionCommunications.filter(communicationMatchesContactFilters);

    return `
        ${renderCommunicationFilterPanel(sectionCommunications, visibleCommunications)}
        ${sectionCommunications.length === 0 ? `
            <div class="contact-empty-card">
                No communication notes are saved yet.
            </div>
        ` : visibleCommunications.length === 0 ? `
            <div class="contact-empty-card">
                No communication notes match this filter.
            </div>
        ` : `
            <div class="contact-layout">
                <div class="contact-list">
                    ${visibleCommunications.map(renderCommunicationCard).join('')}
                </div>
            </div>
        `}
    `;
}

function renderCommunicationFilterPanel(sectionCommunications, visibleCommunications) {
    const tagCounts = {};
    sectionCommunications.forEach(item => {
        communicationTags(item).forEach(tag => {
            tagCounts[tag] = (tagCounts[tag] || 0) + 1;
        });
    });
    const tagOptions = uniqueSortedTags([...allContactTags(), ...Object.keys(tagCounts)]);
    const tagSelectOptions = [
        { value: 'all', label: `All tags (${sectionCommunications.length})` },
        ...tagOptions.map(tag => ({ value: tag, label: `${tag} (${tagCounts[tag] || 0})` }))
    ];
    return `
        <details class="filter-details collapsible-details" open>
            <summary>Filters</summary>
            <div class="filter-details-body">
                <div class="filter-row">
                    <span class="filter-label">Date</span>
                    ${COMMON_DATE_FILTERS.map(filter => renderFilterChip('setContactFilter', 'date', filter.id, filter.label, contactDateFilter)).join('')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Tags</span>
                    ${renderFilterSelect('setContactFilter', 'tag', contactTagFilter, tagSelectOptions, 'Communication tag filter')}
                </div>
                ${renderFilterCountNote(visibleCommunications.length, sectionCommunications.length, 'note')}
            </div>
        </details>
    `;
}

function renderCommunicationCard(item) {
    const priority = communicationPriority(item);
    const tags = communicationTags(item);
    const bodyPreview = limitTextClient(item.body || item.summary || '', 260);
    return `
        <article class="contact-card communications-card" data-communication-card data-priority="${escapeHtml(priority)}">
            <div class="contact-card-body">
                <div class="contact-card-top">
                    <div class="contact-card-copy">
                        <div class="contact-card-title">${escapeHtml(communicationSubject(item))}</div>
                        <div class="contact-card-subtitle">${escapeHtml(communicationContactName(item))} / ${escapeHtml(communicationMetaLine(item))}</div>
                    </div>
                    <span class="page-status-pill">${escapeHtml(priority === 'urgent' ? 'Urgent' : priority === 'high' ? 'High' : communicationActionLabel(item))}</span>
                </div>
                <div class="contact-card-contact">${escapeHtml(bodyPreview || 'Contact note')}</div>
                ${renderCommunicationDeliveryPill(item)}
                ${item.body && item.body !== bodyPreview ? `<div class="contact-communication-body">${escapeHtml(limitTextClient(item.body, 520))}</div>` : ''}
                <div class="communication-detail-grid">
                    <div class="communication-detail-pill"><strong>Contact</strong>${escapeHtml(communicationContactName(item))}</div>
                    <div class="communication-detail-pill"><strong>Channel</strong>${escapeHtml(communicationChannelLabel(item.channel))} / ${escapeHtml(communicationDirectionLabel(item.direction))}</div>
                    <div class="communication-detail-pill"><strong>Source</strong>${escapeHtml(communicationSourceLabel(item))}</div>
                    <div class="communication-detail-pill"><strong>Status</strong>${escapeHtml(communicationStatusLine(item))}</div>
                    <div class="communication-detail-pill"><strong>Address</strong>${escapeHtml(communicationAddressLine(item))}</div>
                    <div class="communication-detail-pill"><strong>Workspace</strong>${escapeHtml(communicationAssociatedContext(item))}</div>
                </div>
                <div class="contact-card-meta">
                    <div class="tag-list">
                        ${tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}
                        ${item.lead_type ? `<span class="tag">${escapeHtml(leadTypeLabel(item.lead_type))}</span>` : ''}
                        ${item.lead_interest_level ? `<span class="tag">${escapeHtml(leadInterestLabel(item.lead_interest_level))}</span>` : ''}
                    </div>
                    <span class="status-chip">${escapeHtml(communicationActionLabel(item))}</span>
                </div>
            </div>
        </article>
    `;
}

