function moneyFromCents(amountCents, currency = 'USD') {
    if (amountCents === null || amountCents === undefined || Number.isNaN(Number(amountCents))) return 'pending';
    const prefix = currency === 'USD' ? '$' : `${currency} `;
    return `${prefix}${(Number(amountCents || 0) / 100).toFixed(2)}`;
}

