function renderOneTimeAgentModeAcceptancePanel() {
    const acceptance = oneTimeAgentModeAcceptance();
    const stages = Array.isArray(acceptance.stages) ? acceptance.stages : [];
    const blockers = Array.isArray(acceptance.remaining_external_blockers) ? acceptance.remaining_external_blockers : [];
    const checks = acceptance.acceptance_checks || {};
    const passCount = Object.values(checks).filter(Boolean).length;
    const checkCount = Object.keys(checks).length;
    return `
        <section class="focus-panel" data-one-time-agent-mode-acceptance data-requirement-id="${escapeHtml(acceptance.requirement_id || 'REQ-20260621-910')}" aria-label="One Time Agent Mode acceptance">
            <div class="task-section-header"><h3>Agent Mode Acceptance</h3><span>${escapeHtml(acceptance.status || 'pending')}</span></div>
            <p class="settings-disabled-note">Read-only acceptance over parser, CRM import, trial/referral, payment/access/class links, tickets/questions, and beta TEST data. This panel does not run an autonomous agent, create records, send messages, charge cards, write to external CRM, or mutate Zoom/Vimeo/Google/DNS.</p>
            <div class="task-overview-grid">
                ${renderMetricButton('Stages Covered', `${stages.length}/6`, 'Parser, CRM, trial/referral, access links, support/questions, and beta data.', "switchView('agents'); setCurrentSection('overview')")}
                ${renderMetricButton('Checks Passed', `${passCount}/${checkCount || 0}`, 'Acceptance checks must all pass before closeout.', "switchView('agents'); setCurrentSection('overview')")}
                ${renderMetricButton('External Writes', acceptance.external_write_performed === false ? 'None' : 'Check', 'Acceptance is read-only.', "switchView('settings'); setCurrentSection('security')")}
                ${renderMetricButton('Blockers', blockers.length, 'Remaining external/operator-only actions.', "switchView('decisions'); setCurrentSection('blocked')")}
            </div>
            <div class="content-section-grid" style="margin-top:14px;">
                ${stages.map(renderOneTimeAgentAcceptanceStage).join('') || '<div class="task-empty">Agent Mode acceptance has not loaded yet.</div>'}
            </div>
            <details class="workflow-details" style="margin-top:14px;" open>
                <summary>Remaining External Blockers</summary>
                <div class="calendar-event-list">
                    ${blockers.map(blocker => `
                        <div class="calendar-event-row">
                            <div>
                                <strong>${escapeHtml(blocker.key || 'blocker')}</strong>
                                <div class="event-meta">${escapeHtml(blocker.requirement_id || '')} &middot; ${escapeHtml(blocker.status || '')} &middot; owner ${escapeHtml(blocker.owner || 'operator')}</div>
                                <div class="event-meta">${escapeHtml(blocker.next_action || 'next action pending')}</div>
                            </div>
                            <span class="tag">external</span>
                        </div>
                    `).join('') || '<div class="task-empty">No external blockers are listed.</div>'}
                </div>
            </details>
            <div class="task-actions" style="margin-top:14px;">
                <button class="task-action primary" type="button" onclick="switchView('agents'); setCurrentSection('overview')">View Agent Status</button>
                <button class="task-action" type="button" onclick="switchView('tasks'); setTaskFocus('codex_queue')">View Acceptance Evidence</button>
                <button class="task-action" type="button" disabled aria-disabled="true" title="Read-only acceptance. Running an external/autonomous agent requires explicit operator authorization.">Run Live Agent Mode</button>
            </div>
        </section>
    `;
}

