async function revokeRabbiGrant(grantId) {
    if (!confirm('Revoke this access grant?')) return;
    try {
        await api.revokeRabbiGrant(grantId, { dryRun: true, notes: 'Revoked from Operations launch preview.' });
        rabbiLaunchNotice = 'Access grant revoked.';
        await refreshRabbiLaunchData();
    } catch (error) {
        alert(error.message || 'Could not revoke grant.');
    }
}

