function providerParticipantRows() {
    const cards = pipelineCardsForSection('participants').concat(pipelineCardsForSection('provider_class'));
    const fromCards = cards.map(card => ({
        name: card.title || card.contact_name || 'Participant',
        status: card.stage || card.status || 'lead',
        next: card.next_action || card.notes || 'Confirm membership/access status',
        source: 'pipeline'
    }));
    const fromPeople = people
        .filter(person => /provider|member|participant|sheller|scheller/i.test(`${person.tags || ''} ${person.role || ''} ${person.name || ''}`))
        .map(person => ({
            name: person.name || person.email || 'Participant',
            status: person.status || person.role || 'member',
            next: person.email || person.phone || 'No contact detail loaded',
            source: 'person'
        }));
    const rows = [...fromCards, ...fromPeople];
    return rows.length ? rows : [
        { name: 'Mishnayos member', status: 'sample', next: 'Load participants from provider signup/payment source.', source: 'placeholder' }
    ];
}

function providerAccessRows() {
    return providerParticipantRows().map(row => ({
        ...row,
        access: /won|paid|active|member/i.test(row.status) ? 'Active or pending verification' : 'Needs payment/access review'
    }));
}

function providerScheduleEvents() {
    const productEvents = rabbiLaunch.productSystem?.calendar?.events || [];
    if (productEvents.length) {
        return productEvents.map(event => ({
            ...event,
            workspace_key: 'rabbi_sheller_provider',
            source: 'one_time_product_calendar',
            status: event.event_status || event.status || 'draft',
            description: [
                event.masechta,
                event.perek,
                event.mishnah_range,
                event.notes
            ].filter(Boolean).join(' - '),
            source_notes: `Visibility: ${event.visibility || 'admin_only'}; source sheet ${event.source_sheet_status || 'not_started'}; worksheet ${event.worksheet_status || 'not_started'}; slides ${event.slides_status || 'not_started'}`,
            metadata: {
                ...(event.metadata || {}),
                timezone: event.timezone || 'Asia/Jerusalem',
                source_sheet_status: event.source_sheet_status || 'not_started',
                worksheet_status: event.worksheet_status || 'not_started',
                slides_status: event.slides_status || 'not_started',
            },
        }));
    }
    const events = derivedCalendarEvents()
        .filter(event => normalizeWorkspaceKey(event.workspace_key) === 'rabbi_sheller_provider' || /sheller|mishnayos|mishna|7:00|provider/i.test(`${event.title || ''} ${event.description || ''} ${event.source || ''}`));
    return events.length ? events : [rabbiSchellerSevenPmProgramEvent()];
}

function rabbiSchellerSevenPmProgramEvent() {
    const next = new Date();
    next.setHours(19, 0, 0, 0);
    if (next.getTime() <= Date.now()) next.setDate(next.getDate() + 1);
    return {
        id: 'rabbi-sheller-7pm-program',
        title: "Rabbi Scheller's 7pm Mishnayos class",
        start_at: next.toISOString(),
        workspace_key: 'rabbi_sheller_provider',
        related_type: 'provider_program',
        source: 'provider_schedule',
        visibility: 'participant',
        status: 'review_needed',
        owner_name: 'Rabbi Elie Scheller',
        project_name: 'One Time Mishnah Class',
        recurrence: 'Recurring class; exact weekday/date pending confirmation',
        timezone: 'Asia/Jerusalem',
        source_notes: 'Derived from the One Time provider workspace schedule text until a persisted calendar event or class session is loaded.',
        description: 'First-class provider program schedule object for the 7pm Mishnayos class. Review exact recurrence before external calendar sync or member notices.',
        derived: true,
        metadata: {
            owner: 'Rabbi Elie Scheller',
            project: 'One Time Mishnah Class',
            time: '7:00 PM',
            timezone: 'Asia/Jerusalem',
            recurrence: 'Recurring class; exact weekday/date pending confirmation',
            source_notes: 'Derived from provider workspace schedule text; no external calendar write has run.',
            status: 'review_needed'
        }
    };
}

function renderProviderSchedulePanel() {
    const events = providerScheduleEvents();
    const sourcePrepJobs = rabbiLaunch.productSystem?.source_prep_jobs || [];
    return `
        <section class="focus-panel">
            <div class="task-section-header"><h3>Provider Program Schedule</h3><span>${events.length} items</span></div>
            <p class="settings-disabled-note">Simple schedule only: next class, worksheet/source-sheet deadlines, structured question deadlines, optional class link, and access notices. Add Class saves an internal One Time calendar event only; it does not create a Zoom meeting or external calendar event.</p>
            <form class="settings-form-grid" onsubmit="createOneTimeCalendarEvent(event)">
                <label>Class title<input id="oneTimeClassTitle" placeholder="One Time Mishnayos class"></label>
                <label>Start<input id="oneTimeClassStart" type="datetime-local"></label>
                <label>Duration<input id="oneTimeClassDuration" type="number" min="15" max="240" value="60"></label>
                <label>Masechta<input id="oneTimeClassMasechta" placeholder="Berakhot"></label>
                <label>Perek<input id="oneTimeClassPerek" placeholder="1"></label>
                <label>Mishnah range<input id="oneTimeClassMishnahRange" placeholder="1:1-1:3"></label>
                <label>Visibility<select id="oneTimeClassVisibility"><option value="admin_only">Admin only</option><option value="parent_visible">Parent visible</option><option value="student_visible">Student visible</option><option value="public">Public</option></select></label>
                <label>Notes<textarea id="oneTimeClassNotes" rows="2" placeholder="Internal schedule notes"></textarea></label>
                <button class="task-action primary" type="submit">Add Class</button>
            </form>
            <div class="calendar-event-list">
                ${events.map(renderCalendarEventRow).join('')}
            </div>
        </section>
        ${renderOneTimeAvailabilityBookingPanel()}
        <section class="focus-panel">
            <div class="task-section-header"><h3>Source Prep Jobs</h3><span>${sourcePrepJobs.length}</span></div>
            <div class="content-section-grid">
                ${sourcePrepJobs.slice(0, 8).map(job => `
                    <article class="content-card">
                        <div class="content-card-title">${escapeHtml(job.natural_language_prompt || 'Source prep draft')}</div>
                        <div class="content-card-meta">sources: ${escapeHtml(job.source_lookup_status || 'not_started')} &middot; worksheet: ${escapeHtml(job.worksheet_status || 'not_started')} &middot; slides: ${escapeHtml(job.slides_status || 'not_started')}</div>
                        <p class="event-meta">${escapeHtml(job.approval_status || 'needs_review')} &middot; ${escapeHtml(job.visibility || 'admin_only')}</p>
                        <span class="tag">fixture only</span>
                    </article>
                `).join('') || '<div class="task-empty">No source-prep jobs yet. Create drafts only after Rabbi/admin source review context is available.</div>'}
            </div>
            <button class="task-action" type="button" onclick="createOneTimeSourcePrepFixture()">Create fixture source-prep draft</button>
        </section>
    `;
}

