function planEntitlementIncluded(planKey, entitlementKey) {
    if (planKey === 'free_listing') return ['public_profile', 'provider_index', 'lead_capture'].includes(entitlementKey);
    if (planKey === 'managed_provider') return ['public_profile', 'provider_index', 'lead_capture', 'lead_pipeline', 'landing_page_funnel', 'email_workflows', 'whatsapp_workflows', 'social_scheduling', 'ad_tracking', 'payment_access_tracking', 'content_video_workflow', 'worksheets_source_sheets', 'provider_admin', 'reporting', 'bot_actions', 'support_tickets'].includes(entitlementKey);
    if (planKey === 'school_workspace') return ['public_profile', 'provider_index', 'lead_capture', 'lead_pipeline', 'email_workflows', 'whatsapp_workflows', 'payment_access_tracking', 'parent_portal', 'student_workspace', 'provider_admin', 'reporting', 'bot_actions', 'support_tickets'].includes(entitlementKey);
    if (planKey === 'revenue_share_partner') return true;
    return false;
}

