function workspaceScopedCards(items = []) {
    const workspace = currentWorkspaceKey();
    if (workspace === 'platform') return items;
    return items.filter(item => normalizeWorkspaceKey(item.workspace_key || item.workspace || 'bna') === workspace);
}

function derivedPipelineCards() {
    const leadCards = parentLeads.map(lead => {
        const isProvider = /mishn|rabbi|provider|class|member|sheller|scheller/i.test(`${lead.lead_type || ''} ${lead.notes || ''} ${lead.source_detail || ''}`);
        return {
            id: `lead-${lead.id}`,
            derived: true,
            workspace_key: isProvider ? 'rabbi_sheller_provider' : 'bna',
            pipeline_key: isProvider ? 'provider_class' : 'bna_enrollment',
            stage_key: lead.status || 'interested',
            title: lead.parent_name || lead.student_name || 'Lead',
            summary: [lead.student_name, lead.interest_level, lead.notes].filter(Boolean).join(' / '),
            owner_name: lead.owner || 'Shloimie',
            next_action: lead.next_follow_up_date ? `Follow up ${formatDate(lead.next_follow_up_date)}` : 'Decide next touch',
            source: 'lead'
        };
    });
    const signupCards = signups.map(signup => ({
        id: `signup-${signup.id}`,
        derived: true,
        workspace_key: 'bna',
        pipeline_key: 'bna_enrollment',
        stage_key: signup.payment_status === 'paid' ? 'won' : signup.status || 'signup',
        title: signup.parent_name || signup.student_name || 'Signup',
        summary: [signup.student_name, signup.payment_status, signup.status].filter(Boolean).join(' / '),
        owner_name: 'Shloimie',
        next_action: signup.payment_status === 'paid' ? 'Confirm onboarding' : 'Resolve payment / signup',
        source: 'signup'
    }));
    const providerTasks = providerOnboardingTasks().map(task => ({
        id: `task-${task.id}`,
        derived: true,
        workspace_key: taskProjectKey(task) === 'one_time_mishnah_class' ? 'rabbi_sheller_provider' : 'platform',
        pipeline_key: 'provider_onboarding',
        stage_key: normalizeTaskStage(task.stage),
        title: taskDisplayTitle(task),
        summary: taskDisplayDetail(task, 'mine') || task.notes || '',
        owner_name: taskOwnerLabel(task),
        next_action: taskStageLabel(task),
        source: 'task',
        task_id: task.id
    }));
    return workspaceScopedCards([...leadCards, ...signupCards, ...providerTasks]);
}

function pipelineCardsForSection(section = pipelineSection) {
    const all = workspaceScopedCards([...(pipelineCards || []), ...derivedPipelineCards()]);
    if (section === 'bna_enrollment') return all.filter(card => card.pipeline_key === 'bna_enrollment');
    if (section === 'provider_class') return all.filter(card => card.pipeline_key === 'provider_class');
    if (section === 'provider_onboarding') return all.filter(card => card.pipeline_key === 'provider_onboarding');
    if (section === 'participants') return all.filter(card => /participant|member|won|paid|live|library/i.test(`${card.stage_key || ''} ${card.summary || ''}`));
    return all;
}

// Heavy non-initial renderers are emitted to /js/operations-deferred-renderers.js.

function renderCommandBotPanel(pageContext = currentView) {
    const actions = (supportedBotActions.length ? supportedBotActions : [
        { key: 'create_task', label: 'Create task', pages: ['tasks', 'pipelines'] },
        { key: 'create_calendar_event', label: 'Create calendar event', pages: ['calendar'] },
        { key: 'add_internal_note', label: 'Add internal note', pages: ['internal_dialogue'] },
        { key: 'draft_email', label: 'Draft email', pages: ['communications', 'settings'] },
        { key: 'generate_whatsapp_link', label: 'Generate WhatsApp link', pages: ['communications', 'settings'] }
    ]).filter(action => !Array.isArray(action.pages) || action.pages.includes(pageContext) || action.pages.includes(currentView));
    const logs = botActionLogs
        .filter(log => currentWorkspaceKey() === 'platform' || normalizeWorkspaceKey(log.workspace_key) === currentWorkspaceKey())
        .slice(0, 6);
    return `
        <section class="focus-panel command-bot-panel">
            <div class="task-section-header"><h3>Command Bot Actions</h3><span>${actions.length} typed actions</span></div>
            <p class="settings-disabled-note">The bot reads page/workspace context and previews typed actions. Sensitive actions require approval and dedicated handlers before mutation.</p>
            <div class="action-registry-grid">
                ${actions.map(action => `
                    <button class="action-registry-card" onclick="previewBotActionFromPanel('${escapeHtml(action.key)}')">
                        <strong>${escapeHtml(action.label || action.key)}</strong>
                        <span>${action.sensitive ? 'Approval required' : 'Preview safe'}</span>
                    </button>
                `).join('') || '<div class="empty-state">No typed actions are registered for this page yet.</div>'}
            </div>
            ${logs.length ? `
                <div class="dialogue-timeline compact">
                    ${logs.map(log => `<div class="timeline-item compact"><span class="timeline-dot"></span><div><strong>${escapeHtml(log.action_key)} / ${escapeHtml(log.status)}</strong><p>${escapeHtml(formatDateTime(log.created_at))}</p></div></div>`).join('')}
                </div>
            ` : ''}
        </section>
    `;
}

async function previewBotActionFromPanel(actionKey) {
    try {
        await api.previewBotAction({
            workspace_key: currentWorkspaceKey(),
            action_key: actionKey,
            page_context: {
                view: currentView,
                section: currentSectionId(),
                role: currentWorkspaceRoleLabel()
            },
            payload: {
                source: 'operations_command_panel'
            }
        });
        await loadData({ background: true });
        alert('Typed bot action preview was logged.');
    } catch (error) {
        alert(error.message || 'Could not preview typed bot action.');
    }
}


function isUnresolvedPaymentIntake(intake) {
    const status = String(intake?.status || '').toLowerCase();
    return !['completed', 'ignored', 'matched'].includes(status);
}

function accountingSectionMeta(section) {
    return ({
        overview: {
            title: 'Overview',
            description: 'Compact totals only: paid, unpaid, needs-review, paid-needs-signup, and next due.',
        },
        payments: {
            title: 'Payments',
            description: 'All payment records/cards with amount, method, status, paid date, next due, and contact info.',
        },
        open: {
            title: 'Needs Attention',
            description: 'Unpaid, partial, and unresolved payment records that need review or follow-up.',
        },
        paid: {
            title: 'Paid',
            description: 'Paid records and paid-before-signup records.',
        },
        needs_signup: {
            title: 'Needs Signup',
            description: 'Payments that exist but still need a signup/contact match.',
        },
        exceptions: {
            title: 'Exceptions',
            description: 'Mismatches, missing contact details, partial payments, and records needing manual review.',
        },
    })[section] || {
        title: 'Overview',
        description: 'Compact accounting view.',
    };
}

function renderAccountingOverview(rosterRows) {
    const nextDueRows = rosterRows.filter(row => row.nextDue).slice(0, 6);
    const attentionRows = rosterRows
        .filter(row => paymentRosterMatchesSection(row, 'exceptions') || paymentRosterMatchesSection(row, 'open'))
        .slice(0, 6);
    return `
        <div class="content-section-grid">
            <div class="event-card">
                <div class="event-type">Next Due</div>
                <div class="event-title">Upcoming payment dates</div>
                ${nextDueRows.length
                    ? `<div class="mini-list">${nextDueRows.map(row => `
                        <button class="mini-list-item" onclick="setAccountingSection('payments')">
                            <span>${escapeHtml(row.parentName)}</span>
                            <strong>${formatDate(row.nextDue)}</strong>
                        </button>
                    `).join('')}</div>`
                    : '<p class="payment-muted">No next due dates are scheduled yet.</p>'}
            </div>
            <div class="event-card">
                <div class="event-type">Needs Attention</div>
                <div class="event-title">Open, partial, missing, or unmatched</div>
                ${attentionRows.length
                    ? `<div class="mini-list">${attentionRows.map(row => `
                        <button class="mini-list-item" onclick="setAccountingSection('${row.source === 'intake' ? 'needs_signup' : 'open'}')">
                            <span>${escapeHtml(row.parentName)}</span>
                            <strong>${escapeHtml(row.statusLabel)}</strong>
                        </button>
                    `).join('')}</div>`
                    : '<p class="payment-muted">No accounting exceptions are visible right now.</p>'}
            </div>
        </div>
    `;
}

function renderPaymentRosterTable(rows, emptyText) {
    return `
        <div class="data-table payment-roster">
            <div class="table-header">
                <div>Parent / Student</div>
                <div>Contact</div>
                <div>Amount / Method</div>
                <div>Status</div>
                <div>Paid</div>
                <div>Next Due</div>
            </div>
            ${rows.length === 0 ? `
                <div class="empty-state">
                    <p>${escapeHtml(emptyText)}</p>
                </div>
            ` : rows.map(row => `
                <div class="table-row">
                    <div>
                        <div class="parent-name">${escapeHtml(row.parentName)}</div>
                        <div class="student-name">${escapeHtml(row.studentName || 'Student not entered yet')}</div>
                        ${row.source === 'intake' ? '<div class="payment-muted">Pre-signup payment</div>' : ''}
                    </div>
                    <div>
                        <div>${escapeHtml(row.email || 'No email yet')}</div>
                        <div class="student-name">${escapeHtml(row.phone || 'No phone yet')}</div>
                    </div>
                    <div>
                        <div>${row.amount ? `ILS ${escapeHtml(String(row.amount))}` : 'Amount unknown'}</div>
                        <div class="student-name">${escapeHtml(row.method || 'Method not set')}</div>
                    </div>
                    <div>
                        <span class="mobile-field-label">Status</span>
                        <span class="payment-status ${escapeHtml(row.statusKey)}">${escapeHtml(row.statusLabel)}</span>
                    </div>
                    <div>
                        <span class="mobile-field-label">Paid</span>
                        ${row.paidAt ? formatDate(row.paidAt) : '<span class="payment-muted">Not paid yet</span>'}
                    </div>
                    <div>
                        <span class="mobile-field-label">Next due</span>
                        ${row.nextDue ? formatDate(row.nextDue) : `<span class="payment-muted">${escapeHtml(row.nextDueLabel || 'Not scheduled yet')}</span>`}
                    </div>
                </div>
            `).join('')}
        </div>
    `;
}

function paymentRosterMatchesSection(row, section) {
    const missingContact = !String(row.email || '').trim() || !String(row.phone || '').trim();
    if (section === 'payments') return true;
    if (section === 'open') return !['paid', 'needs_signup'].includes(row.statusKey);
    if (section === 'paid') return row.statusKey === 'paid' || row.statusKey === 'needs_signup';
    if (section === 'needs_signup') return row.statusKey === 'needs_signup' || row.source === 'intake';
    if (section === 'exceptions') return row.source === 'intake' || row.statusKey === 'partial' || row.statusKey === 'needs_matching' || missingContact;
    return true;
}

function accountingMethodKey(row) {
    return String(row.method || 'not_set').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'not_set';
}

function accountingMethodLabel(method) {
    if (method === 'not_set') return 'Method not set';
    return String(method || '').replace(/_/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase());
}

function accountingMatchesDateFilter(row) {
    if (accountingDateFilter === 'next_due') return Boolean(row.nextDue);
    return matchesRecentDate(row.paidAt || row.nextDue || row.createdAt, accountingDateFilter);
}

function accountingMatchesFilters(row) {
    return (accountingStatusFilter === 'all' || row.statusKey === accountingStatusFilter)
        && (accountingMethodFilter === 'all' || accountingMethodKey(row) === accountingMethodFilter)
        && (accountingSourceFilter === 'all' || row.source === accountingSourceFilter)
        && accountingMatchesDateFilter(row);
}

function renderAccountingFilterPanel(sectionRows, visibleRows) {
    const statusCounts = countByValue(sectionRows, row => row.statusKey);
    const methodCounts = countByValue(sectionRows, accountingMethodKey);
    const sourceCounts = countByValue(sectionRows, row => row.source || 'signup');
    const statusOptions = ['paid', 'pending', 'partial', 'needs_signup', 'needs_matching'].filter(status => statusCounts[status]);
    const methodOptions = Object.keys(methodCounts).sort();
    const sourceOptions = Object.keys(sourceCounts).sort();
    const statusSelectOptions = [
        { value: 'all', label: `All (${sectionRows.length})` },
        ...statusOptions.map(status => ({ value: status, label: `${paymentStatusLabel(status)} (${statusCounts[status]})` }))
    ];
    const methodSelectOptions = [
        { value: 'all', label: 'All methods' },
        ...methodOptions.map(method => ({ value: method, label: `${accountingMethodLabel(method)} (${methodCounts[method]})` }))
    ];
    const sourceSelectOptions = [
        { value: 'all', label: 'All sources' },
        ...sourceOptions.map(source => ({ value: source, label: `${contactStatusLabel(source)} (${sourceCounts[source]})` }))
    ];

    return `
        <details class="filter-details collapsible-details" open>
            <summary>Filters</summary>
            <div class="filter-details-body">
                <div class="filter-row">
                    <span class="filter-label">Date</span>
                    ${ACCOUNTING_DATE_FILTERS.map(filter => renderFilterChip('setAccountingFilter', 'date', filter.id, filter.label, accountingDateFilter)).join('')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Status</span>
                    ${renderFilterSelect('setAccountingFilter', 'status', accountingStatusFilter, statusSelectOptions, 'Accounting status filter')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Method</span>
                    ${renderFilterSelect('setAccountingFilter', 'method', accountingMethodFilter, methodSelectOptions, 'Accounting method filter')}
                </div>
                <div class="filter-row">
                    <span class="filter-label">Source</span>
                    ${renderFilterSelect('setAccountingFilter', 'source', accountingSourceFilter, sourceSelectOptions, 'Accounting source filter')}
                </div>
                ${renderFilterCountNote(visibleRows.length, sectionRows.length, 'payment record')}
            </div>
        </details>
    `;
}

function renderAccountingSummaryCard(label, value, note) {
    return `
        <div class="accounting-summary-card">
            <span class="accounting-summary-label">${escapeHtml(label)}</span>
            <strong>${escapeHtml(String(value))}</strong>
            <span class="accounting-summary-note">${escapeHtml(note)}</span>
        </div>
    `;
}

function buildPaymentRoster(activeSignups, openIntake) {
    const latestPaymentsBySignup = new Map();
    [...payments].sort((a, b) => new Date(b.received_at || b.created_at || 0) - new Date(a.received_at || a.created_at || 0))
        .forEach(payment => {
            const signupId = payment.signup_id || payment.signup?.id;
            if (signupId && !latestPaymentsBySignup.has(String(signupId))) {
                latestPaymentsBySignup.set(String(signupId), payment);
            }
        });

    const signupRows = activeSignups.map(signup => {
        const latestPayment = latestPaymentsBySignup.get(String(signup.id)) || {};
        const statusKey = normalizePaymentStatusKey(signup.payment_status);
        return {
            source: 'signup',
            sortName: `${signup.parent_name || ''} ${signup.student_name || ''}`.toLowerCase(),
            parentName: signup.parent_name || 'Unknown parent',
            studentName: signup.student_name || '',
            email: signup.parent_email || '',
            phone: signup.parent_phone || '',
            amount: signup.payment_amount || latestPayment.amount || 1000,
            method: signup.payment_method || latestPayment.method || '',
            statusKey,
            statusLabel: paymentStatusLabel(statusKey),
            paidAt: signup.last_payment_at || signup.cash_received_at || latestPayment.received_at || latestPayment.created_at || (statusKey === 'paid' ? signup.updated_at : null),
            nextDue: signup.payment_due_date || null,
            nextDueLabel: signup.payment_due_date ? '' : 'No due date set',
            createdAt: signup.created_at || signup.updated_at || latestPayment.created_at || null,
        };
    });

    const intakeRows = openIntake.map(intake => ({
        source: 'intake',
        sortName: `${intake.parent_name || ''} ${intake.student_name || ''}`.toLowerCase(),
        parentName: intake.parent_name || 'Unknown parent',
        studentName: intake.student_name || '',
        email: intake.parent_email || '',
        phone: intake.parent_phone || '',
        amount: intake.amount || '',
        method: intake.method || '',
        statusKey: normalizePaymentStatusKey(intake.status),
        statusLabel: paymentStatusLabel(normalizePaymentStatusKey(intake.status)),
        paidAt: intake.received_at || intake.created_at || null,
        nextDue: null,
        nextDueLabel: 'Signup needed first',
        createdAt: intake.created_at || intake.received_at || null,
    }));

    return [...signupRows, ...intakeRows].sort((a, b) => {
        const priority = { pending: 0, partial: 1, needs_signup: 2, needs_matching: 2, paid: 3 };
        const aPriority = priority[a.statusKey] ?? 2;
        const bPriority = priority[b.statusKey] ?? 2;
        if (aPriority !== bPriority) return aPriority - bPriority;
        return a.sortName.localeCompare(b.sortName);
    });
}

function normalizePaymentStatusKey(status) {
    const key = String(status || 'pending').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    if (key === 'paid') return 'paid';
    if (key === 'partial') return 'partial';
    if (key === 'needs_signup') return 'needs_signup';
    if (key === 'needs_matching') return 'needs_matching';
    return 'pending';
}

function paymentStatusLabel(statusKey) {
    return ({
        paid: 'Paid',
        partial: 'Partial',
        needs_signup: 'Paid, needs signup',
        needs_matching: 'Paid, needs match',
        pending: 'Not paid',
    })[statusKey] || 'Open';
}


function defaultContentSection(workspaceKey = currentWorkspaceKey()) {
    return currentWorkspaceIsOneTime(workspaceKey) ? 'one_time_library' : 'library';
}

function visibleContentSubtabs(workspaceKey = currentWorkspaceKey()) {
    if (currentWorkspaceIsOneTime(workspaceKey)) return ONE_TIME_CONTENT_SUBTABS;
    return CONTENT_SUBTABS.filter(tab => tab.id !== 'one_time_library' || currentWorkspaceIsGlobal(workspaceKey));
}

