// Helpers
function escapeHtml(text) {
    if (text === null || text === undefined || text === '') return '';
    return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function attrJson(value) {
    return JSON.stringify(String(value || '')).replace(/"/g, '&quot;').replace(/</g, '\\u003c');
}

function attrValueJson(value) {
    return JSON.stringify(value ?? {}).replace(/"/g, '&quot;').replace(/</g, '\\u003c');
}

function matchesRecentDate(value, filter) {
    if (filter === 'all') return true;
    if (!value) return false;
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return false;
    const now = new Date();
    if (filter === 'today') return date.toDateString() === now.toDateString();
    if (filter === 'week') return date.getTime() >= now.getTime() - (7 * 24 * 60 * 60 * 1000);
    if (filter === 'month') return date.getTime() >= now.getTime() - (30 * 24 * 60 * 60 * 1000);
    return true;
}

function countByValue(items = [], getter) {
    return (items || []).reduce((counts, item) => {
        const key = String(getter(item) || 'unknown');
        counts[key] = (counts[key] || 0) + 1;
        return counts;
    }, {});
}

function countByContentTopicKeys(items = []) {
    return (items || []).reduce((counts, item) => {
        contentTopicKeys(item).forEach((key) => {
            counts[key] = (counts[key] || 0) + 1;
        });
        return counts;
    }, {});
}

function formatDate(date) {
    if (!date) return '';
    return new Date(date).toLocaleDateString('en-GB', { month: 'short', day: 'numeric' });
}

function formatDateTime(date) {
    if (!date) return '';
    return new Date(date).toLocaleString('en-GB', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}

function formatTime(date) {
    if (!date) return '';
    const value = new Date(date);
    if (Number.isNaN(value.getTime())) return '';
    return value.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
}

function formatUrgency(urgency) {
    return ({
        urgent: 'Urgent',
        today: 'Today',
        this_week: 'This week',
        low: 'Low'
    })[urgency] || 'Normal';
}

function parseJsonField(value) {
    if (!value) return null;
    if (typeof value === 'object') return value;
    try { return JSON.parse(value); } catch { return null; }
}

function transcriptPreview(text) {
    if (!text) return '';
    return text.replace(/\s+/g, ' ').trim().slice(0, 500);
}

function containsHebrewText(value) {
    return /[\u0590-\u05ff]/.test(String(value || ''));
}

function isMostlyEnglishText(value) {
    const text = String(value || '');
    const latin = (text.match(/[a-z]/gi) || []).length;
    const hebrew = (text.match(/[\u0590-\u05ff]/g) || []).length;
    return latin >= 20 && latin >= hebrew;
}

function cleanEnglishDisplayText(value) {
    return String(value || '')
        .replace(/[\u0590-\u05ff]+/g, '')
        .replace(/[Ã°Å¸â„¢â€šÃ°Å¸â€˜â€°Ã°Å¸Å’Â³Ã¢Ëœâ‚¬Ã¯Â¸ÂÃ°Å¸Ââ€˜Ã°Å¸Â¥Å¡Ã°Å¸â€™Â°Ã°Å¸â€œÅ’Ã¢Å“â€¦Ã¢â‚¬Â¢]/g, '')
        .replace(/^[\s\-Ã¢â‚¬â€œÃ¢â‚¬â€:*]+/, '')
        .replace(/\btranscript\b/gi, 'recording')
        .replace(/\(\s*\)/g, '')
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/\s+/g, ' ')
        .trim();
}

function isGenericContentText(value) {
    return /auto drive intake|transcribe audio|describe image|ask the operator|what do you want me to do|repurpose-ready asset/i.test(String(value || ''));
}

function contentItemText(item) {
    if (!item) return '';
    if (typeof item === 'object') {
        return [
            item.reference,
            item.source,
            item.book,
            item.chapter_verse,
            item.hebrew_source,
            item.hebrew_text,
            item.text,
            item.reader
        ].filter(Boolean).join(' - ');
    }
    return String(item);
}

function isNonContentSectionText(value) {
    const text = String(value || '').toLowerCase();
    if (!text.trim()) return false;
    return (
        /\b(codex|kimi|kimmy|dashboard|telegram|bot|bridge|railway|legacy crm|green invoice|webhook|parser|routing|database|deploy|task|tasks|my task|for me|app build|coding|content card|content section cleanup)\b/.test(text) ||
        /\b(accountability|private meeting|check-?in|follow-?up|attendance|engagement|goals?|student goal|student goals|personal goal|personal goals|fitness|exercise|workout|diet goal|work goal|job goal|torah goal|learning goal|group goal|daily completion|progress percent|percentage|points?|camping trip|student ownership|daily follow-?through|work responsibility)\b/.test(text)
    );
}

function englishContentLine(value) {
    const cleaned = cleanEnglishDisplayText(contentItemText(value));
    if (!cleaned || isGenericContentText(cleaned)) return '';
    if (isNonContentSectionText(cleaned)) return '';
    if (!/[a-z]/i.test(cleaned)) return '';
    return cleaned;
}

function sourceContentLine(value) {
    const cleaned = contentItemText(value)
        .replace(/[ÃƒÂ°Ã…Â¸Ã¢â€žÂ¢Ã¢â‚¬Å¡ÃƒÂ°Ã…Â¸Ã¢â‚¬ËœÃ¢â‚¬Â°ÃƒÂ°Ã…Â¸Ã…â€™Ã‚Â³ÃƒÂ¢Ã‹Å“Ã¢â€šÂ¬ÃƒÂ¯Ã‚Â¸Ã‚ÂÃƒÂ°Ã…Â¸Ã‚ÂÃ¢â‚¬ËœÃƒÂ°Ã…Â¸Ã‚Â¥Ã…Â¡ÃƒÂ°Ã…Â¸Ã¢â‚¬â„¢Ã‚Â°ÃƒÂ°Ã…Â¸Ã¢â‚¬Å“Ã…â€™ÃƒÂ¢Ã…â€œÃ¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¢]/g, '')
        .replace(/^[\s\-ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â:*]+/, '')
        .replace(/\btranscript\b/gi, 'recording')
        .replace(/\s+([,.;:!?])/g, '$1')
        .replace(/\s+/g, ' ')
        .trim();
    if (!cleaned || isGenericContentText(cleaned)) return '';
    if (isNonContentSectionText(cleaned)) return '';
    if (!/[a-z\u0590-\u05ff]/i.test(cleaned)) return '';
    return cleaned;
}

function uniqueEnglishList(items, limit = 12) {
    const seen = new Set();
    const result = [];
    asList(items).forEach((item) => {
        const line = englishContentLine(item);
        const key = line.toLowerCase();
        if (!line || seen.has(key)) return;
        seen.add(key);
        result.push(line);
    });
    return result.slice(0, limit);
}

function uniqueSourceList(items, limit = 12) {
    const seen = new Set();
    const result = [];
    asList(items).forEach((item) => {
        const line = sourceContentLine(item);
        const key = line.toLowerCase();
        if (!line || seen.has(key)) return;
        seen.add(key);
        result.push(line);
    });
    return result.slice(0, limit);
}

function firstNonEmptyOutput(outputs = []) {
    const output = outputs.find(item => item.status !== 'archived' && item.body && item.body.trim() && item.body.trim() !== item.title);
    return output ? output.body.trim().slice(0, 700) : '';
}

function preferredEnglishOutputBodies(outputs = []) {
    const priority = ['whatsapp_update', 'facebook_post', 'weekly_newsletter', 'blog_draft', 'linkedin_post', 'youtube_description', 'google_business_post', 'short_clip', 'parent_email', 'teaching_philosophy_note', 'daily_report'];
    return outputs
        .filter(output => output && output.status !== 'archived' && output.body && !isGenericContentText(output.body))
        .filter(output => isMostlyEnglishText(output.body))
        .sort((a, b) => {
            const aRank = priority.indexOf(a.output_type);
            const bRank = priority.indexOf(b.output_type);
            return (aRank < 0 ? 99 : aRank) - (bRank < 0 ? 99 : bRank);
        })
        .map(output => String(output.body || ''));
}

function outputDiscussionBullets(job, limit = 6) {
    const bodies = preferredEnglishOutputBodies(job.outputs || []);
    const bullets = [];
    bodies.forEach((body) => {
        String(body || '').split(/\r?\n/).forEach((line) => {
            const raw = line.trim();
            if (!raw || !/^[-*Ã¢â‚¬Â¢Ã°Å¸â€˜â€°Ã°Å¸â„¢â€šÃ°Å¸Å’Â³Ã¢Ëœâ‚¬Ã¯Â¸ÂÃ°Å¸Ââ€˜Ã°Å¸Â¥Å¡]/.test(raw)) return;
            const cleaned = englishContentLine(raw);
            if (cleaned) bullets.push(cleaned);
        });
    });
    if (bullets.length) return uniqueEnglishList(bullets, limit);

    const fallbackSentences = [];
    bodies.forEach((body) => {
        cleanEnglishDisplayText(body)
            .split(/(?<=[.!?])\s+/)
            .map(sentence => sentence.trim())
            .filter(sentence => sentence.length >= 35 && sentence.length <= 220)
            .forEach(sentence => fallbackSentences.push(sentence));
    });
    return uniqueEnglishList(fallbackSentences, limit);
}

function contentParsedSections(job, parsed = {}) {
    const classNotes = [
        ...asList(parsed.class_notes),
        ...asList(parsed.mixed_recording_parse?.class_notes),
    ].filter(item => item && typeof item === 'object');

    const fromClassNotes = (key, aliases = []) => classNotes.flatMap(note => aliases.concat(key).flatMap(field => asList(note[field])));
    const topics = uniqueEnglishList([
        ...asList(parsed.topics),
        ...fromClassNotes('topics'),
    ]);
    const discussions = uniqueEnglishList([
        ...asList(parsed.discussions),
        ...asList(parsed.questions_or_discussions),
        ...fromClassNotes('discussions', ['questions_or_discussions']),
    ]);
    const studentQuestions = uniqueEnglishList([
        ...asList(parsed.student_questions),
        ...fromClassNotes('student_questions', ['questions']),
    ]);
    const sources = uniqueEnglishList([
        ...asList(parsed.sources),
        ...asList(parsed.source_texts),
        ...asList(parsed.torah_sources),
        ...fromClassNotes('sources', ['source_texts', 'torah_sources']),
    ]);
    const sourceRefs = uniqueSourceList([
        ...asList(parsed.sources),
        ...asList(parsed.source_texts),
        ...asList(parsed.torah_sources),
        ...fromClassNotes('sources', ['source_texts', 'torah_sources']),
    ]);
    const highlights = uniqueEnglishList([
        ...asList(parsed.highlights),
        ...asList(parsed.newsletter_highlights),
        ...fromClassNotes('highlights', ['newsletter_highlights']),
    ]);
    const outputBullets = outputDiscussionBullets(job);
    const inferredTopics = inferredContentTopics(job);
    return {
        topics: topics.length ? topics : (outputBullets.length ? outputBullets : inferredTopics),
        discussions,
        studentQuestions,
        sources: sourceRefs.length ? sourceRefs : sources,
        highlights,
        outputBullets,
    };
}

function contentDisplayTitle(job, parsed = {}, sections = {}) {
    const topicTitle = compactContentTopics([
        ...asList(sections.topics),
        ...asList(sections.discussions),
        ...asList(sections.sources)
    ]).join(', ');
    const candidates = [
        parsed.title,
        parsed.english_title,
        job.title,
        topicTitle,
        ...(job.outputs || []).map(output => output.title),
    ];
    for (const candidate of candidates) {
        const title = englishContentLine(candidate);
        if (title && title.length <= 140 && !isGenericContentTitle(title)) return title;
    }
    return `Content item #${job.id}`;
}

function isGenericContentTitle(value) {
    return isGenericContentText(value)
        || /\b(whatsapp update draft|facebook post draft|weekly newsletter draft|website blog draft|content draft|class summary|new parent update video)\b/i.test(String(value || ''));
}

function activeContentOutputs(job = {}) {
    return (job.outputs || []).filter(output => output && output.status !== 'archived');
}

function contentNeedsOutput(job = {}) {
    const status = String(job?.status || '').toLowerCase();
    return status === 'transcribed' && activeContentOutputs(job).length === 0;
}

function contentStatusLabel(job) {
    if (contentNeedsOutput(job)) return 'Needs Output';
    if (job.status === 'transcribed') return 'Ready to Repurpose';
    if (job.status === 'needs_approval') return 'Draft Needs Approval';
    if (job.status === 'ingested' || job.status === 'transcribing') return 'Ingesting';
    return String(job.status || '').replace(/_/g, ' ');
}

function contentStatusFilterKey(job) {
    const status = String(job?.status || '').toLowerCase();
    if (contentNeedsOutput(job)) return 'needs_output';
    if (['ingested', 'transcribing'].includes(status)) return 'ingesting';
    if (['transcribed', 'parsing', 'drafting'].includes(status)) return 'ready';
    if (status === 'needs_approval') return 'needs_approval';
    if (['approved', 'published'].includes(status)) return 'approved';
    return status || 'unknown';
}

function contentMatchesStatusFilter(job, filter) {
    if (filter === 'all') return true;
    return contentStatusFilterKey(job) === filter;
}

function contentStatusCounts(items = []) {
    return items.reduce((counts, job) => {
        const key = contentStatusFilterKey(job);
        counts.all = (counts.all || 0) + 1;
        counts[key] = (counts[key] || 0) + 1;
        return counts;
    }, { all: 0 });
}

function normalizeContentTopicKey(value = '') {
    const raw = String(value || '')
        .trim()
        .toLowerCase()
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
    const aliases = {
        'billing_admin': 'billing_admin',
        'billing': 'billing_admin',
        'admin': 'billing_admin',
        'billing_admin_': 'billing_admin',
        'billing/admin': 'billing_admin',
        'operations': 'operations_note',
        'ops': 'operations_note',
        'support': 'support_ticket',
        'integration': 'integration_issue',
        'drive': 'drive_workflow_issue',
        'drive_workflow': 'drive_workflow_issue',
        'parser': 'parser_error',
        'parse_error': 'parser_error',
        'question': 'student_question',
        'questions': 'student_question',
        'tasks': 'task',
        'profile': 'profile_note',
        'private_review': 'private_meeting',
        'other': 'uncategorized',
        'unknown': 'uncategorized',
        'class_sessions': 'class_session',
        'class_note': 'class_notes',
        'profile_notes': 'profile_note',
        'parser_errors': 'parser_error',
        'student_questions': 'student_question',
        'open_questions': 'open_question',
        'content_ideas': 'content_idea',
        'article_angles': 'article_angle',
        'marketing_clips': 'marketing_clip',
        'source_sheets': 'source_sheet_candidate',
        'drive_workflows': 'drive_workflow_issue'
    };
    return aliases[raw] || raw;
}

function contentTopicLabelForKey(key = 'uncategorized') {
    const normalized = normalizeContentTopicKey(key) || 'uncategorized';
    const configured = CONTENT_TOPIC_FILTERS.find(filter => filter.id === normalized);
    if (configured) return configured.label;
    return normalized.split('_').map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
}

function contentDigestCard(job = {}) {
    const card = parseJsonField(job.digest_card) || job.digest_card;
    return card && typeof card === 'object' ? card : null;
}

function contentDigestCategories(card = {}) {
    const values = [
        ...(Array.isArray(card.categories) ? card.categories : []),
        ...(Array.isArray(card.category_labels) ? card.category_labels : []),
        ...(Array.isArray(card.topic_keys) ? card.topic_keys : [])
    ];
    const seen = new Set();
    return values.map((value) => {
        const raw = typeof value === 'object'
            ? (value.key || value.lane || value.category || value.id || value.label)
            : value;
        const key = normalizeContentTopicKey(raw);
        if (!key || seen.has(key)) return null;
        seen.add(key);
        return { key, label: contentTopicLabelForKey(key) };
    }).filter(Boolean);
}

function statusObject(label, key) {
    return { label, key };
}

function contentCardModel(job = {}, parsed = {}, sections = {}) {
    const card = contentDigestCard(job);
    if (card) return card;
    const categories = contentDigestCategories({
        categories: parsed.category_list || parsed.categories || parsed.routing?.categories || sections?.topics || []
    });
    const topicKeys = categories.length ? categories.map(category => category.key) : ['uncategorized'];
    const hasTranscript = Boolean(String(job.transcript_text || '').trim());
    const hasParse = Boolean(Object.keys(parsed || {}).length);
    const displayTitle = contentDisplayTitle(job, parsed, sections);
    const needsTitle = !displayTitle || /^(untitled|unknown|class recording|voice|audio|video)\b/i.test(displayTitle);
    const parseStatus = hasParse ? statusObject('Parsed', 'parsed') : statusObject(hasTranscript ? 'Needs parse' : 'Needs transcript', hasTranscript ? 'needs_parse' : 'needs_transcript');
    const digestStatus = statusObject('Needs digest', 'needs_digest');
    const routingStatus = categories.length ? statusObject('Routing ready', 'routing_ready') : statusObject('Needs routing', 'needs_routing');
    const topicStatus = topicKeys.includes('uncategorized') ? statusObject('Needs topic classification', 'needs_topic_classification') : statusObject('Classified', 'classified');
    const stateBadges = [
        needsTitle ? 'Needs title' : '',
        parseStatus.label.startsWith('Needs') ? parseStatus.label : '',
        digestStatus.label,
        routingStatus.label.startsWith('Needs') ? routingStatus.label : '',
        topicStatus.label.startsWith('Needs') ? topicStatus.label : ''
    ].filter(Boolean);
    return {
        display_title: needsTitle ? `Needs title - content job #${Number(job.id) || ''}`.trim() : displayTitle,
        summary: contentDisplaySummary(job, parsed),
        main_points: [
            ...asList(sections?.topics),
            ...asList(sections?.discussions),
            ...asList(sections?.highlights),
            ...asList(sections?.outputBullets)
        ],
        categories,
        category_labels: categories.map(category => category.label),
        topic_keys: topicKeys,
        topic_labels: topicKeys.map(contentTopicLabelForKey),
        parse_status: parseStatus,
        digest_status: digestStatus,
        routing_status: routingStatus,
        topic_status: topicStatus,
        next_action: stateBadges.length ? `Resolve: ${stateBadges.join(', ')}.` : contentPrimaryActionLabel(job),
        state_badges: stateBadges
    };
}

function contentSearchHaystack(job = {}) {
    const parsed = parseJsonField(job.parse_json) || {};
    const card = contentCardModel(job, parsed, contentParsedSections(job, parsed));
    const parts = [
        job.id,
        job.title,
        job.caption,
        job.notes,
        job.source_type,
        job.media_url,
        job.local_path,
        job.drive_file_id,
        job.drive_folder_id,
        job.drive_stage,
    ];
    addContentSearchValue(parts, card.display_title);
    addContentSearchValue(parts, card.summary);
    addContentSearchValue(parts, card.main_points);
    addContentSearchValue(parts, card.category_labels);
    addContentSearchValue(parts, card.topic_labels);
    addContentSearchValue(parts, card.state_badges);
    addContentSearchValue(parts, card.next_action);
    (job.outputs || []).forEach((output) => {
        addContentSearchValue(parts, output.output_type);
        addContentSearchValue(parts, output.platform);
        addContentSearchValue(parts, output.title);
        addContentSearchValue(parts, output.body);
        addContentSearchValue(parts, contentOutputMetadata(output));
    });
    return parts.filter(Boolean).join(' ').replace(/\s+/g, ' ').toLowerCase();
}

function contentMatchesSearch(job = {}, query = '') {
    const terms = String(query || '').toLowerCase().split(/\s+/).map(term => term.trim()).filter(Boolean);
    if (!terms.length) return true;
    const haystack = contentSearchHaystack(job);
    return terms.every(term => haystack.includes(term));
}

function addContentSearchValue(parts, value, depth = 0) {
    if (value === null || value === undefined || value === '' || depth > 3) return;
    if (Array.isArray(value)) {
        value.slice(0, 30).forEach(item => addContentSearchValue(parts, item, depth + 1));
        return;
    }
    if (typeof value === 'object') {
        Object.values(value).slice(0, 40).forEach(item => addContentSearchValue(parts, item, depth + 1));
        return;
    }
    parts.push(String(value));
}

function contentTopicHaystack(job = {}) {
    const parsed = parseJsonField(job.parse_json) || {};
    const card = contentDigestCard(job);
    const parts = [];
    [
        job.title,
        job.caption,
        job.notes,
        job.source_type,
        job.mime_type,
        job.media_url,
        job.local_path,
        job.drive_stage,
    ].forEach(value => addContentSearchValue(parts, value));
    if (card) {
        addContentSearchValue(parts, card.display_title);
        addContentSearchValue(parts, card.summary);
        addContentSearchValue(parts, card.category_labels);
        addContentSearchValue(parts, card.topic_labels);
        addContentSearchValue(parts, card.state_badges);
        addContentSearchValue(parts, card.next_action);
    }
    (job.outputs || []).slice(0, 8).forEach((output) => {
        addContentSearchValue(parts, output.title);
        addContentSearchValue(parts, String(output.body || '').slice(0, 5000));
    });
    return parts.join(' ').replace(/\s+/g, ' ').toLowerCase();
}

function contentLooksOperationalAdminRemarkFromHaystack(haystack = '') {
    const text = String(haystack || '').toLowerCase();
    if (!text.trim()) return false;
    const operationalMarker = /\b(codex|dashboard|operations|task|tasks|parser|routing|backend|technical|admin|prompt|corrupt|corruption|wrong section|railway|api|database|server|deploy|smoke|test|ui|toolbar|sidebar|button|buttons|dropdown|content section|torah section)\b/.test(text);
    if (!operationalMarker) return false;
    const classMarkerCount = contentRegexCount(text, /\b(class recording|shiur|lesson|learned|rashi|onkelos|chava|adam|avraham|gemara|zohar|mishnah?|mishnayos|sefaria|sefer|chumash|pasuk|verse|source sheet)\b/g);
    const operationsMarkerCount = contentRegexCount(text, /\b(codex|dashboard|operations|task|tasks|parser|routing|backend|technical|admin|prompt|corrupt|corruption|wrong section|railway|api|database|server|deploy|smoke|test|ui|toolbar|sidebar|button|buttons|dropdown|content section|torah section)\b/g);
    return operationsMarkerCount >= 2 || operationsMarkerCount >= classMarkerCount;
}

function contentRegexCount(text, pattern) {
    return (text.match(pattern) || []).length;
}

function contentFallbackTopicKey(job = {}) {
    const haystack = contentTopicHaystack(job);
    const scores = {
        one_time: contentProject(job) === 'mishna' ? 100 : contentRegexCount(haystack, /\b(one time|one-time|mishnah?|mishnayos|mishna|rabbi elie|scheller|sheller|vimeo|zoom)\b/g),
        torah: contentRegexCount(haystack, /\b(torah|gemara|mishnah?|mishnayos|sefaria|sefer|chumash|davening|tefillah|rebbe|rabbi|rashi|onkelos|orchos tzadikim|halacha|shabbos|shabbat|yom tov|daf|shiur|jewish|hashem)\b/g),
        health: contentRegexCount(haystack, /\b(health|food|sugar|nutrition|diet|junk|insulin|medication|medicine|vyvanse|exercise|fitness|workout|sleep|bedtime|wake|eggs|meat|fruit|juice|meal|meals|protein|vitamin)\b/g),
        psychology: contentRegexCount(haystack, /\b(adhd|trauma|dopamine|motivation|emotion|emotional|psychology|therapy|therapist|therapeutic|focus|checked out|self-control|connection|intrinsic|autonomy|responsibility|confidence|behavior|behaviour|anxiety|depression|mindset|executive function)\b/g),
        education: contentRegexCount(haystack, /\b(school|education|curriculum|classroom|homeschool|micro-school|microschool|teacher|student|learning system|assignment|worksheet|source sheet|mixed-age|lesson)\b/g),
        parenting: contentRegexCount(haystack, /\b(parent|parents|mother|father|mom|dad|family|son|child|children|boys|home|accountability|portal|meeting)\b/g),
        operations: contentRegexCount(haystack, /\b(codex|dashboard|operations|task|parser|railway|api|google workspace|integration|system|software|login|ui|filter|loading|deploy|smoke|database|server)\b/g),
        content_marketing: contentRegexCount(haystack, /\b(marketing|facebook post|linkedin|newsletter|blog|reel|clip|video description|organic|ad copy|prompt|buffer|social post|content calendar)\b/g),
    };
    if (contentLooksOperationalAdminRemarkFromHaystack(haystack)) return 'operations';
    const priority = ['one_time', 'torah', 'health', 'psychology', 'education', 'parenting', 'operations', 'content_marketing'];
    let best = 'other';
    let bestScore = 0;
    priority.forEach((key) => {
        if (scores[key] > bestScore) {
            best = key;
            bestScore = scores[key];
        }
    });
    return bestScore > 0 ? best : 'other';
}

function contentTopicKeys(job = {}) {
    const card = contentCardModel(job, parseJsonField(job.parse_json) || {}, contentParsedSections(job, parseJsonField(job.parse_json) || {}));
    const digestKeys = [
        ...(Array.isArray(card.topic_keys) ? card.topic_keys : []),
        ...contentDigestCategories(card).map(category => category.key)
    ].map(normalizeContentTopicKey).filter(Boolean);
    const uniqueDigestKeys = [...new Set(digestKeys)];
    if (uniqueDigestKeys.length && !uniqueDigestKeys.every(key => key === 'uncategorized')) return uniqueDigestKeys;
    const fallback = contentFallbackTopicKey(job);
    return fallback && fallback !== 'other' ? [fallback] : ['uncategorized'];
}

function contentTopicKey(job = {}) {
    return contentTopicKeys(job)[0] || 'uncategorized';
}

function contentTopicLabel(job = {}) {
    const labels = contentTopicKeys(job).map(contentTopicLabelForKey);
    return labels.length ? labels.join(', ') : 'Uncategorized';
}

function inferredContentTopics(job = {}) {
    const fallback = contentFallbackTopicKey(job);
    return fallback && fallback !== 'other' && fallback !== 'uncategorized'
        ? [`${contentTopicLabelForKey(fallback)} material`]
        : [];
}

function contentSourceKey(job = {}) {
    const sourceType = String(job.source_type || '').toLowerCase();
    const mime = String(job.mime_type || '').toLowerCase();
    const title = String(job.title || '').toLowerCase();
    const url = String(job.media_url || '').toLowerCase();
    const localPath = String(job.local_path || '').toLowerCase();
    if (/youtube\.com|youtu\.be/.test(url) || mime.includes('youtube') || /^youtube:/.test(title)) return 'youtube';
    if (sourceType.includes('google_drive') || job.drive_file_id || /drive\.google\.com/.test(url)) return 'drive';
    if (sourceType.includes('telegram') || job.source_message_id || job.source_chat_id || localPath.includes('media-inbox')) return 'telegram';
    if (sourceType.includes('local') || localPath.includes('media-drop') || localPath.includes('uploads')) return 'local';
    if (sourceType.includes('manual')) return 'manual';
    return 'unknown';
}

function contentSourceLabel(job = {}) {
    const key = contentSourceKey(job);
    return CONTENT_SOURCE_FILTERS.find(filter => filter.id === key)?.label || 'Unknown';
}

function contentSourceHref(job = {}) {
    const url = String(job.media_url || '').trim();
    if (/^https?:\/\//i.test(url)) return url;
    if (job.drive_file_id) return `https://drive.google.com/file/d/${encodeURIComponent(job.drive_file_id)}/view`;
    return '';
}

function shortContentValue(value, limit = 90) {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (text.length <= limit) return text;
    return `${text.slice(0, limit - 3).trim()}...`;
}

function contentSourceDetail(job = {}) {
    const parts = [];
    if (job.source_type) parts.push(`Source type: ${shortContentValue(job.source_type, 40)}`);
    if (job.drive_stage) parts.push(`Stage: ${shortContentValue(job.drive_stage, 60)}`);
    if (job.drive_file_id) parts.push(`Drive file: ${shortContentValue(job.drive_file_id, 48)}`);
    if (job.source_message_id) parts.push(`Telegram message: ${shortContentValue(job.source_message_id, 32)}`);
    if (job.local_path) parts.push(`Local file: ${shortContentValue(job.local_path, 80)}`);
    if (job.media_url) parts.push(`Source URL: ${shortContentValue(job.media_url, 100)}`);
    return parts.join(' | ');
}

function contentDisplaySummary(job, parsed = {}) {
    const summary = String(parsed.summary || '').trim();
    const generic = /auto drive intake|transcribe audio|describe image|ask the operator|what do you want me to do/i.test(summary);
    const cleanedSummary = englishContentLine(summary);
    if (cleanedSummary && !generic) return cleanedSummary;
    const sections = contentParsedSections(job, parsed);
    const topics = sections.topics;
    const discussions = sections.discussions;
    const highlights = sections.highlights;
    const parts = [
        topics.length ? `Topics: ${topics.slice(0, 4).join('; ')}` : '',
        discussions.length ? `Questions/discussions: ${discussions.slice(0, 3).join('; ')}` : '',
        highlights.length ? `Highlights: ${highlights.slice(0, 3).join('; ')}` : ''
    ].filter(Boolean);
    if (parts.length) return parts.join('\n');
    return outputDiscussionBullets(job, 3).join('\n');
}

function promptForOutputType(outputType) {
    return contentPrompts.find(prompt => prompt.platform === outputType) || null;
}

function outputForJob(job, outputType) {
    return (job.outputs || [])
        .filter(output => output.output_type === outputType && output.status !== 'archived')
        .sort((a, b) => Date.parse(b.updated_at || b.created_at || 0) - Date.parse(a.updated_at || a.created_at || 0))[0] || null;
}

function renderPromptGenerationStatus(state) {
    if (!state) return '';
    const status = ['working', 'done', 'error'].includes(state.status) ? state.status : 'working';
    const fallback = status === 'working'
        ? 'Regenerating output...'
        : status === 'done'
            ? 'Output updated.'
            : 'Generation failed.';
    return `
        <div class="prompt-generation-status ${status}" role="status" aria-live="polite">
            <span class="prompt-generation-dot"></span>
            <span>${escapeHtml(state.message || fallback)}</span>
        </div>
    `;
}

function upsertContentOutput(outputs = [], output = {}) {
    if (!output?.output_type) return outputs;
    const outputId = Number(output.id || 0);
    const archivedOutputs = outputs.filter(item => item.status === 'archived');
    const otherActiveOutputs = outputs.filter(item => {
        if (item.status === 'archived') return false;
        if (outputId && Number(item.id) === outputId) return false;
        return item.output_type !== output.output_type;
    });
    return [output, ...otherActiveOutputs, ...archivedOutputs];
}

function applyGeneratedPrompt(prompt, fallbackPlatform) {
    if (!prompt) return;
    const platform = prompt.platform || fallbackPlatform;
    if (!platform) return;
    let found = false;
    contentPrompts = contentPrompts.map(existing => {
        if (existing.platform === platform || (prompt.id && Number(existing.id) === Number(prompt.id))) {
            found = true;
            return { ...existing, ...prompt, platform };
        }
        return existing;
    });
    if (!found) contentPrompts = [...contentPrompts, { ...prompt, platform, examples: prompt.examples || [] }];
}

function applyContentJobGenerationResponse(jobId, outputType, response = {}) {
    const output = response.output;
    if (output?.output_type) {
        contentJobs = contentJobs.map(job => {
            if (Number(job.id) !== Number(jobId)) return job;
            return {
                ...job,
                status: job.status === 'published' ? job.status : 'needs_approval',
                outputs: upsertContentOutput(job.outputs || [], output),
            };
        });
    }
    applyGeneratedPrompt(response.prompt, outputType);
}

function applyNewsletterGenerationResponse(bundleId, response = {}) {
    const output = response.output;
    if (output?.output_type) {
        contentBundles = contentBundles.map(bundle => {
            if (Number(bundle.id) !== Number(bundleId)) return bundle;
            return {
                ...bundle,
                status: bundle.status === 'archived' ? bundle.status : 'generated',
                outputs: upsertContentOutput(bundle.outputs || [], output),
            };
        });
        if (output.job_id) {
            contentJobs = contentJobs.map(job => {
                if (Number(job.id) !== Number(output.job_id)) return job;
                return {
                    ...job,
                    status: job.status === 'published' ? job.status : 'needs_approval',
                    outputs: upsertContentOutput(job.outputs || [], output),
                };
            });
        }
    }
    applyGeneratedPrompt(response.prompt, 'weekly_newsletter');
}

function clearContentGenerationStateLater(key, storeName = 'content') {
    window.setTimeout(() => {
        if (storeName === 'newsletter') {
            if (newsletterGenerationStates[key]?.status === 'working') return;
            const next = { ...newsletterGenerationStates };
            delete next[key];
            newsletterGenerationStates = next;
        } else {
            if (contentGenerationStates[key]?.status === 'working') return;
            const next = { ...contentGenerationStates };
            delete next[key];
            contentGenerationStates = next;
        }
        render();
    }, 5500);
}

function contentMediaType(job) {
    const mime = String(job.mime_type || '').toLowerCase();
    const path = String(job.local_path || job.media_url || job.title || '').toLowerCase();
    if (mime.startsWith('video/') || /\.(mp4|mov|m4v|webm)(\?|$)/.test(path)) return 'video';
    if (mime.startsWith('audio/') || /\.(mp3|m4a|wav|ogg|opus)(\?|$)/.test(path)) return 'audio';
    if (mime.startsWith('image/') || /\.(jpg|jpeg|png|webp|gif)(\?|$)/.test(path)) return 'image';
    return 'file';
}

function contentProject(job) {
    const projectKey = String(job.project_key || job.project || '').toLowerCase();
    if (projectKey === 'one_time_mishnah_class' || projectKey === 'mishna' || projectKey === 'mishnah') return 'mishna';
    if (projectKey === 'bna') return 'bna';
    const haystack = [
        job.title,
        job.caption,
        job.notes,
        job.transcript_text
    ].filter(Boolean).join(' ').toLowerCase();
    if (/\b(one time|one time mishnah class|rabbi elie scheller|rabbi elie sheller|scheller|sheller|mishna|mishnah|mishnayas|mishna learning|mission of learning|micro school|micro schools)\b/.test(haystack)) {
        return 'mishna';
    }
    return 'bna';
}

function contentJobLooksLikeOneTimeMeeting(job = {}) {
    const haystack = [
        job.title,
        job.caption,
        job.notes,
        job.local_path,
        job.media_url,
        job.drive_file_id,
        job.transcript_text
    ].filter(Boolean).join(' ').toLowerCase();
    const isOneTime = contentProject(job) === 'mishna'
        || /\b(one time|rabbi elie|elie scheller|elie sheller|scheller|sheller|mishna|mishnah)\b/.test(haystack);
    const isMeeting = /\b(meeting|strategy|software|legacy crm|google classroom|workspace|parent login|student login|revenue|ownership|vimeo|analytics|zoom|voice\s*\d{6})\b/.test(haystack)
        || contentMediaType(job) === 'audio';
    return Boolean(isOneTime && isMeeting);
}

function contentLooksPrivateOrNonContentInput(job = {}) {
    const parsed = parseJsonField(job.parse_json) || {};
    const haystack = [
        parsed.content_kind,
        parsed.intake_lane,
        parsed.route_to,
        parsed.routing?.lane,
        job.title,
        job.caption,
        job.notes,
        job.drive_stage,
        job.local_path,
        job.transcript_text
    ].filter(Boolean).join(' ').toLowerCase();
    const teachingMaterial = /\b(class|shiur|lesson|source sheet|torah source|worksheet|mishnah?|mishnayos|gemara|sefaria|chumash|sefer|teaching topic|research)\b/.test(haystack);
    const nonContent = /\b(private meeting|rabbi coordination|coordination meeting|operator task|student goal|student note|accountability note|accountability meeting|technical discussion|backend|codex|railway|database|dashboard bug|ui bug|payment issue|accounting note)\b/.test(haystack);
    return Boolean(nonContent && !teachingMaterial);
}

function contentIsReusableContent(job = {}) {
    return !contentIsParserIntake(job) && !contentLooksPrivateOrNonContentInput(job);
}

function contentUploadedAt(job) {
    return job.created_at || job.updated_at;
}

function sortContentJobs(a, b) {
    return Date.parse(contentUploadedAt(b) || 0) - Date.parse(contentUploadedAt(a) || 0);
}

function contentMatchesDateFilter(job, filter) {
    if (filter === 'all') return true;
    const uploaded = Date.parse(contentUploadedAt(job) || '');
    if (!Number.isFinite(uploaded)) return false;
    const now = Date.now();
    if (filter === 'today') {
        const start = new Date();
        start.setHours(0, 0, 0, 0);
        return uploaded >= start.getTime();
    }
    if (filter === 'week') return uploaded >= now - (7 * 24 * 60 * 60 * 1000);
    if (filter === 'month') return uploaded >= now - (30 * 24 * 60 * 60 * 1000);
    return true;
}

function taskRelevantDate(task) {
    return task.due_date || task.planned_at || task.updated_at || task.file_mtime || task.completed_at || task.created_at || task.date;
}

function taskMatchesDateFilter(task, filter) {
    if (filter === 'all') return true;
    if (filter === 'no_date') return !task.due_date && !task.planned_at;
    const dueTime = taskDueTime(task);
    if (filter === 'today') return taskIsDueToday(task);
    if (filter === 'week') return taskIsDueWithinDays(task, 7);
    if (filter === 'upcoming') return Number.isFinite(dueTime) && dueTime >= startOfTodayMs();
    const value = Date.parse(taskRelevantDate(task) || '');
    if (!Number.isFinite(value)) return false;
    const now = Date.now();
    if (filter === 'month') return value >= now - (30 * 24 * 60 * 60 * 1000);
    return true;
}

function startOfTodayMs() {
    const start = new Date();
    start.setHours(0, 0, 0, 0);
    return start.getTime();
}

function taskDueTime(task = {}) {
    const value = Date.parse(task.due_date || task.planned_at || '');
    return Number.isFinite(value) ? value : null;
}

function taskIsDueToday(task = {}) {
    const due = taskDueTime(task);
    if (!Number.isFinite(due)) return false;
    return due >= startOfTodayMs() && due < startOfTodayMs() + 24 * 60 * 60 * 1000;
}

function taskIsDueWithinDays(task = {}, days = 7) {
    const due = taskDueTime(task);
    if (!Number.isFinite(due)) return false;
    return due >= startOfTodayMs() && due < startOfTodayMs() + Number(days) * 24 * 60 * 60 * 1000;
}

function taskPeopleText(task = {}) {
    return [task.assigned_to, task.waiting_on, task.decision_owner]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
}

function taskMatchesSignalFilter(task = {}, signal = taskSignalFilter) {
    const normalized = String(signal || 'all').toLowerCase();
    if (normalized === 'all') return true;
    const people = taskPeopleText(task);
    const agentStatus = String(task.agent_status || '').toLowerCase();
    const bucket = taskStatusBucket(task);
    if (normalized === 'needs_shloimie') return /(shloimie|operator|manager)/.test(`${task.decision_owner || ''} ${task.waiting_on || ''}`.toLowerCase());
    if (normalized === 'needs_rabbi') return /(rabbi|scheller|sheller|provider)/.test(`${task.decision_owner || ''} ${task.waiting_on || ''}`.toLowerCase());
    if (normalized === 'assigned_shloimie') return /shloimie|operator|manager/.test(String(task.assigned_to || '').toLowerCase());
    if (normalized === 'assigned_rabbi') return /rabbi|scheller|sheller|provider/.test(String(task.assigned_to || '').toLowerCase());
    if (normalized === 'unassigned') return !String(task.assigned_to || task.decision_owner || task.waiting_on || '').trim();
    if (normalized === 'other_team') {
        const owner = String(task.assigned_to || task.decision_owner || task.waiting_on || '').toLowerCase();
        return Boolean(owner) && !/(shloimie|operator|manager|rabbi|scheller|sheller|codex|agent|system|openai|kimi)/.test(owner);
    }
    if (normalized === 'external') return Boolean(task.waiting_on) && !/(shloimie|rabbi|scheller|sheller|codex|agent|system)/.test(people);
    if (normalized === 'agent_working') return taskMatchesCodexQueue(task) || ['queued', 'running', 'failed', 'blocked_needs_human_decision'].includes(agentStatus);
    if (normalized === 'due_today') return taskIsDueToday(task);
    if (normalized === 'due_week') return taskIsDueWithinDays(task, 7);
    if (normalized === 'stale') return Boolean(task.is_stale) || taskStaleReasonList(task).length > 0;
    if (normalized === 'done') return bucket === 'done';
    return true;
}

function formatHebrewDate(value) {
    const parsed = Date.parse(value || '');
    if (!Number.isFinite(parsed)) return '';
    try {
        return new Intl.DateTimeFormat('en-u-ca-hebrew', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        }).format(new Date(parsed));
    } catch (error) {
        return '';
    }
}

function renderContentFilterChip(kind, value, label, currentValue) {
    return renderFilterChip('setContentFilter', kind, value, label, currentValue);
}

function asList(value) {
    if (Array.isArray(value)) return value.filter(item => item !== null && item !== undefined && String(item).trim());
    if (!value) return [];
    if (typeof value === 'string') return value.split(/\n|;/).map(item => item.trim()).filter(Boolean);
    return [value];
}

function renderContentList(label, items, options = {}) {
    const cleanedItems = options.allowHebrew ? uniqueSourceList(items, 10) : uniqueEnglishList(items, 10);
    if (!cleanedItems.length) return '';
    return `
        <div class="event-card">
            <div class="event-type">${escapeHtml(label)}</div>
            <ul class="content-section-list" style="color: #cbd5e1; font-size: 13px;">
                ${cleanedItems.map(item => `<li>${escapeHtml(String(item))}</li>`).join('')}
            </ul>
        </div>
    `;
}

function renderContentBulletSummary(items, emptyText = 'Topic bullets are not ready yet. Open the card to generate or review outputs.') {
    const bullets = uniqueEnglishList(items, 6);
    if (!bullets.length) return `<p class="content-card-summary">${escapeHtml(emptyText)}</p>`;
    return `
        <div class="content-card-summary">
            <ul>
                ${bullets.slice(0, 5).map(item => `<li>${escapeHtml(item)}</li>`).join('')}
            </ul>
        </div>
    `;
}

function shortContentTopic(value) {
    let text = englishContentLine(value)
        .replace(/\b(the|this|that|and|with|about|around|through|during)\b/gi, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    if (!text) return '';
    const lower = text.toLowerCase();
    const topicRules = [
        [/goals?.*\broutines?\b|\broutines?.*\bgoals?\b/, 'Goals and routines'],
        [/\b(content|card|cards|collapsible|collapse|bullet|bullets|section|sections|transcript)\b/, 'Content organization'],
        [/\b(parse|parser|routing|route|natural language|recording|audio|video upload|uploaded video)\b/, 'Recording parser'],
        [/\b(codex|kimi|kimmy|code|coding|app|dashboard|railway|remotion|video editor)\b/, 'Coding tasks'],
        [/\b(payment|paid|invoice|green invoice|cash|billing|accounting)\b/, 'Payments'],
        [/\b(blog|faq|seo|aeo|geo|header image|one page|homepage)\b/, 'Website content'],
        [/\b(social|youtube|linkedin|facebook|footer icon|social icon)\b/, 'Social links'],
        [/\b(workout|working out|exercise|fitness|punching|squats?|pushups?)\b/, 'Fitness routine'],
        [/\b(diet|sugar|candy|pizza|weight|food|nutrition)\b/, 'Nutrition goals'],
        [/\b(inside|listening|sefer|torah|mishna|gemara|learning goal|focused learning|daily learning)\b/, 'Torah learning goals'],
        [/\b(accountability|student goal|private meeting|check-?in|progress percent|follow up|follow-up)\b/, 'Student accountability'],
    ];
    const matched = topicRules.find(([pattern]) => pattern.test(lower));
    if (matched) return matched[1];
    text = text.replace(/\b\d+(\.\d+)?%?\b/g, '').replace(/\s+/g, ' ').trim();
    const words = text.split(/\s+/).slice(0, 5);
    text = words.join(' ');
    if (text.length > 42) text = text.slice(0, 39).trim() + '...';
    return text;
}

function compactContentTopics(items) {
    const seen = new Set();
    const topics = [];
    asList(items).forEach((item) => {
        const topic = shortContentTopic(item);
        const key = topic.toLowerCase();
        if (!topic || seen.has(key)) return;
        seen.add(key);
        topics.push(topic);
    });
    return topics.slice(0, 3);
}

function renderCompactTopicChips(items) {
    const topics = compactContentTopics(items);
    if (!topics.length) {
        return `<div class="content-topic-chips"><span class="content-topic-chip">Needs parse</span></div>`;
    }
    return `
        <div class="content-topic-chips">
            ${topics.map(topic => `<span class="content-topic-chip">${escapeHtml(topic)}</span>`).join('')}
        </div>
    `;
}

function renderContentCardDigestChips(card = {}) {
    const chips = [
        ...asList(card.category_labels),
        ...asList(card.state_badges)
    ];
    const unique = [];
    const seen = new Set();
    chips.forEach((chip) => {
        const text = String(chip || '').trim();
        const key = text.toLowerCase();
        if (!text || seen.has(key)) return;
        seen.add(key);
        unique.push(text);
    });
    if (!unique.length) {
        unique.push('Needs topic classification');
    }
    return `
        <div class="content-topic-chips">
            ${unique.slice(0, 10).map(chip => `<span class="content-topic-chip">${escapeHtml(chip)}</span>`).join('')}
        </div>
    `;
}

function contentHasTranscript(job) {
    return Boolean(String(job.transcript_text || '').trim());
}

function contentIsParserIntake(job) {
    const parsed = parseJsonField(job.parse_json) || {};
    return parsed.intake_lane === 'tasks_students' || Boolean(parsed.routing?.parser_only);
}

function contentIsParseCandidate(job) {
    const mediaType = contentMediaType(job);
    return contentHasTranscript(job) && ['audio', 'video', 'file'].includes(mediaType);
}

function renderContentParsePanel(job, parsed = {}) {
    const existing = parsed.mixed_recording_parse;
    const counts = existing?.counts || {};
    if (!contentHasTranscript(job)) {
        return '';
    }

    if (!existing) return '';
    return `
        <div class="content-parse-panel">
            <div class="event-type">Filed Parser Results</div>
            <p style="color:#93c5fd; font-size:12px; margin-top:8px;">
                Parsed ${escapeHtml(formatDateTime(existing.parsed_at))}
                &middot; Tasks ${Number(counts.tasks || 0)}
                &middot; Students ${Number(counts.accountability_events || 0)}
                &middot; Torah ${Number(counts.torah_learning_entries || counts.group_goal_entries || 0)}
            </p>
        </div>
    `;
}

function taskPriorityRank(task) {
    return ({ urgent: 0, today: 1, this_week: 2, low: 3 })[task.urgency] ?? 2;
}

function sortTasks(a, b) {
    const priority = taskPriorityRank(a) - taskPriorityRank(b);
    if (priority !== 0) return priority;
    const dueA = a.due_date ? Date.parse(a.due_date) : Infinity;
    const dueB = b.due_date ? Date.parse(b.due_date) : Infinity;
    if (dueA !== dueB) return dueA - dueB;
    return Date.parse(b.created_at || 0) - Date.parse(a.created_at || 0);
}

function isHiddenCapture(task) {
    const stage = normalizeTaskStage(task.stage);
    const source = String(task.source || '').toLowerCase();
    const title = String(task.title || '');
    const notes = String(task.notes || '');
    const owner = String(task.assigned_to || '').trim();
    const rawSource = ['telegram', 'ramble', 'web'].includes(source);
    const longUnclearCapture = rawSource && !owner && title.length > 130 && (!notes || notes.startsWith(title.slice(0, 60)));
    return stage === 'archive' || stage === 'raw_input' || longUnclearCapture;
}

function taskDisplayTitle(task) {
    const parsed = parseJsonField(task.ai_parsed) || {};
    const storedTitle = String(task.title || '').replace(/\s+/g, ' ').trim();
    const displayTitle = String(task.display_title || '').replace(/\s+/g, ' ').trim();
    const parsedTitle = String(parsed.display_title || '').replace(/\s+/g, ' ').trim();
    const candidates = taskTitleLooksRaw(storedTitle)
        ? [displayTitle, parsedTitle, storedTitle]
        : [displayTitle, storedTitle, parsedTitle];
    const title = candidates.find(candidate => candidate && !taskTitleLooksRaw(candidate)) || candidates.find(Boolean) || 'Untitled task';
    const polished = polishTaskText(title);
    if (polished.length <= 120) return polished;
    const sentenceEnd = polished.search(/[.!?]\s/);
    const sentence = sentenceEnd > 0 ? polished.slice(0, sentenceEnd + 1) : '';
    return sentence && sentence.length <= 120 ? sentence : polished.slice(0, 117).trim() + '...';
}

function taskTitleLooksRaw(value) {
    const text = String(value || '').trim();
    if (!text) return false;
    const lower = text.toLowerCase();
    if (text.length > 150) return true;
    if (/\b(umm+|uh+|you know|i want you to|i need you to|can you|could you|what i want you to do|i don't know)\b/i.test(text)) return true;
    if (text.length > 95 && (lower.match(/\b(and|also|then|so)\b/g) || []).length >= 4) return true;
    return false;
}

function taskDisplayDetail(task, columnId) {
    if (task.verification_notes && (columnId === 'done' || columnId === 'done_activity')) return task.verification_notes;
    if (columnId === 'stale') return taskStaleReasonList(task).join(' / ') || 'Task needs refresh.';
    if (task.cleaned_summary) return task.cleaned_summary;
    const parsed = parseJsonField(task.ai_parsed) || {};
    if (parsed.display_note) return parsed.display_note;
    const title = String(task.title || '').trim();
    const notes = String(task.notes || '').trim();
    const originalText = String(parsed.original_text || '').trim();
    if (originalText && (notes === originalText || title === originalText || notes.includes(originalText.slice(0, 120)))) {
        if (columnId === 'decisions') return 'Missing decision detail - needs research or a clarifying comment.';
        return 'Captured from Telegram and rewritten into a structured task.';
    }
    if (!notes || notes === title) {
        if (columnId === 'decisions') return 'Missing decision detail - needs research or a clarifying comment.';
        return '';
    }
    if (taskIsMachine(task)) {
        const agentDetail = task.result_summary || task.error_message || task.verification_notes || notes;
        if (agentDetail.length > 260) return agentDetail.slice(0, 257).trim() + '...';
        return agentDetail;
    }
    const polished = polishTaskText(notes);
    if (polished.length > 260) return polished.slice(0, 257).trim() + '...';
    return polished;
}

function polishTaskText(text) {
    let value = String(text || '')
        .replace(/\s+/g, ' ')
        .replace(/\b(umm+|uh+|like|you know|basically|okay so|ok so|yeah|right|just|also)\b/gi, ' ')
        .replace(/\b(can you|could you|i need you to|i want you to|you need to|please|no codex|codex|kimi|kimmy|mr kenny)\b/gi, '')
        .replace(/\b(i don't know|i have no idea|what in the world)\b/gi, '')
        .replace(/\s+/g, ' ')
        .trim();

    if (!value) return 'Review captured task';
    const lower = value.toLowerCase();
    if (/natural language/.test(lower) && /task/.test(lower)) {
        return 'Clean raw natural-language wording from the Tasks dashboard';
    }
    if (/(same task file|same page|exact same page|changelog|change log)/.test(lower) && /(kimi|codex|agent|task)/.test(lower)) {
        return 'Keep Codex work on the shared task and changelog ledger';
    }
    if (/(website|homepage)/.test(lower) && /(page number three|page three|3|three|progress)/.test(lower)) {
        return 'Update homepage learning progress to 3 of 30 pages';
    }
    if (/(carousel|image slider|slider|learning moments)/.test(lower) && /(image|drive|intake)/.test(lower)) {
        return 'Use the newest Drive intake images for the homepage Learning Moments carousel';
    }
    if (/(planned briefs?|plan briefs?|implementation briefs?|briefs section|section planned? briefs?)/.test(lower) && /(get rid|remove|don't want|do not want|should never|codex|kodak)/.test(lower)) {
        return 'Remove planned briefs from the operator-facing Tasks dashboard';
    }
    value = value.charAt(0).toUpperCase() + value.slice(1);
    if (/^(fix|build|wire|set up|configure|process|transcribe|send|create|make|run|deploy|sync|finish|add|remove|change|update)\b/i.test(value)) {
        return value;
    }
    if (value.length > 140 || /\b(and then|also|another thing)\b/i.test(value)) {
        return `Review and organize: ${value}`;
    }
    return value;
}

function taskOwnerLabel(task) {
    const owner = String(task.assigned_to || '').trim();
    if (owner) return owner;
    if (task.decision_owner) return `Decision: ${task.decision_owner}`;
    if (task.waiting_on) return `Waiting on ${taskWaitingOnLabel(task.waiting_on)}`;
    const bucket = taskStatusBucket(task);
    if (bucket === 'decisions') return 'Needs decision';
    if (taskMatchesCodexQueue(task)) return 'Codex';
    return 'Unassigned';
}

function taskIsMachine(task) {
    const owner = String(task.assigned_to || '').toLowerCase();
    const kind = String(task.task_kind || '').toLowerCase();
    const agentStatus = String(task.agent_status || task.effective_agent_status || '').toLowerCase();
    return kind === 'agent_job'
        || owner.includes('kimi')
        || owner.includes('codex')
        || owner.includes('system')
        || ['queued', 'running', 'failed', 'blocked_needs_human_decision'].includes(agentStatus);
}

function taskMatchesCodexQueue(task = {}) {
    const agentStatus = String(task.agent_status || task.effective_agent_status || '').toLowerCase();
    if (taskIsMachine(task)) return !['completed'].includes(agentStatus) || !task.completed_at;
    return false;
}

function taskIsRabbi(task) {
    const owner = String(task.assigned_to || '').toLowerCase();
    return owner.includes('rabbi') || owner.includes('scheller') || owner.includes('sheller');
}

function decisionOptionLabels(task) {
    const parsed = parseJsonField(task.ai_parsed) || {};
    const fromColumn = parseJsonField(task.decision_options_json);
    const columnOptions = Array.isArray(fromColumn) ? fromColumn : [];
    const fromParsed = Array.isArray(parsed.options) ? parsed.options : [];
    const text = [task.title, task.notes].filter(Boolean).join('\n');
    const fromText = [...text.matchAll(/\bOption\s+([A-C])\s*:\s*([^\n]+)/gi)]
        .map(match => ({ label: `Option ${match[1].toUpperCase()}`, value: match[2].trim().slice(0, 160) }));
    const sourceOptions = columnOptions.length ? columnOptions : fromParsed;
    const options = sourceOptions.length
        ? sourceOptions.map((option, index) => ({
            sourceLabel: option.label || option.title || '',
            value: option.value || option.text || String(option),
            patch: option.patch || null,
            pros: option.pros || option.upside || option.benefits || [],
            cons: option.cons || option.risks || option.tradeoffs || [],
            consequences: option.consequences || option.consequence || option.outcome || option.result || option.impact_if_chosen || option.next_step || [],
            recommendation: option.recommendation || '',
        }))
        : fromText;
    return options.slice(0, 3).map((option, index) => ({
        keyLabel: `Option ${String.fromCharCode(65 + index)}`,
        label: `Option ${String.fromCharCode(65 + index)}`,
        title: option.sourceLabel && !/^(?:option\s+)?[a-c]\b/i.test(option.sourceLabel)
            ? limitTextClient(option.sourceLabel, 80)
            : '',
        value: option.value || option.label || '',
        patch: option.patch || null,
        pros: decisionTextList(option.pros),
        cons: decisionTextList(option.cons),
        consequences: decisionTextList(option.consequences),
        recommendation: option.recommendation || '',
    }));
}

function decisionQuestionText(value) {
    const text = String(value || '').replace(/\s+/g, ' ').trim();
    if (!text) return 'What decision is needed?';
    if (/[?؟]$/.test(text)) return text;
    const cleaned = text
        .replace(/^decide\s+(whether\s+)?/i, '')
        .replace(/^choose\s+(between\s+)?/i, '')
        .replace(/^pick\s+(between\s+)?/i, '')
        .trim();
    if (/^(what|which|who|when|where|how|should|can|will|do|does|is|are)\b/i.test(cleaned)) return `${cleaned}?`;
    if (/\b(policy|plan|path|approach|option|schedule|price|pricing|scope|workflow)\b/i.test(cleaned)) {
        return `What should the ${cleaned} be?`;
    }
    return `What should we decide about ${cleaned}?`;
}

function decisionTextList(value) {
    if (Array.isArray(value)) return value.map(item => String(item || '').trim()).filter(Boolean).slice(0, 3);
    if (!value) return [];
    return String(value)
        .split(/\n|;|\u2022/g)
        .map(item => item.replace(/^[-*]\s*/, '').trim())
        .filter(Boolean)
        .slice(0, 3);
}

function decisionDetailModel(task = {}) {
    const parsed = parseJsonField(task.ai_parsed) || {};
    const rawDecision = parsed.decision && typeof parsed.decision === 'object' ? parsed.decision : {};
    const options = Array.isArray(rawDecision.options) && rawDecision.options.length
        ? rawDecision.options.map((option, index) => ({
            keyLabel: option.label || `Option ${String.fromCharCode(65 + index)}`,
            label: option.label || `Option ${String.fromCharCode(65 + index)}`,
            title: option.title || option.label || '',
            value: option.description || option.value || option.summary || '',
            patch: option.patch || null,
            pros: decisionTextList(option.upsides || option.pros || option.upside || option.benefits),
            cons: decisionTextList(option.downsides || option.cons || option.risks || option.tradeoffs),
            blockers: decisionTextList(option.blockers || option.blocker),
            consequences: decisionTextList(option.consequences || option.consequence || option.outcome || option.result || option.impact_if_chosen || option.next_step),
            recommendation: option.recommendation || '',
        })).slice(0, 6)
        : decisionOptionLabels(task);
    const question = task.decision_prompt
        || rawDecision.summary
        || parsed.question
        || parsed.decision_question
        || parsed.title
        || taskDisplayTitle(task)
        || 'Decision needed';
    const context = rawDecision.context
        || rawDecision.why_it_exists
        || task.summary
        || parsed.context
        || parsed.summary
        || parsed.reason
        || task.notes
        || '';
    const recommendation = rawDecision.recommendation
        || parsed.recommendation
        || parsed.recommended_option
        || options.find(option => option.recommendation)?.label
        || '';
    const why = rawDecision.why_it_exists
        || parsed.why_it_matters
        || parsed.why
        || parsed.impact
        || parsed.blocker
        || task.next_action
        || '';
    const dueValue = task.due_date || task.planned_at || parsed.due || parsed.due_date || '';
    const status = normalizeDecisionStatusClient(task.decision_status || (task.stage === 'needs_decision' ? 'created' : ''));
    const route = normalizeDecisionRouteClient(task.decision_route || 'none');
    const linkedTaskIds = Array.isArray(rawDecision.linked_task_ids) ? rawDecision.linked_task_ids.map(Number).filter(Boolean) : [];
    const linkedCodexTaskIds = Array.isArray(rawDecision.linked_codex_task_ids) ? rawDecision.linked_codex_task_ids.map(Number).filter(Boolean) : [];
    const links = Array.isArray(rawDecision.links) ? rawDecision.links.filter(Boolean) : [];
    return {
        question: limitTextClient(decisionQuestionText(question), 180),
        summary: limitTextClient(rawDecision.summary || task.summary || taskDisplayTitle(task), 360),
        context: limitTextClient(context, 800),
        research: limitTextClient(rawDecision.research || parsed.research || '', 800),
        recommendation: limitTextClient(recommendation, 120),
        why: limitTextClient(why, 500),
        nextAction: rawDecision.next_action || task.next_action || task.next_action_label || '',
        owner: rawDecision.owner || task.decision_owner || taskOwnerLabel(task),
        waitingOn: rawDecision.waiting_on || task.waiting_on || '',
        blocker: rawDecision.blocker || task.blocked_reason || '',
        due: dueValue ? formatDate(dueValue) : 'No due date',
        workspace: taskProjectLabel(task),
        status,
        statusLabel: decisionStatusLabel(status),
        route,
        routeLabel: decisionRouteLabel(route),
        outcome: task.decision_outcome || rawDecision.outcome || '',
        links,
        linkedTaskIds,
        linkedCodexTaskIds,
        lastCommentSummary: rawDecision.last_comment_summary || '',
        lastActivity: task.decision_last_activity_at || task.last_activity_at || task.updated_at || task.created_at,
        reprocessRequestedAt: task.decision_reprocess_requested_at || '',
        reprocessedAt: task.decision_reprocessed_at || '',
        options
    };
}

function normalizeDecisionStatusClient(value) {
    const status = String(value || '').trim().toLowerCase();
    const allowed = new Set(['created', 'needs_research', 'researching', 'ready_for_decision', 'comment_added', 'reprocess_requested', 'sent_to_codex', 'converted_to_task', 'waiting_on_external_input', 'decided', 'done', 'blocked', 'stale']);
    return allowed.has(status) ? status : 'created';
}

function normalizeDecisionRouteClient(value) {
    const route = String(value || '').trim().toLowerCase();
    const allowed = new Set(['none', 'research', 'codex', 'my_task', 'external_input', 'done', 'hidden']);
    return allowed.has(route) ? route : 'none';
}

function decisionStatusLabel(status) {
    return ({
        created: 'Created',
        needs_research: 'Needs research',
        researching: 'Researching',
        ready_for_decision: 'Ready',
        comment_added: 'Comment added',
        reprocess_requested: 'Reprocess requested',
        sent_to_codex: 'Sent to Codex',
        converted_to_task: 'Converted to task',
        waiting_on_external_input: 'Waiting on input',
        decided: 'Decided',
        done: 'Done',
        blocked: 'Blocked',
        stale: 'Stale',
    })[status] || 'Created';
}

function decisionRouteLabel(route) {
    return ({
        none: 'No route',
        research: 'Research',
        codex: 'Codex',
        my_task: 'My task',
        external_input: 'External input',
        done: 'Done',
        hidden: 'Hidden',
    })[route] || 'No route';
}

function decisionMissingFields(decision = {}) {
    const missing = [];
    if (!String(decision.summary || decision.question || '').trim()) missing.push('summary');
    if (!String(decision.why || decision.context || '').trim()) missing.push('why/context');
    if (!decision.options?.length) missing.push('options');
    if (!String(decision.recommendation || '').trim()) missing.push('recommendation');
    return missing;
}

function decisionIsStale(task = {}, decision = decisionDetailModel(task)) {
    if (!task.decision_status && (task.stage === 'needs_decision' || task.decision_required)) return true;
    if (decision.status === 'stale') return true;
    if (task.decision_reprocess_requested_at && (!task.decision_reprocessed_at || Date.parse(task.decision_reprocess_requested_at) > Date.parse(task.decision_reprocessed_at))) return true;
    if (task.last_comment_at && task.decision_reprocessed_at && Date.parse(task.last_comment_at) > Date.parse(task.decision_reprocessed_at)) return true;
    const last = Date.parse(decision.lastActivity || 0);
    return Boolean(last && Date.now() - last > 7 * 24 * 60 * 60 * 1000 && !['done', 'decided'].includes(decision.status));
}

function renderDecisionMissingWarning(decision) {
    const missing = decisionMissingFields(decision);
    if (!missing.length) return '';
    return `<div class="task-stale-warning">Missing decision detail: ${escapeHtml(missing.join(', '))}. Needs research or a clarifying comment.</div>`;
}

function renderDecisionOptionList(label, values = [], fallback = 'None captured') {
    const items = decisionTextList(values);
    return `
        <div>
            <div class="task-inline-label">${escapeHtml(label)}</div>
            <ul class="task-decision-list">
                ${items.length ? items.map(item => `<li>${escapeHtml(item)}</li>`).join('') : `<li>${escapeHtml(fallback)}</li>`}
            </ul>
        </div>
    `;
}

function renderDecisionOptionCard(taskId, option = {}) {
    const payload = JSON.stringify(option).replace(/"/g, '&quot;');
    const optionTitle = option.title || option.value || 'Captured option';
    const optionBody = option.title && option.value && option.value !== option.title ? option.value : '';
    return `
        <article class="task-decision-option-card">
            <div>
                <span class="task-decision-option-key">${escapeHtml(option.keyLabel || option.label || 'Option')}</span>
                <strong>${escapeHtml(optionTitle)}</strong>
                ${optionBody ? `<p>${escapeHtml(optionBody)}</p>` : ''}
            </div>
            <div class="task-decision-pros-cons">
                ${renderDecisionOptionList('Pros', option.pros)}
                ${renderDecisionOptionList('Cons', option.cons)}
            </div>
            ${option.blockers?.length ? `
                <div class="task-inline-item task-decision-consequences">
                    ${renderDecisionOptionList('Blockers', option.blockers, 'No blockers captured yet')}
                </div>
            ` : ''}
            <div class="task-inline-item task-decision-consequences">
                ${renderDecisionOptionList('Consequences', option.consequences, 'No consequence captured yet')}
            </div>
            ${option.recommendation ? `<div class="task-inline-item"><div class="task-inline-label">Recommendation</div><div class="task-inline-text">${escapeHtml(option.recommendation)}</div></div>` : ''}
            <button class="task-action primary" onclick="taskDecisionAction(event, ${Number(taskId)}, ${payload})">Choose ${escapeHtml(option.keyLabel || option.label || 'option')}</button>
        </article>
    `;
}

function renderTaskDecisionContextCommentForm(task) {
    const id = Number(task.id);
    if (!id) return '';
    return `
        <form class="task-inline-comment-form task-decision-comment-form" onsubmit="addDecisionContextComment(event, ${id})">
            <textarea id="taskDecisionComment-${id}" placeholder="Add decision context, missing information, or why this choice matters..."></textarea>
            <button class="task-action primary" type="submit">Add Decision Comment</button>
        </form>
    `;
}

function renderDecisionOptionAction(taskId, option, verbose = false) {
    const payload = JSON.stringify(option).replace(/"/g, '&quot;');
    const detail = verbose
        ? [
            option.pros?.length ? `Pros: ${option.pros.join('; ')}` : '',
            option.cons?.length ? `Cons: ${option.cons.join('; ')}` : ''
        ].filter(Boolean).join(' | ')
        : '';
    return `
        <button class="task-action primary" onclick="taskDecisionAction(event, ${Number(taskId)}, ${payload})" title="${escapeHtml(detail || option.value || option.label)}">
            ${escapeHtml(verbose ? `${option.label}: ${option.value}` : option.label)}
        </button>
    `;
}

function formatEventType(type) {
    return String(type || '').replace(/_/g, ' ');
}

function allowedViews() {
    const views = Array.isArray(opsMe?.allowedViews) ? opsMe.allowedViews : ['dashboard', 'watchdog', 'pipelines', 'tasks', 'agents', 'platform_suite', 'students', 'contacts', 'community', 'studio', 'content', 'live_classes', 'calendar', 'service_providers', 'communications', 'internal_dialogue', 'accounting', 'automations', 'api_usage', 'admin', 'integrations', 'settings'];
    return new Set(views);
}

function viewAllowed(view) {
    return allowedViews().has(view) && workspaceNavViewIds().includes(view);
}

function firstAllowedViewForWorkspace(workspaceKey = currentWorkspaceKey()) {
    const views = allowedViews();
    const navIds = workspaceNavViewIds(workspaceKey);
    const preferred = currentWorkspaceIsOneTime(workspaceKey)
        ? ['service_providers', 'contacts', 'content', 'tasks']
        : ['dashboard', 'tasks', 'studio'];
    return preferred.find(view => views.has(view) && navIds.includes(view))
        || navIds.find(view => views.has(view))
        || 'dashboard';
}

function ensureCurrentViewAllowedForWorkspace(workspaceKey = currentWorkspaceKey()) {
    const views = allowedViews();
    if (!views.has(currentView) || !workspaceNavViewIds(workspaceKey).includes(currentView)) {
        currentView = firstAllowedViewForWorkspace(workspaceKey);
    }
    return currentView;
}

function isStudioTaskOnlySession() {
    const views = allowedViews();
    const role = String(opsMe?.role || opsMe?.legacy_role || '').toLowerCase();
    const projectKey = normalizeProjectKey(opsMe?.scope?.projectKey || opsMe?.scope?.project_key || opsMe?.project_key || '');
    return opsMe?.scope?.type === 'project'
        && projectKey === 'one_time_mishnah_class'
        && ['one_time_ai_studio_operator', 'one_time_ai_video_worker'].includes(role)
        && views.has('studio')
        && views.has('tasks')
        && views.size <= 2;
}

function normalizeProjectKey(value) {
    const key = String(value || '')
        .trim()
        .toLowerCase()
        .replace(/['"]/g, '')
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
    if (!key) return 'bna';
    if (['one_time', 'one_time_mishna', 'one_time_mishnah', 'one_time_mishna_class', 'mishna', 'mishnah', 'mishna_learning', 'mishnah_learning'].includes(key)) {
        return 'one_time_mishnah_class';
    }
    if (['bnei_neviim', 'bnei_neviim_academy', 'academy'].includes(key)) return 'bna';
    return key;
}

function normalizeWorkspaceKey(value) {
    const key = String(value || '')
        .trim()
        .toLowerCase()
        .replace(/['"]/g, '')
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '');
    if (!key) return '';
    if (['platform', 'super_admin', 'superadmin', 'agency', 'operations', 'ops'].includes(key)) return 'platform';
    if (['bna', 'school', 'bna_school', 'bna_school_workspace', 'bnei_neviim', 'bnei_neviim_academy', 'academy'].includes(key)) return 'bna';
    if (['provider', 'one_time', 'one_time_mishna', 'one_time_mishnah', 'one_time_mishna_class', 'one_time_mishnah_class', 'mishna', 'mishnah', 'rabbi_elie', 'rabbi_elie_scheller', 'rabbi_sheller', 'rabbi_sheller_provider'].includes(key)) return 'rabbi_sheller_provider';
    return key;
}

function workspaceFromProjectKey(projectKey) {
    const project = normalizeProjectKey(projectKey);
    if (project === 'one_time_mishnah_class') return 'rabbi_sheller_provider';
    return project === 'bna' ? 'bna' : normalizeWorkspaceKey(project);
}

function projectKeyForWorkspaceKey(workspaceKey = currentWorkspaceKey()) {
    const key = normalizeWorkspaceKey(workspaceKey);
    if (key === 'platform') return 'all';
    if (key === 'bna') return 'bna';
    if (key === 'rabbi_sheller_provider') return 'one_time_mishnah_class';
    const record = workspaceDirectoryRecords().find(workspace => workspaceRecordKey(workspace) === key);
    const targetProject = record?.target?.project && record.target.project !== 'all' ? record.target.project : '';
    return normalizeProjectKey(record?.project_key || targetProject || '') || 'all';
}

function contentDataProjectFilters(workspaceKey = currentWorkspaceKey()) {
    const projectKey = projectKeyForWorkspaceKey(workspaceKey);
    return projectKey && projectKey !== 'all' ? { project_key: projectKey } : {};
}

function studioDataProjectFilters(workspaceKey = currentWorkspaceKey()) {
    const projectKey = projectKeyForWorkspaceKey(workspaceKey);
    const workspace = normalizeWorkspaceKey(workspaceKey);
    const filters = {};
    if (workspace && workspace !== 'platform') filters.workspace = workspace;
    if (projectKey && projectKey !== 'all') filters.project_key = projectKey;
    return filters;
}

function communityDataProjectFilters(workspaceKey = currentWorkspaceKey()) {
    const projectKey = projectKeyForWorkspaceKey(workspaceKey);
    return projectKey && projectKey !== 'all' ? { project_key: projectKey } : {};
}

function liveClassDataProjectFilters(workspaceKey = currentWorkspaceKey()) {
    const projectKey = projectKeyForWorkspaceKey(workspaceKey);
    return projectKey && projectKey !== 'all' ? { project_key: projectKey } : {};
}

function workspaceDataProjectFilters(workspaceKey = currentWorkspaceKey()) {
    const projectKey = projectKeyForWorkspaceKey(workspaceKey);
    const normalizedWorkspace = normalizeWorkspaceKey(workspaceKey);
    return projectKey && projectKey !== 'all'
        ? { project_key: projectKey, workspace: normalizedWorkspace }
        : {};
}

function selectedStudentDetailDataFilters(workspaceKey = currentWorkspaceKey()) {
    const filters = { ...workspaceDataProjectFilters(workspaceKey) };
    const inSelectedStudentDetail = currentView === 'students'
        && selectedStudentId
        && !['overview', 'list', 'group_goal', 'next_year_login'].includes(studentSection);
    if (inSelectedStudentDetail) filters.student_id = selectedStudentId;
    return filters;
}

function currentWorkspaceIsGlobal(workspaceKey = currentWorkspaceKey()) {
    const key = normalizeWorkspaceKey(workspaceKey);
    return !key || key === 'platform' || key === 'super_admin';
}

function currentWorkspaceIsOneTime(workspaceKey = currentWorkspaceKey()) {
    return projectKeyForWorkspaceKey(workspaceKey) === 'one_time_mishnah_class';
}

function communityWorkspaceProfile(workspaceKey = currentWorkspaceKey()) {
    const key = normalizeWorkspaceKey(workspaceKey);
    const record = workspaceDirectoryRecords().find(workspace => workspaceRecordKey(workspace) === key);
    if (currentWorkspaceIsGlobal(key)) {
        return {
            title: 'All Communities',
            subtitle: 'Explicit global community view',
            kicker: 'Community',
            overviewLabel: 'Global community overview',
            itemFallback: 'Community item',
            emptyCourses: 'No community courses are loaded for this global view.',
        };
    }
    if (key === 'rabbi_sheller_provider') {
        return {
            title: 'One Time Mishnayos Community',
            subtitle: 'Rabbi Elie Scheller workspace',
            kicker: 'Provider Community',
            overviewLabel: 'One Time community overview',
            itemFallback: 'Mishnayos community',
            emptyCourses: 'No One Time community courses are loaded yet.',
        };
    }
    if (key === 'bna') {
        return {
            title: 'BNA Community',
            subtitle: 'School workspace community',
            kicker: 'School Community',
            overviewLabel: 'BNA community overview',
            itemFallback: 'BNA community',
            emptyCourses: 'No BNA community courses are loaded yet.',
        };
    }
    if (workspaceNavProfile(key) === 'family') {
        return {
            title: 'Family Community',
            subtitle: record?.name || 'Family workspace context',
            kicker: 'Family Community',
            overviewLabel: 'Family community overview',
            itemFallback: 'Family community',
            emptyCourses: 'No family community items are loaded yet.',
        };
    }
    return {
        title: record?.name ? `${record.name} Community` : 'Workspace Community',
        subtitle: record?.display_category_label || record?.type_label || 'Workspace-specific community',
        kicker: 'Workspace Community',
        overviewLabel: 'Workspace community overview',
        itemFallback: 'Workspace community',
        emptyCourses: 'No workspace community courses are loaded yet.',
    };
}

function currentWorkspaceKey() {
    if (currentWorkspaceId) return normalizeWorkspaceKey(currentWorkspaceId);
    const scopedProject = normalizeProjectKey(opsMe?.scope?.projectKey || '');
    if (opsMe?.scope?.type === 'project' || scopedProject === 'one_time_mishnah_class') return workspaceFromProjectKey(scopedProject);
    return 'platform';
}

function currentWorkspaceRecord() {
    const key = currentWorkspaceKey();
    return workspaceDirectoryRecords().find(workspace => workspaceRecordKey(workspace) === key)
        || workspaceDirectoryRecords().find(workspace => workspaceRecordKey(workspace) === 'platform')
        || WORKSPACE_FALLBACKS[0];
}

function currentWorkspaceRoleLabel() {
    const key = currentWorkspaceKey();
    const type = workspaceTypeForKey(key);
    if (['platform', 'super_admin'].includes(type) || key === 'platform') return 'Super Admin';
    if (type === 'service_provider') {
        if (opsMe?.workspace_role_label) return opsMe.workspace_role_label;
        if (opsMe?.canonical_role_label && opsMe?.workspace_role) return opsMe.canonical_role_label;
        if (opsMe?.role === 'project_owner') return 'Workspace Owner';
        if (opsMe?.role === 'project_manager') return 'Workspace Manager';
        return opsMe?.role === 'one_time_admin' ? 'Provider Admin' : 'Provider Workspace Admin';
    }
    if (type === 'family') return 'Family Owner';
    if (type === 'household') return 'Family Admin';
    if (type === 'school') return 'BNA Admin';
    return 'BNA Admin';
}

function workspaceNavProfile(workspaceKey = currentWorkspaceKey()) {
    const key = normalizeWorkspaceKey(workspaceKey) || 'platform';
    const type = workspaceTypeForKey(key);
    if (key === 'platform' || ['platform', 'super_admin'].includes(type)) return 'platform';
    if (type === 'school' || key === 'bna') return 'bna';
    if (type === 'service_provider') return 'service_provider';
    if (type === 'family') return 'family';
    if (type === 'household') return 'household';
    return 'platform';
}

function oneTimeDashboardIa() {
    const ia = window.ONE_TIME_RABBI_DASHBOARD_IA;
    return ia && Array.isArray(ia.main_modules) ? ia : null;
}

function markerForLabel(label = '') {
    const words = String(label || '')
        .replace(/&/g, ' ')
        .split(/\s+/)
        .map(word => word.replace(/[^A-Za-z0-9]/g, ''))
        .filter(Boolean);
    const marker = words.slice(0, 2).map(word => word[0]).join('').toUpperCase();
    return marker || String(label || 'OP').slice(0, 2).toUpperCase();
}

function oneTimeIaSubsection(module = {}) {
    const ia = oneTimeDashboardIa();
    const sections = ia?.section_subsection_map?.[module.id]?.subsections || [];
    return sections.find(section => section.id === module.default_section) || sections[0] || null;
}

function oneTimeProviderPrimaryNavItems() {
    const ia = oneTimeDashboardIa();
    if (!ia) return [];
    return ia.main_modules.map(module => {
        const subsection = oneTimeIaSubsection(module);
        const label = module.short_label || module.label || module.id;
        return {
            id: subsection?.source_view || module.operations_view || 'service_providers',
            navKey: module.id,
            section: subsection?.source_section || module.default_section || 'overview',
            label,
            marker: markerForLabel(label),
            iaModule: module
        };
    });
}

function workspaceNavViewIds(workspaceKey = currentWorkspaceKey()) {
    const profile = workspaceNavProfile(workspaceKey);
    if (profile === 'service_provider' && currentWorkspaceIsOneTime(workspaceKey)) {
        return Array.from(new Set(oneTimeProviderPrimaryNavItems().map(item => item.id))).filter(Boolean);
    }
    const nav = {
        platform: ['dashboard', 'watchdog', 'admin', 'tasks', 'agents', 'platform_suite', 'students', 'contacts', 'community', 'studio', 'content', 'live_classes', 'calendar', 'service_providers', 'communications', 'pipelines', 'accounting', 'automations', 'integrations', 'api_usage', 'settings'],
        bna: ['dashboard', 'watchdog', 'tasks', 'agents', 'platform_suite', 'students', 'contacts', 'community', 'content', 'live_classes', 'calendar', 'communications', 'service_providers', 'accounting', 'automations', 'integrations', 'settings'],
        service_provider: ['dashboard', 'watchdog', 'service_providers', 'agents', 'contacts', 'community', 'studio', 'content', 'live_classes', 'calendar', 'communications', 'tasks', 'automations', 'integrations', 'api_usage', 'settings'],
        family: ['dashboard', 'contacts', 'tasks', 'calendar', 'communications', 'service_providers', 'settings'],
        household: ['dashboard', 'contacts', 'tasks', 'calendar', 'communications', 'service_providers', 'settings']
    };
    return nav[profile] || nav.platform;
}

