function renderSupportTicketCard(ticket) {
    const severityLabel = String(ticket.severity || 'normal').replace(/_/g, ' ');
    const statusLabel = String(ticket.status || 'open').replace(/_/g, ' ');
    return `
        <article class="task-card">
            <div class="task-card-header">
                <div>
                    <div class="task-title">${escapeHtml(ticket.title || 'Untitled ticket')}</div>
                    <div class="task-meta">
                        <span>${escapeHtml(statusLabel)}</span>
                        <span>${escapeHtml(severityLabel)}</span>
                        <span>${escapeHtml(String(ticket.category || 'other').replace(/_/g, ' '))}</span>
                        <span>${escapeHtml(formatDateTime(ticket.created_at))}</span>
                    </div>
                </div>
            </div>
            ${ticket.description ? `<p class="task-notes">${escapeHtml(ticket.description)}</p>` : ''}
            <div class="task-actions">
                ${ticket.status !== 'triage' ? `<button onclick="updateSupportTicketStatus(${Number(ticket.id)}, 'triage')">Triage</button>` : ''}
                ${ticket.status !== 'in_progress' ? `<button onclick="updateSupportTicketStatus(${Number(ticket.id)}, 'in_progress')">Start</button>` : ''}
                ${ticket.status !== 'resolved' ? `<button onclick="updateSupportTicketStatus(${Number(ticket.id)}, 'resolved')">Resolve</button>` : ''}
                ${ticket.related_task_id ? `<button onclick="switchView('tasks')">Task #${Number(ticket.related_task_id)}</button>` : ''}
            </div>
        </article>
    `;
}

