        if (liveSessionsRes.status === 'fulfilled' && liveSessionsRes.value?.sessions) liveSessions = liveSessionsRes.value.sessions;
        if (contentPromptsRes.status === 'fulfilled' && contentPromptsRes.value?.prompts) contentPrompts = contentPromptsRes.value.prompts;
        if (contentBundlesRes.status === 'fulfilled' && contentBundlesRes.value?.bundles) contentBundles = contentBundlesRes.value.bundles;
