async function refreshOperationsAssistantAgentStatus() {
    operationsAssistantStatus = 'Checking assistant control center...';
    render();
    try {
        const [agentStatus, controlCenter] = await Promise.all([
            api.getAssistantAgentStatus(12),
            api.getAssistantControlCenter()
        ]);
        operationsAssistantAgentStatus = agentStatus;
        operationsAssistantControlCenter = controlCenter;
        const queue = operationsAssistantAgentStatus?.queue || {};
        const blockers = (operationsAssistantControlCenter?.blockers || []).length;
        operationsAssistantStatus = `Codex: ${Number(queue.queued || queue.pending || 0)} queued, ${Number(queue.running || queue.in_progress || 0)} running, ${Number(queue.blocked || queue.needs_decision || 0)} blocked. Control Center: ${blockers} blocker${blockers === 1 ? '' : 's'}.`;
    } catch (error) {
        operationsAssistantStatus = error.message || 'Could not load assistant control center.';
    }
    render();
}

function quickOperationsAssistantPrompt(text) {
    const input = document.getElementById('operationsAssistantInput');
    if (!input) return;
    input.value = text;
    input.focus();
}

async function submitOperationsAssistantMessage(event) {
    event?.preventDefault?.();
    const input = document.getElementById('operationsAssistantInput');
    const message = String(input?.value || '').trim();
    if (!message || operationsAssistantBusy) return;
    operationsAssistantBusy = true;
    operationsAssistantStatus = 'Sending to assistant...';
    operationsAssistantMessages.push({ role: 'You', body: message, actions: [] });
    render();
    try {
        const result = await api.sendAssistantMessage({
            message,
            mode: 'operator',
            surface: 'operations',
            page_path: `${window.location.pathname}${window.location.search}`,
            context: {
                view: currentView,
                section: currentSectionId(),
                workspace_key: currentWorkspaceKey()
            }
        });
        operationsAssistantMessages.push({
            role: 'Assistant',
            body: result?.assistant_message?.body || result?.assistant_message?.content || 'Saved.',
            actions: result?.actions || []
        });
        operationsAssistantStatus = (result?.actions || []).length
            ? `${result.actions.length} action${result.actions.length === 1 ? '' : 's'} recorded.`
            : 'Assistant replied without a write action.';
        if ((result?.actions || []).some(action => ['create_ticket', 'create_task'].includes(action.action_type))) {
            await loadData({ background: true });
        } else {
            render();
        }
        if (input) input.value = '';
    } catch (error) {
        operationsAssistantMessages.push({ role: 'Assistant', body: error.message || 'Assistant request failed.', actions: [] });
        operationsAssistantStatus = error.message || 'Assistant request failed.';
        render();
    } finally {
        operationsAssistantBusy = false;
        render();
    }
}

async function createAdminOpsAccessLink(username, returnTo) {
    const targetUsername = String(username || '').trim();
    if (!targetUsername) {
        adminAccessLinkError = 'Operations login username is not configured for this external user.';
        adminAccessLinkResult = null;
        render();
        return;
    }
    adminAccessLinkPendingUsername = targetUsername;
    adminAccessLinkError = '';
    adminAccessLinkResult = null;
    render();
    try {
        const data = await api.createOpsAccessLink({
            username: targetUsername,
            return_to: returnTo || '/operations?workspace=rabbi_sheller_provider&view=tasks',
            purpose: 'super_admin_external_user_access'
        });
        adminAccessLinkResult = data;
    } catch (err) {
        adminAccessLinkError = err.message || 'Could not create access link.';
    } finally {
        adminAccessLinkPendingUsername = '';
        render();
    }
}

async function copyAdminAccessLink() {
    if (!adminAccessLinkResult?.url) return;
    try {
        await navigator.clipboard.writeText(adminAccessLinkResult.url);
        adminAccessLinkError = '';
    } catch {
        adminAccessLinkError = 'Copy failed. Select the link text manually from this panel.';
    }
    render();
}

