async function workspaceUserMembershipAction(membershipId, action) {
    const id = String(membershipId || '').trim();
    const nextAction = String(action || '').trim();
    if (!id || !nextAction) return;
    const labels = {
        deactivate: 'deactivate this membership',
        reactivate: 'reactivate this membership',
        remove_membership: 'archive this membership'
    };
    if (nextAction !== 'reactivate' && !confirm(`Confirm ${labels[nextAction] || nextAction}. No invite, email, WhatsApp, password, billing, or external app action will run.`)) return;
    workspaceUserActionBusy = `${nextAction}:${id}`;
    workspaceUserActionError = '';
    workspaceUserActionNotice = '';
    render();
    try {
        const result = await api.updateWorkspaceUser(id, {
            action: nextAction,
            reason: `Operations ${nextAction.replace(/_/g, ' ')} action`,
            no_send: true
        });
        workspaceUserActionNotice = `${result?.user?.person_name || 'Workspace user'} membership ${nextAction.replace(/_/g, ' ')} completed.`;
        await loadData({ background: true });
    } catch (err) {
        workspaceUserActionError = err.message || 'Could not update workspace membership.';
    } finally {
        workspaceUserActionBusy = '';
        render();
    }
}

