async function submitSupportTicketForm(event) {
    event?.preventDefault?.();
    const form = document.getElementById('supportTicketForm');
    const button = document.getElementById('supportTicketSubmit');
    const titleInput = (document.getElementById('supportTicketTitle')?.value || '').trim();
    const issue = (document.getElementById('supportTicketDescription')?.value || '').trim();
    const expected = (document.getElementById('supportTicketExpected')?.value || '').trim();
    const severityInput = (document.getElementById('supportTicketSeverity')?.value || 'normal').toLowerCase();
    const category = document.getElementById('supportTicketCategory')?.value || 'task_manager';
    const severity = ['low', 'normal', 'high', 'blocking'].includes(severityInput) ? severityInput : 'normal';
    const description = [
        issue ? `Issue:\n${issue}` : '',
        expected ? `Expected result:\n${expected}` : ''
    ].filter(Boolean).join('\n\n');
    const title = titleInput || issue.slice(0, 140) || expected.slice(0, 140) || 'Support report';
    supportTicketDraft = { title: titleInput, description: issue, expected, severity, category };
    if (!titleInput && !issue && !expected) {
        supportTicketFormError = 'Add the issue or expected result before creating the ticket.';
        render();
        requestAnimationFrame(() => document.getElementById('supportTicketDescription')?.focus());
        return;
    }
    if (button) {
        button.disabled = true;
        button.textContent = 'Submitting...';
    }
    if (form) form.setAttribute('aria-busy', 'true');
    try {
        await api.createSupportTicket({
            title,
            description,
            severity,
            category,
            source: 'dashboard',
            source_context: currentSupportTicketSourceContext()
        });
        supportTicketModalOpen = false;
        supportTicketFormError = '';
        resetSupportTicketDraft();
        openSupportTicketResultView();
        syncOperationsUrl();
        await loadData();
    } catch (error) {
        supportTicketFormError = error.message || 'Could not create the support ticket.';
        render();
        requestAnimationFrame(() => document.getElementById('supportTicketDescription')?.focus());
    }
}

