async function sendPaymentReminders(event) {
    event?.preventDefault();
    const typed = prompt('Type SEND_REMINDERS to send live payment reminder emails.');
    if (typed !== 'SEND_REMINDERS') return;
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        paymentReminderPreview = await api.runPaymentReminders({
            dryRun: false,
            confirm: 'SEND_REMINDERS'
        });
        alert(`Sent ${paymentReminderPreview.sent?.length || 0} reminder(s). Failed: ${paymentReminderPreview.failed?.length || 0}.`);
        await loadData();
    } catch (error) {
        alert(error.message);
    } finally {
        if (button) button.disabled = false;
    }
}

