async function saveOneTimeHostedMediaUrl(event, jobId) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const id = Number(jobId || 0);
    const job = contentJobs.find(item => Number(item.id) === id);
    if (!job) return alert('This One Time content item is not loaded.');
    const current = contentHostedMediaUrl(job);
    const url = prompt('Hosted media URL for this One Time library item:', current || '');
    if (url === null) return;
    const trimmed = String(url || '').trim();
    if (trimmed && !/^https?:\/\//i.test(trimmed)) return alert('Use a full hosted URL starting with http:// or https://.');
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        await api.updateContentJob(id, { media_url: trimmed || null });
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not save hosted media URL.');
    } finally {
        if (button) button.disabled = false;
    }
}

