async function addInterestedParentLead(event) {
    event?.preventDefault?.();
    const parentName = (prompt('Parent name:') || '').trim();
    if (!parentName) return;
    const phone = (prompt('Phone or WhatsApp, if available:', '') || '').trim();
    const email = (prompt('Email, if available:', '') || '').trim();
    const studentName = (prompt('Student name, if known:', '') || '').trim();
    const interestInput = (prompt('Interest level: hot, warm, cool, or unknown', 'warm') || 'warm').trim().toLowerCase();
    const interestLevel = ['hot', 'warm', 'cool', 'unknown'].includes(interestInput) ? interestInput : 'unknown';
    const followUpDate = (prompt('Next follow-up date (YYYY-MM-DD), optional:', '') || '').trim();
    if (followUpDate && !/^\d{4}-\d{2}-\d{2}$/.test(followUpDate)) {
        alert('Use YYYY-MM-DD for the follow-up date.');
        return;
    }
    const notes = (prompt('Initial note or contact history:', '') || '').trim();
    const tagInput = prompt('Tags, comma-separated:', 'school-interest, manual-capture');
    const tags = normalizeLeadTagInput(tagInput === null ? 'school-interest, manual-capture' : tagInput);
    const status = followUpDate ? 'follow_up' : 'interested';

    try {
        const result = await api.createParentLead({
            parent_name: parentName,
            parent_phone: phone || null,
            parent_email: email || null,
            student_name: studentName || null,
            lead_type: 'school_interest',
            status,
            interest_level: interestLevel,
            source: 'manual',
            source_detail: 'Operations Contacts manual interested-parent capture',
            next_follow_up_date: followUpDate || null,
            owner: 'Shloimie',
            tags,
            notes: notes || null,
            metadata: { created_from: 'operations_interested_parent_pipeline' },
        });

        if (!result?.lead) {
            const matched = result?.matched_existing;
            alert(matched
                ? `A matching ${matched.kind || 'record'} already exists for this parent.`
                : 'No new lead was created.');
            await loadData();
            return;
        }

        const leadId = Number(result.lead.id);
        if (leadId && notes) {
            await api.createContactCommunication({
                contact_type: 'lead',
                lead_id: leadId,
                channel: 'internal_note',
                direction: 'internal_note',
                summary: `Initial lead note for ${parentName}`,
                body: notes,
                follow_up_required: Boolean(followUpDate),
                source: 'dashboard',
                source_context: { created_from: 'operations_interested_parent_pipeline' },
            });
        }

        currentView = 'contacts';
        contactSection = 'interested_parents';
        contactLeadTypeFilter = 'all';
        contactLeadStatusFilter = 'all';
        contactInterestFilter = 'all';
        selectedLeadId = leadId || null;
        syncOperationsUrl();
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not add interested parent.');
    }
}

