async function updateLeadQuick(leadId, updates = {}) {
    const id = Number(leadId);
    if (!id) return alert('Lead not found.');
    try {
        const result = await api.updateParentLead(id, updates);
        if (result?.lead) {
            parentLeads = parentLeads.map(lead => Number(lead.id) === id ? result.lead : lead);
        } else {
            await loadData();
            return;
        }
        selectedLeadId = updates.status === 'archived' ? null : id;
        render();
    } catch (error) {
        alert(error.message || 'Could not update lead.');
    }
}

async function setLeadNextFollowUp(leadId) {
    const id = Number(leadId);
    const lead = parentLeads.find(item => Number(item.id) === id);
    if (!lead) return alert('Lead not found.');
    const currentDate = lead.next_follow_up_date ? String(lead.next_follow_up_date).slice(0, 10) : '';
    const entered = prompt('Next follow-up date (YYYY-MM-DD). Leave blank to clear.', currentDate);
    if (entered === null) return;
    const nextDate = String(entered || '').trim();
    if (nextDate && !/^\d{4}-\d{2}-\d{2}$/.test(nextDate)) {
        alert('Use YYYY-MM-DD for the follow-up date.');
        return;
    }
    const updates = { next_follow_up_date: nextDate || null };
    if (nextDate && ['new', 'interested', 'lead_candidate'].includes(leadStatusKey(lead))) {
        updates.status = 'follow_up';
    }
    await updateLeadQuick(id, updates);
}

async function addLeadCommunication(leadId) {
    const id = Number(leadId);
    const lead = parentLeads.find(item => Number(item.id) === id);
    if (!lead) return alert('Lead not found.');
    const summary = prompt('Short summary for this contact note:', `Follow-up with ${lead.parent_name || 'lead'}`);
    if (summary === null) return;
    const cleanSummary = String(summary || '').trim();
    if (!cleanSummary) return alert('Summary is required.');
    const body = prompt('Details or next step:', '');
    if (body === null) return;
    const followUpRequired = confirm('Should this stay flagged for follow-up?');
    try {
        await api.createContactCommunication({
            contact_type: 'lead',
            lead_id: id,
            channel: 'internal_note',
            direction: 'internal_note',
            summary: cleanSummary,
            body: String(body || '').trim(),
            follow_up_required: followUpRequired,
            source: 'dashboard',
        });
        selectedLeadId = id;
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not save communication note.');
    }
}

