async function createGoalBoardItem(event, studentId) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const source = document.getElementById(`goal-source-${studentId}`)?.value || 'admin';
    const title = document.getElementById(`goal-title-${studentId}`)?.value || '';
    const dueAt = document.getElementById(`goal-due-${studentId}`)?.value || '';
    const targetValue = document.getElementById(`goal-target-${studentId}`)?.value || '';
    const targetUnit = document.getElementById(`goal-unit-${studentId}`)?.value || '';
    const youtubeUrl = document.getElementById(`goal-youtube-${studentId}`)?.value || '';
    const bedtimeTime = document.getElementById(`goal-bedtime-${studentId}`)?.value || '';
    const wakeTime = document.getElementById(`goal-wake-${studentId}`)?.value || '';
    const studentCommitment = document.getElementById(`goal-commitment-${studentId}`)?.value || '';
    const recoveryPath = document.getElementById(`goal-recovery-${studentId}`)?.value || '';
    const deviceState = document.getElementById(`goal-device-${studentId}`)?.value || '';
    const deviceDuration = document.getElementById(`goal-device-duration-${studentId}`)?.value || '';
    const successDeviceState = document.getElementById(`goal-success-device-${studentId}`)?.value || '';
    const successDuration = document.getElementById(`goal-success-duration-${studentId}`)?.value || '';
    const reviewReason = document.getElementById(`goal-review-reason-${studentId}`)?.value || '';
    const approvalRequired = Boolean(document.getElementById(`goal-approval-${studentId}`)?.checked || deviceState);

    if (!title.trim()) return alert('Title is required.');

    const button = event?.submitter || event?.currentTarget?.querySelector('button[type="submit"]');
    if (button) button.disabled = true;
    try {
        await api.createGoalBoardItem(studentId, {
            title,
            source,
            urgency: document.getElementById(`goal-urgency-${studentId}`)?.value || 'this_week',
            category: document.getElementById(`goal-category-${studentId}`)?.value || '',
            due_at: dueAt || null,
            target_value: targetValue ? Number(targetValue) : null,
            target_unit: targetUnit || null,
            youtube_url: youtubeUrl,
            agreement_type: bedtimeTime || wakeTime ? 'bedtime_wakeup' : '',
            bedtime_time: bedtimeTime,
            wake_time: wakeTime,
            student_commitment: studentCommitment,
            chosen_consequence: reviewReason,
            student_summary: document.getElementById(`goal-summary-${studentId}`)?.value || '',
            student_visible: Boolean(document.getElementById(`goal-share-student-${studentId}`)?.checked),
            parent_visible: Boolean(document.getElementById(`goal-share-parent-${studentId}`)?.checked),
            private_note: document.getElementById(`goal-private-${studentId}`)?.value || '',
            recovery_path: recoveryPath,
            device_access_state: deviceState,
            duration_minutes: deviceDuration ? Number(deviceDuration) : null,
            auto_apply_on_completion: Boolean(successDeviceState),
            success_device_access_state: successDeviceState,
            success_duration_minutes: successDuration ? Number(successDuration) : null,
            review_reason: reviewReason,
            approval_required: approvalRequired
        });
        await loadData();
        studentGoalFilter = approvalRequired ? 'needs_review' : 'due_today';
        render();
    } catch (error) {
        alert(error.message || 'Could not create Goal Board item.');
    } finally {
        if (button) button.disabled = false;
    }
}

