async function performDeviceAction(event, deviceId, status, defaultDuration = null) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const normalizedStatus = normalizeDeviceAccessState(status);
    const needsDuration = ['approved_access', 'manual_override'].includes(normalizedStatus);
    const reason = prompt('Reason for mock device state change:', deviceAccessLabel(normalizedStatus)) || '';
    if (needsDuration) {
        const durationInput = prompt('Duration in minutes:', String(defaultDuration || 60));
        if (durationInput === null) return;
        defaultDuration = Math.max(1, Math.min(1440, Math.round(Number(durationInput) || 60)));
    }
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        await api.deviceAction(deviceId, {
            status: normalizedStatus,
            duration_minutes: defaultDuration,
            reason
        });
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not record mock device action.');
    } finally {
        if (button) button.disabled = false;
    }
}

async function reviewDeviceAccess(event, goalId, deviceId, action, defaultDuration = null) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    if (action !== 'deny' && !deviceId) {
        alert('Add a mock tablet before applying a device state.');
        return;
    }
    let duration = defaultDuration || 60;
    if (['approve', 'manual_override'].includes(action)) {
        const durationInput = prompt('Access duration in minutes:', String(duration));
        if (durationInput === null) return;
        duration = Math.max(1, Math.min(1440, Math.round(Number(durationInput) || duration)));
    }
    const reason = prompt('Review note:', action === 'deny' ? 'Denied device state after review' : 'Parent/admin approved mock access state') || '';
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        await api.reviewDeviceAccess(goalId, {
            action,
            device_id: deviceId || null,
            duration_minutes: duration,
            reason
        });
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not record device access review.');
    } finally {
        if (button) button.disabled = false;
    }
}

