async function addTaskComment(event) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    if (!editingTask?.id) return;
    const textarea = document.getElementById('taskNewComment');
    const body = textarea?.value || '';
    if (!body.trim()) return alert('Comment is empty.');
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        await api.addTaskComment(editingTask.id, {
            body,
            author: 'dashboard',
            visibility: taskCommentDefaultVisibility(editingTask),
            source: 'dashboard',
            requeue: false
        });
        if (textarea) textarea.value = '';
        const result = await api.getTaskComments(editingTask.id);
        taskComments = result?.comments || [];
        await loadData();
        editingTask = tasks.find(t => Number(t.id) === Number(editingTask.id)) || editingTask;
        render();
        document.getElementById('taskModal').classList.add('show');
    } catch (error) {
        alert(error.message || 'Could not add comment.');
    } finally {
        if (button) button.disabled = false;
    }
}

async function addInlineTaskComment(event, taskId) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const id = Number(taskId);
    if (!id) return;
    const textarea = document.getElementById(`taskInlineComment-${id}`);
    const body = textarea?.value || '';
    if (!body.trim()) return alert('Comment is empty.');
    const button = event?.submitter || event?.currentTarget?.querySelector('button[type="submit"]');
    if (button) button.disabled = true;
    try {
        const saved = await api.addTaskComment(id, {
            body,
            author: 'dashboard',
            visibility: taskCommentDefaultVisibility(tasks.find(task => Number(task.id) === id) || {}),
            source: 'dashboard',
            requeue: false,
            request_reprocess: true,
            source_context: {
                action: 'comment_added',
                request_reprocess: true,
            }
        });
        const decisionEvent = saved?.decision_event || {};
        taskWorkflowNotice = decisionEvent.message
            ? `Decision #${id}: ${decisionEvent.message} Status: ${decisionStatusLabel(decisionEvent.status_after || 'comment_added')}.`
            : `Decision #${id}: comment saved.`;
        if (textarea) textarea.value = '';
        const result = await api.getTaskComments(id);
        const comments = result?.comments || [];
        expandedTaskComments = {
            ...expandedTaskComments,
            [id]: comments,
        };
        taskComments = editingTask && Number(editingTask.id) === id ? comments : taskComments;
        tasks = tasks.map(task => Number(task.id) === id ? {
            ...task,
            ...(saved?.task || {}),
            comment_count: comments.length,
        } : task);
        render();
    } catch (error) {
        alert(error.message || 'Could not add comment.');
    } finally {
        if (button) button.disabled = false;
    }
}

