async function saveTaskAgentModeDropoff(event, taskId) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const id = Number(taskId || 0);
    const form = event?.currentTarget;
    if (!id || !form) return;
    const task = tasks.find(item => Number(item.id) === id) || {};
    const review = task.agent_mode_review || {};
    const payload = Object.fromEntries(new FormData(form).entries());
    payload.task_id = id;
    payload.agent_review_run_id = review.copy_metadata?.agent_review_run_id || payload.agent_review_run_id || '';
    payload.return_url = review.exact_return_url || payload.return_url || `/operations?view=tasks&task=${id}`;
    payload.dropoff_url = review.exact_dropoff_url || payload.dropoff_url || `/operations/agent-review/dropoff?task_id=${id}`;
    payload.current_route = window.location.pathname + window.location.search;
    payload.summary = payload.summary || String(payload.report_text || '').slice(0, 4000);
    const statusEl = document.getElementById(`taskAgentModeSaveStatus-${id}`);
    const button = event?.submitter || form.querySelector('button[type="submit"]');
    if (button) button.disabled = true;
    if (statusEl) statusEl.textContent = 'Saving...';
    try {
        const result = await api.submitAgentReviewResult(payload);
        if (result?.task) {
            tasks = tasks.map(item => Number(item.id) === id ? { ...item, ...result.task } : item);
        } else if (result?.task_agent_mode_review) {
            tasks = tasks.map(item => Number(item.id) === id ? { ...item, agent_mode_review: result.task_agent_mode_review } : item);
        }
        if (statusEl) {
            const viewLink = result?.readback_url ? ` <a href="${escapeHtml(result.readback_url)}" target="_blank" rel="noopener">View saved result</a>` : '';
            statusEl.innerHTML = `Saved ${escapeHtml(result?.result_ref || 'AGR result')}.${viewLink}`;
        }
        taskWorkflowNotice = `Task #${id}: Agent Review result ${result?.result_ref || ''} saved.`;
        render();
    } catch (error) {
        if (statusEl) statusEl.textContent = error.message || 'Could not save Agent Review result.';
        alert(error.message || 'Could not save Agent Review result.');
    } finally {
        if (button) button.disabled = false;
    }
}

