async function decisionAction(event, taskId, action, payload = {}) {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const id = Number(taskId);
    if (!id) return;
    const task = tasks.find(item => Number(item.id) === id) || {};
    const request = { action, ...(payload || {}) };
    if (action === 'done' && !request.outcome) {
        const outcome = prompt('What was the actual decision/outcome?');
        if (!outcome || !outcome.trim()) return;
        request.outcome = outcome.trim();
    }
    if (action === 'add_task') {
        const title = prompt('Linked task title:', `Task: ${taskDisplayTitle(task)}`);
        if (title === null) return;
        request.task_title = title.trim() || `Task: ${taskDisplayTitle(task)}`;
        const notes = prompt('Linked task notes/context:', '');
        if (notes !== null && notes.trim()) request.task_notes = notes.trim();
    }
    if (action === 'wait_external' && !request.waiting_on) {
        const waitingOn = prompt('Who or what is this waiting on?', task.waiting_on || 'External input');
        if (!waitingOn || !waitingOn.trim()) return;
        request.waiting_on = waitingOn.trim();
    }
    if (action === 'block' && !request.blocker) {
        const blocker = prompt('What is blocking this decision?');
        if (!blocker || !blocker.trim()) return;
        request.blocker = blocker.trim();
    }
    if (action === 'hide' && !confirm('Hide this decision from the active queue without deleting history?')) return;
    try {
        const result = await api.decisionAction(id, request);
        taskWorkflowNotice = result?.decision_event?.message
            ? `Decision #${id}: ${result.decision_event.message} Status: ${decisionStatusLabel(result.decision_event.status_after || 'created')}.`
            : `Decision #${id}: action completed.`;
        if (result?.task) {
            tasks = tasks.map(item => Number(item.id) === id ? { ...item, ...result.task } : item);
        }
        if (result?.linked_task) {
            const exists = tasks.some(item => Number(item.id) === Number(result.linked_task.id));
            tasks = exists
                ? tasks.map(item => Number(item.id) === Number(result.linked_task.id) ? { ...item, ...result.linked_task } : item)
                : [result.linked_task, ...tasks];
        }
        await loadData();
    } catch (error) {
        alert(error.message || 'Decision action failed.');
    }
}

