    const prompt = target === 'custom'
        ? `For content job ${jobId} (${title}), use the transcript and summary already stored in the BNA content library. Here is what I want you to do: `
        : `For content job ${jobId} (${title}), draft this as a ${target}. Use the transcript and summary already stored in the BNA content library.`;
