async function generateContentOutput(event, jobId, outputType, key = '') {
    event.stopPropagation();
    event.preventDefault();
    const feedbackKey = key && !key.includes(':') ? key : `${outputType}-${Number(jobId)}`;
    const correction = document.getElementById(`promptFeedback-${feedbackKey}`)?.value || '';
    const saveCurrentAsExample = Boolean(document.getElementById(`promptSaveExample-${feedbackKey}`)?.checked);
    const action = correction.trim() ? 'patch_prompt_regenerate_output' : 'generate_output';
    const cardKey = `${Number(jobId)}:${outputType}`;
    const button = event.currentTarget;
    button.disabled = true;
    contentGenerationStates = {
        ...contentGenerationStates,
        [cardKey]: {
            status: 'working',
            feedback: correction,
            message: correction.trim()
                ? 'Patching the saved prompt and regenerating the output...'
                : 'Regenerating the output...'
        }
    };
    render([], { force: true });
    try {
        const res = await api.contentJobAction(jobId, action, {
            output_type: outputType,
            feedback: correction,
            save_current_as_example: saveCurrentAsExample
        });
        applyContentJobGenerationResponse(jobId, outputType, res || {});
        contentGenerationStates = {
            ...contentGenerationStates,
            [cardKey]: {
                status: 'done',
                message: res?.message || 'Output updated in this card.'
            }
        };
        expandedContentJobIds.add(Number(jobId));
        selectedContentDetailJobId = Number(jobId);
        expandedPromptKey = cardKey;
        syncOperationsUrl();
        render([], { force: true });
        clearContentGenerationStateLater(cardKey);
        await loadData({ background: true });
    } catch (error) {
        contentGenerationStates = {
            ...contentGenerationStates,
            [cardKey]: {
                status: 'error',
                feedback: correction,
                message: error.message || 'Draft generation failed.'
            }
        };
        render([], { force: true });
        alert(error.message || 'Draft generation failed.');
    } finally {
        button.disabled = false;
    }
}

async function generateSelectedContentOutput(event, outputType) {
    event.stopPropagation();
    const ids = [...selectedContentJobIds];
    if (!ids.length) return alert('Select at least one content item first.');
    const label = CONTENT_OUTPUT_TYPES.find(type => type.id === outputType)?.label || outputType;
    const instruction = prompt(`Optional one-time instruction for this ${label}. This will not change the saved prompt:`, '') || '';
    const button = event.currentTarget;
    button.disabled = true;
    try {
        const res = await api.bulkGenerateContent({
            job_ids: ids,
            output_type: outputType,
            instruction
        });
        const firstJobId = Number(res?.output?.job_id || ids[0]);
        expandedContentJobIds.add(firstJobId);
        selectedContentDetailJobId = firstJobId;
        syncOperationsUrl();
        alert(res?.message || `${label} draft generated from ${ids.length} selected item(s).`);
        await loadData();
    } catch (error) {
        alert(error.message || 'Selected content generation failed.');
    } finally {
        button.disabled = false;
    }
}

async function approveContentOutput(event, outputId) {
    event.stopPropagation();
    const output = [
        ...contentJobs.flatMap(job => job.outputs || []),
        ...contentBundles.flatMap(bundle => bundle.outputs || [])
    ].find(item => Number(item.id) === Number(outputId));
    const message = ['facebook_post', 'linkedin_post', 'youtube_description'].includes(output?.output_type)
        ? 'Commit this social draft to Buffer as a draft so it can be scheduled there?'
        : output?.output_type === 'blog_draft'
            ? 'Approve this website blog draft and publish it to the BNA website?'
            : 'Approve this output and save it as a reusable example?';
    if (!confirm(message)) return;
    const button = event.currentTarget;
    button.disabled = true;
    try {
        const res = await api.contentOutputAction(
            outputId,
            'approve_publish',
            ['facebook_post', 'linkedin_post', 'youtube_description'].includes(output?.output_type) ? { publishNow: false } : {}
        );
        alert(res?.message || 'Approved.');
        await loadData();
    } catch (error) {
        alert(error.message || 'Approval failed.');
    } finally {
        button.disabled = false;
    }
}

