async function contentAction(event, jobId, action) {
    event.stopPropagation();
    try {
        const res = await api.contentJobAction(jobId, action);
        if (action === 'whatsapp_copy') {
            const text = res?.body || '';
            if (text) await navigator.clipboard?.writeText(text);
            alert(text ? 'WhatsApp copy copied.' : 'No WhatsApp draft found yet.');
            return;
        }
        if (action === 'facebook_draft') {
            alert(res?.message || 'Social draft created in Buffer.');
            await loadData();
            return;
        }
        if (action === 'tasks_from_recording') {
            if (res?.parse_run?.id) {
                intakeSelectedRunId = res.parse_run.id;
                currentView = 'tasks';
                taskFocus = 'decisions';
                taskWorkflowNotice = res?.message || `Parsed recording into run #${intakeSelectedRunId}; review any low-confidence items as Decisions.`;
                syncOperationsUrl();
            } else {
                alert(res?.message || 'Queued recording for task extraction.');
            }
            await loadData();
        }
    } catch (error) {
        alert(error.message || 'Content action failed.');
    }
}

async function parseMixedRecording(event, jobId, dryRun = false) {
    event.stopPropagation();
    const button = event.currentTarget;
    const instruction = prompt(
        dryRun
            ? 'Optional parse instruction for preview:'
            : 'Optional parse instruction before filing tasks/students:',
        'Separate my personal tasks, Codex coding tasks, student accountability, and Torah progress into the correct sections.'
    ) || '';
    button.disabled = true;
    try {
        const res = await api.parseMixedRecording(jobId, {
            dry_run: Boolean(dryRun),
            instruction
        });
        if (dryRun) {
            if (res?.parse_run?.id) {
                intakeSelectedRunId = res.parse_run.id;
                currentView = 'tasks';
                taskFocus = 'decisions';
                taskWorkflowNotice = `Preview parse run #${intakeSelectedRunId} created. Low-confidence items should be reviewed as Decisions.`;
                syncOperationsUrl();
                await loadData();
                return;
            }
            const parsed = res?.parsed || {};
            alert([
                'Parse preview only:',
                `Tasks: ${(parsed.tasks || []).length}`,
                `Student accountability: ${(parsed.accountability_events || []).length}`,
                `Group/Torah entries: ${(parsed.group_goal_entries || []).length}`,
                `Class notes: ${(parsed.class_notes || []).length}`,
                parsed.report?.summary ? `Summary: ${parsed.report.summary}` : ''
            ].filter(Boolean).join('\n'));
            return;
        }
        if (res?.parse_run?.id) {
            intakeSelectedRunId = res.parse_run.id;
            currentView = 'tasks';
            taskFocus = 'decisions';
            taskWorkflowNotice = `Parsed and filed safe items from run #${intakeSelectedRunId}; unresolved items are Decisions.`;
            syncOperationsUrl();
            await loadData();
            return;
        }
        const counts = res?.counts || {};
        if (res?.skipped) {
            alert([
                'Already parsed:',
                `Tasks: ${counts.tasks || 0}`,
                `Student accountability: ${counts.accountability_events || 0}`,
                `Group/Torah entries: ${counts.group_goal_entries || 0}`,
                `Torah daily entries: ${counts.torah_learning_entries || 0}`
            ].join('\n'));
            return;
        }
        alert([
            'Parsed and filed:',
            `Tasks: ${counts.tasks || 0}`,
            `Student accountability: ${counts.accountability_events || 0}`,
            `Group/Torah entries: ${counts.group_goal_entries || 0}`,
            `Torah daily entries: ${counts.torah_learning_entries || 0}`,
            res?.report?.summary ? `Summary: ${res.report.summary}` : ''
        ].filter(Boolean).join('\n'));
        await loadData();
    } catch (error) {
        alert(error.message || 'Mixed recording parse failed.');
    } finally {
        button.disabled = false;
    }
}

