async function fetchAssignmentMetadata(event) {
    event?.stopPropagation?.();
    const input = document.getElementById('assignment-youtube');
    const status = document.getElementById('assignment-youtube-meta-status');
    const titleInput = document.getElementById('assignment-title');
    const url = input?.value || '';
    if (!url.trim()) return alert('Paste a YouTube URL first.');
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    if (status) status.textContent = 'Fetching YouTube metadata...';
    try {
        const result = await api.fetchAssignmentYoutubeMetadata({ youtube_url: url });
        const metadata = result?.metadata || {};
        if (metadata.title && titleInput && !titleInput.value.trim()) {
            titleInput.value = metadata.title;
        }
        if (status) {
            status.textContent = [
                metadata.title ? `Title: ${metadata.title}` : '',
                metadata.channel ? `Channel: ${metadata.channel}` : '',
                result?.youtube_video_id ? `Video ID: ${result.youtube_video_id}` : ''
            ].filter(Boolean).join(' - ') || 'Metadata fetched.';
        }
    } catch (error) {
        if (status) status.textContent = '';
        alert(error.message || 'Could not fetch YouTube metadata.');
    } finally {
        if (button) button.disabled = false;
    }
}

async function refreshAssignmentYoutubeMetadata(event, assignmentId) {
    event?.stopPropagation?.();
    const assignment = assignments.find(item => Number(item.id) === Number(assignmentId));
    const youtubeUrl = assignment?.youtube_url || '';
    if (!youtubeUrl) return alert('This assignment does not have a YouTube URL.');
    const button = event?.currentTarget;
    if (button) button.disabled = true;
    try {
        const result = await api.fetchAssignmentYoutubeMetadata({ youtube_url: youtubeUrl });
        await api.updateAssignment(assignmentId, {
            youtube_video_id: result?.youtube_video_id || null,
            youtube_metadata_json: result?.metadata || {},
        });
        await loadData();
        alert(result?.metadata?.title ? `Metadata updated: ${result.metadata.title}` : 'Metadata updated.');
    } catch (error) {
        alert(error.message || 'Could not refresh YouTube metadata.');
    } finally {
        if (button) button.disabled = false;
    }
}

