async function createStudentAssignment(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const button = form.querySelector('button[type="submit"]');
    const studentIds = [...form.querySelectorAll('input[name="student_ids"]:checked')]
        .map(input => Number(input.value))
        .filter(Number.isFinite);
    if (!studentIds.length) return alert('Choose at least one student.');
    const videoProcessingRequested = Boolean(form.elements.queue_video_download?.checked);
    const payload = {
        title: form.elements.title?.value || '',
        youtube_url: form.elements.youtube_url?.value || '',
        material_url: form.elements.material_url?.value || '',
        instructions: form.elements.instructions?.value || '',
        prompt_patch_text: form.elements.prompt_patch_text?.value || '',
        teacher_instruction_patch: form.elements.teacher_instruction_patch?.value || '',
        language_mode: form.elements.language_mode?.value || 'mixed',
        worksheet_type: form.elements.worksheet_type?.value || 'reflection',
        schedule_text: form.elements.schedule_text?.value || '',
        google_classroom_sync: Boolean(form.elements.google_classroom_sync?.checked),
        google_calendar_sync: Boolean(form.elements.google_calendar_sync?.checked),
        queue_video_download: videoProcessingRequested,
        video_processing_requested: videoProcessingRequested,
        project_key: currentWorkspaceKey() === 'rabbi_sheller_provider' ? 'one_time_mishnah_class' : 'bna',
        workspace_key: currentWorkspaceKey(),
        student_ids: studentIds,
    };
    if (!payload.title.trim()) return alert('Title is required.');
    if (button) button.disabled = true;
    try {
        const result = await api.createAssignment(payload);
        form.reset();
        selectedStudentId = studentIds[0] || selectedStudentId;
        alert(result?.assignment?.schedule_plan?.needs_review
            ? 'Assignment created. Review the parsed schedule before Google sync.'
            : 'Assignment created.');
        await loadData();
    } catch (error) {
        alert(error.message || 'Could not create assignment.');
    } finally {
        if (button) button.disabled = false;
    }
}

