async function sendParentAccessLink(event, contactType, contactId, mode = 'email') {
    event?.stopPropagation();
    const channel = mode === 'open' ? 'open' : mode === 'whatsapp' ? 'whatsapp' : 'email';
    if (
        channel === 'whatsapp'
        && !confirm('Send this short-lived parent portal login link by WhatsApp now?')
    ) {
        return;
    }
    let portalWindow = null;
    if (channel === 'open') {
        portalWindow = window.open('', '_blank');
    }
    try {
        const result = await api.sendParentAccessLink({
            contact_type: contactType,
            contact_id: contactId,
            send_email: channel === 'email',
            send_whatsapp: channel === 'whatsapp',
            ...(channel === 'whatsapp' ? { confirm: 'SEND_WHATSAPP' } : {})
        });
        const copied = await tryCopyText(result?.url);
        if (channel === 'open') {
            if (result?.url && portalWindow) {
                portalWindow.location.href = result.url;
            } else if (result?.url) {
                window.open(result.url, '_blank', 'noopener,noreferrer');
            } else if (portalWindow) {
                portalWindow.close();
            }
        }
        await loadData();
        const copyNote = copied ? ' and copied' : '; clipboard copy was unavailable';
        if (channel === 'open') {
            alert(result?.url
                ? `Parent portal opened in a new tab${copyNote}. No email was sent.`
                : 'Parent portal link was created, but no URL was returned.');
            return;
        }
        if (channel === 'whatsapp') {
            alert(result?.whatsapp_sent
                ? `Parent portal link was sent by WhatsApp${copyNote}.`
                : `Parent portal link was created${copyNote}. WhatsApp did not send automatically${result?.whatsapp_error ? `: ${result.whatsapp_error}` : '.'}`);
            return;
        }
        alert(result?.email_sent
            ? `Parent portal link was emailed to ${result?.parent_email || 'the parent email on file'}${copyNote}. The parent can open it directly without typing their email again.`
            : `Parent portal link was created${copyNote}. Email did not send automatically.`);
    } catch (error) {
        if (portalWindow) portalWindow.close();
        alert(error.message || 'Could not create parent portal link.');
    }
}

async function sendParentPasswordSetup(event, contactType, contactId, dryRun = true) {
    event?.stopPropagation();
    if (
        !dryRun
        && !confirm('Email this parent a password setup/reset link now? This is a single-family send, not a bulk campaign.')
    ) {
        return;
    }
    const button = event?.currentTarget;
    const originalText = button?.textContent || '';
    try {
        if (button) {
            button.disabled = true;
            button.textContent = dryRun ? 'Previewing...' : 'Sending...';
        }
        const result = await api.sendParentPasswordSetup({
            contact_type: contactType,
            contact_id: contactId,
            dry_run: Boolean(dryRun),
            ...(dryRun ? {} : { confirm: 'SEND_PARENT_PASSWORD_SETUP' })
        });
        if (dryRun) {
            const preview = result?.password_setup_preview || {};
            alert(`Password setup email preview ready for ${preview.parent_email || 'the parent email on file'}. No email was sent. Subject: ${preview.subject || 'Set or reset your Bnei Neviim Academy parent portal password'}`);
            return;
        }
        await loadData({ background: true });
        alert(result?.email_sent
            ? `Parent password setup/reset email sent to ${result?.parent_email || 'the parent email on file'}.`
            : `Parent password setup/reset link was created, but email did not send automatically${result?.email_error ? `: ${result.email_error}` : '.'}`);
    } catch (error) {
        alert(error.message || 'Could not prepare parent password setup email.');
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = originalText;
        }
    }
}

